// ── IMPORT / UPDATE ───────────────────────────────────────────
function buildLevelConfig(cfg){
 const lc={};
 if(cfg.nivel_maximo)           lc.nivel_maximo=parseInt(cfg.nivel_maximo)||20;
 if(cfg.hp_base)                lc.hp_base=parseInt(cfg.hp_base)||100;
 if(cfg.hp_por_nivel)           lc.hp_por_nivel=parseInt(cfg.hp_por_nivel)||10;
 if(cfg.pontos_attr_por_nivel)  lc.pontos_attr_por_nivel=parseInt(cfg.pontos_attr_por_nivel)||0;
 if(cfg.hp_attr)                lc.hp_attr=cfg.hp_attr; // atributo que contribui com HP
 if(cfg.hp_attr_mult)           lc.hp_attr_mult=parseFloat(cfg.hp_attr_mult)||0; // multiplicador
 if(cfg.aumentos_automaticos_json){try{lc.aumentos_automaticos=JSON.parse(cfg.aumentos_automaticos_json);}catch(e){}}
 if(cfg.habilidades_por_nivel_json){try{lc.habilidades_por_nivel=JSON.parse(cfg.habilidades_por_nivel_json);}catch(e){}}
 return Object.keys(lc).length?lc:null;
}

// Calcula hp_max de um personagem usando atributos (se configurado)
function calcularHpMaxComAtributos(lc, charAtributos, hpMaxExplicito) {
  if (hpMaxExplicito) return hpMaxExplicito; // HP explícito tem prioridade
  const base = lc?.hp_base || 100;
  const attrNome = lc?.hp_attr;
  const mult = parseFloat(lc?.hp_attr_mult) || 0;
  if (attrNome && mult && charAtributos) {
    const attrVal = parseFloat(charAtributos[attrNome]) || 0;
    return Math.ceil(base + attrVal * mult);
  }
  return base;
}

function buildTheme(cfg){
 const level_config=buildLevelConfig(cfg);
 return{
   preto:cfg.theme_preto||'#080c10',
   escuro:cfg.theme_escuro||'#0f1520',
   painel:cfg.theme_painel||'#141d2b',
   borda:cfg.theme_borda||'#1e2d42',
   cinza:cfg.theme_cinza||'#2a3a50',
   texto:cfg.theme_texto||'#c8d8e8',
   suave:cfg.theme_suave||'#7a92aa',
   primario:cfg.theme_primario||'#4fa3d1',
   primario_v:cfg.theme_primario_v||'#7ec8f0',
   destaque:cfg.theme_destaque||'#c8a84b',
   destaque_v:cfg.theme_destaque_v||'#f0cc6a',
   perigo:cfg.theme_perigo||'#c0392b',
   sucesso:cfg.theme_sucesso||'#27ae60',
   especial:cfg.theme_especial||'#7b2fbe',
   animation_css: cfg.animation_css || '',
   card_icon_svg: cfg.card_icon_svg || '',
   animation_loading_svg: cfg.animation_loading_svg || '',
   animation: cfg.animation || 'flame',
   font_display: cfg.font_display || 'Cinzel',
   font_text: cfg.font_text || 'Crimson Text',
   font_url: cfg.font_url || '',
   description: cfg.description || '',
   ...(level_config?{level_config}:{})
 };
}



async function insertSection(rpgId,section,rows,levelConfig){
 const P=[];
 if(section==='characters') rows.forEach(c=>{
   const tipoChar = c.tipo||'jogador';
   const ca={tipo:tipoChar,cor:c.cor||'#4fa3d1'};
   if(tipoChar==='npc'||tipoChar==='criatura'){ca.tipo_personagem='npc';ca.npc_generico=true;if(!c.cor)ca.cor='#e74c3c';}
   if(c.img_url)ca.img_url=normalizeImgUrl(c.img_url);
   if(c.background)ca.background=c.background;
   if(c.equipamentos)ca.equipamentos=c.equipamentos;
   if(c.companheiro)ca.companheiro=c.companheiro;
   // Suporta campo novo (atributos_json) e campo antigo (custom_attrs) para compatibilidade
   const atribRaw = c.atributos_json || c.custom_attrs;
   if(atribRaw){try{ca.atributos=typeof atribRaw==='string'?JSON.parse(atribRaw):atribRaw;}catch(e){}}
   // Level fields
   const nivel = parseInt(c.nivel)||1;
   const lc = levelConfig||{};
   const hp_base = lc.hp_base||100;
   const hp_por_nivel = lc.hp_por_nivel||0;
   const hp_max = calcularHpMaxComAtributos(lc, ca.atributos, c.hp_max ? +c.hp_max : null) + (nivel-1)*(lc.hp_por_nivel||0);
   const hp_atual_raw = c.hp_atual!=null ? +c.hp_atual : hp_max;
   ca.nivel = nivel;
   ca.hp_max = hp_max;
   ca.xp = +c.xp||0;
   ca.pontos_attr = +c.pontos_attr||0;
   P.push(sb('characters',{method:'POST',body:JSON.stringify({
     rpg_id:rpgId, nome:c.nome, hp_atual:hp_atual_raw, custom_attrs:ca,
     nivel:nivel, hp_max:hp_max, xp:+c.xp||0, pontos_attr:+c.pontos_attr||0
   })}));
 });
 if(section==='skills')    rows.forEach(s=>{
    let efeitosBonus = null;
    if(s.efeitos_bonus_json){ try{ efeitosBonus = JSON.parse(s.efeitos_bonus_json); }catch(e){} }
    P.push(sb('skills',{method:'POST',body:JSON.stringify({
      rpg_id:rpgId,
      personagem:s.personagem,
      habilidade:s.habilidade,
      efeito:s.efeito||'',
      formula_dano:s.formula_dano||null,
      custo_rsv:s.custo_rsv||null,
      cooldown_turnos:parseInt(s.cooldown_turnos)||0,
      tipo_dano:s.tipo_dano||'fisico',
      alcance_celulas:s.alcance_celulas!==''&&s.alcance_celulas!=null?parseInt(s.alcance_celulas):null,
      atributo_base:s.atributo_base||null,
      alvo_tipo:s.alvo_tipo||'inimigo',
      efeitos_bonus:efeitosBonus,
      critico_positivo:s.critico_positivo||null,
      critico_negativo:s.critico_negativo||null,
    })}));
  });
 if(section==='lore')      rows.forEach(l=>P.push(sb('lore',{method:'POST',body:JSON.stringify({rpg_id:rpgId,secao:l.secao,titulo:l.titulo,conteudo:l.conteudo||''})})));
 if(section==='mapas')     rows.forEach(m=>P.push(sb('mapas',{method:'POST',body:JSON.stringify({
   rpg_id:rpgId, map_id:m.map_id, nome:m.nome, tipo:m.tipo||'geral',
   img_url:m.img_url||'', escala_val:+m.escala_val||1,
   escala_unit:m.escala_unit||'m', grid:+m.grid||20,
   parent_map_id:m.parent_map_id||null,
   locais: m.locais ? (typeof m.locais==='string'?JSON.parse(m.locais):m.locais) : [],
   render_data: m.render_data ? (typeof m.render_data==='string'?JSON.parse(m.render_data):m.render_data) : null,
 })})));
 if(section==='attr_defs') rows.forEach(a=>P.push(sb('attr_defs',{method:'POST',body:JSON.stringify({rpg_id:rpgId,nome:a.nome||a.label||a.attr_key,tipo:a.tipo||'text',opcoes:a.opcoes||null,ordem:+a.ordem||1,categoria:a.categoria||'basico'})})));
 await Promise.all(P);
}

async function importRPG(payload, mapasJSON=null){
 const cfg=(payload.config||[])[0];
 if(!cfg||!cfg.rpg_id)throw new Error('rpg_id não encontrado no config.');
 const rpgId=cfg.rpg_id;
 const existing=await sb(`rpg_registry?rpg_id=eq.${encodeURIComponent(rpgId)}&select=rpg_id`);
 if(existing&&existing.length)throw new Error(`RPG "${rpgId}" já existe.`);
 
 const theme=buildTheme(cfg);
 const levelConfig=buildLevelConfig(cfg);
 const ownerId=SESSION?.user?.id||null;
 const registryBody={rpg_id:rpgId,name:cfg.name,owner_id:ownerId,theme_json:theme};
 if(levelConfig) registryBody.level_config=levelConfig;
 await sb('rpg_registry',{method:'POST',body:JSON.stringify(registryBody)});
 
 // Vincular criador como mestre automaticamente — OBRIGATÓRIO antes de inserir characters
 if (!ownerId) throw new Error('Usuário não autenticado.');
 await sb('rpg_members', {
   method: 'POST',
   body: JSON.stringify({
     rpg_id: rpgId,
     player_id: ownerId,
     nickname: SESSION?.nickname || SESSION?.user?.email || 'mestre',
     role: 'mestre',
     permissoes: {}
   })
 });

 for(const sec of['characters','skills','lore','attr_defs','mapas']){
   if(payload[sec]&&payload[sec].length)await insertSection(rpgId,sec,payload[sec],theme.level_config);
 }
 // A4: Importar mapeamento de atributos
 if(payload.attr_grupos&&payload.attr_grupos.length){
   const rows=payload.attr_grupos.filter(r=>r.nome_customizado&&r.grupo_base);
   const validGrupos=['forca','destreza','constituicao','inteligencia'];
   const upserts=rows.filter(r=>validGrupos.includes(r.grupo_base.toLowerCase().trim()))
     .map(r=>({rpg_id:rpgId,nome_customizado:r.nome_customizado.trim(),grupo_base:r.grupo_base.toLowerCase().trim()}));
   if(upserts.length){
     await sb('atributos_grupos',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates'},body:JSON.stringify(upserts)});
     // Atualizar cache local se RPG_DATA estiver carregado
     if(typeof _mapeamentoCache!=='undefined')delete _mapeamentoCache[rpgId];
   }
 }
 // A4: Importar vocabulário temático
 if(payload.vocab_tematico&&payload.vocab_tematico.length){
   const validTipos=['prefixo_material','adjetivo_qualidade','nome_origem'];
   const upserts=payload.vocab_tematico.filter(r=>r.tipo&&r.valor&&validTipos.includes(r.tipo.trim()))
     .map(r=>({rpg_id:rpgId,tipo:r.tipo.trim(),valor:r.valor.trim()}));
   if(upserts.length){
     await sb('vocabulario_tematico',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates'},body:JSON.stringify(upserts)});
   }
 }
 // Importar mapas gerados por IA (arquivo JSON separado)
 if (mapasJSON && mapasJSON.length) {
   await importarMapasJSON(rpgId, mapasJSON);
 }
 return rpgId;
}


async function updateRPG(rpgId,payload){
 const sections=Object.keys(payload).filter(k=>payload[k]&&payload[k].length);
 let levelConfig=null;
 for(const sec of sections){
   if(sec==='config'){
     const cfg=payload.config[0];
     const theme = buildTheme(cfg);
     levelConfig=theme.level_config||null;
     await sb(`rpg_registry?rpg_id=eq.${encodeURIComponent(rpgId)}`,{method:'PATCH',body:JSON.stringify({
       name:cfg.name||rpgId,
       theme_json:theme
     })});
   }
   else{
     const TABLE_MAP={characters:'characters',skills:'skills',lore:'lore',attr_defs:'attr_defs'};
     const tbl=TABLE_MAP[sec];
     if(tbl){
       await sb(`${tbl}?rpg_id=eq.${encodeURIComponent(rpgId)}`,{method:'DELETE'});
       await insertSection(rpgId,sec,payload[sec],levelConfig);
     }
   }
 }
 return sections;
}


// ── REALTIME ──────────────────────────────────────────────────
function iniciarRealtime(rpgId){
 fecharRealtime();
 let _reconectando=false, _tentativas=0, _timerReconexao=null;

 function conectar(){
   let ws;
   try{ ws=new WebSocket(`${SUPABASE_URL.replace('https','wss')}/realtime/v1/websocket?apikey=${SUPABASE_KEY}&vsn=1.0.0`); }catch(e){return;}
   realtimeWS=ws;

   ws.onopen=()=>{
     _tentativas=0; _reconectando=false;
     // Ocultar banner de reconexão
     const banner=document.getElementById('reconexao-banner');
     if(banner)banner.classList.remove('visible');
     const join=(topic)=>ws.send(JSON.stringify({topic,event:'phx_join',payload:{config:{broadcast:{self:false},presence:{key:''}}},ref:'1'}));
     join(`realtime:public:characters:rpg_id=eq.${rpgId}`);
     join(`realtime:public:lore:rpg_id=eq.${rpgId}`);
     join(`realtime:public:skills:rpg_id=eq.${rpgId}`);
     join(`realtime:public:attr_defs:rpg_id=eq.${rpgId}`);
     join(`realtime:public:rpg_registry:rpg_id=eq.${rpgId}`);
     join(`realtime:public:batalhas:rpg_id=eq.${rpgId}`);
     join(`realtime:public:criativos:rpg_id=eq.${rpgId}`);
     join(`realtime:public:mapas:rpg_id=eq.${rpgId}`);
     const dot=document.getElementById('realtime-dot');
     if(dot){dot.style.display='inline-block';dot.title='Tempo real conectado';}
     chatIniciar(rpgId, ws);
   };

   ws.onmessage=(e)=>{
     try{
       const msg=JSON.parse(e.data);
       // Chat broadcast
       if(msg.event==='broadcast'&&msg.payload?.event==='chat_msg'){chatReceberMensagem(msg.payload.payload);return;}
       if(msg.event==='broadcast'&&msg.payload?.event==='chat_presence'){chatReceberPresenca(msg.payload.payload);return;}
       if(msg.event==='broadcast'&&msg.payload?.event==='anim_ataque'){animReceberBroadcast(msg.payload.payload);return;}
       if(msg.event==='broadcast'&&msg.payload?.event==='token_move'){tokenMoveReceber(msg.payload.payload);return;}
       if(msg.event==='broadcast'&&msg.payload?.event==='combate_evento'){combateReceberBroadcast(msg.payload.payload);return;}
       if(!msg.payload||!msg.payload.record)return;
       const rec=msg.payload.record;
       const ev=msg.event;
       const topic=msg.topic||'';

       // ── CHARACTERS ──
       if(topic.includes('characters')){
         if(typeof rec.custom_attrs==='string'){try{rec.custom_attrs=JSON.parse(rec.custom_attrs);}catch(e){rec.custom_attrs={};}}
         else if(!rec.custom_attrs||typeof rec.custom_attrs!=='object'){rec.custom_attrs={};}
         if(!rec.map_positions||typeof rec.map_positions!=='object')rec.map_positions={};
         if(!Array.isArray(rec.buffs))rec.buffs=[];

         if(ev==='DELETE'){
           const oldRec=msg.payload.old_record||{};
           const nome=oldRec.nome||rec.nome;
           RPG_DATA.characters=RPG_DATA.characters.filter(c=>!(c.nome===nome&&c.rpg_id===rec.rpg_id));
           renderCharButtons();
           mostrarToast(`✕ ${nome} removido`,'');
           return;
         }
         const idx=RPG_DATA.characters.findIndex(c=>c.nome===rec.nome&&c.rpg_id===rec.rpg_id);
         if(idx>=0){
           RPG_DATA.characters[idx]=rec;
           if(CHAR_VIEW===rec.nome)renderCharView(rec.nome);
           if(ATTR_VIEW===rec.nome)renderAttrView(rec.nome);
           mostrarToast(`↺ ${rec.nome} atualizado`,'');
         } else if(ev==='INSERT'){
           RPG_DATA.characters.push(rec);
           mostrarToast(`✦ ${rec.nome} adicionado`,'sucesso');
         }
         renderCharButtons();
         if(MAPA_STATE.mapaAtualId){const mapas=RPG_DATA.mapas||[];const entry=mapas.find(l=>l.mapa.map_id===MAPA_STATE.mapaAtualId);if(entry)mapaRenderTokens(entry.mapa);mapaRenderStatus();}
       }

       // ── SKILLS ──
       if(topic.includes('skills')){
         if(ev==='DELETE'){
           const oldRec=msg.payload.old_record||{};
           const skId=oldRec.id||rec.id;
           RPG_DATA.skills=RPG_DATA.skills.filter(s=>s.id!==skId);
         } else {
           if(typeof rec.animacao==='string'){try{rec.animacao=JSON.parse(rec.animacao);}catch(e){rec.animacao=null;}}
           if(typeof rec.efeitos_bonus==='string'){try{rec.efeitos_bonus=JSON.parse(rec.efeitos_bonus);}catch(e){rec.efeitos_bonus=[];}}
           const idx=RPG_DATA.skills.findIndex(s=>s.id===rec.id);
           if(idx>=0)RPG_DATA.skills[idx]=rec;
           else RPG_DATA.skills.push(rec);
         }
         if(CHAR_VIEW)renderCharView(CHAR_VIEW);
       }

       // ── LORE ──
       if(topic.includes('lore')){
         if(ev==='DELETE'){
           const oldRec=msg.payload.old_record||{};
           const lId=oldRec.id||rec.id;
           RPG_DATA.lore=RPG_DATA.lore.filter(l=>l.id!==lId);
         } else {
           const idx=RPG_DATA.lore.findIndex(l=>l.id===rec.id);
           if(idx>=0)RPG_DATA.lore[idx]=rec;
           else RPG_DATA.lore.push(rec);
         }
         if(typeof renderLore==='function'&&document.getElementById('lore-items'))renderLore();
       }

       // ── ATTR_DEFS ──
       if(topic.includes('attr_defs')){
         if(ev==='DELETE'){
           const oldRec=msg.payload.old_record||{};
           const adId=oldRec.id||rec.id;
           RPG_DATA.attrDefs=(RPG_DATA.attrDefs||[]).filter(a=>a.id!==adId);
         } else {
           const idx=(RPG_DATA.attrDefs||[]).findIndex(a=>a.id===rec.id);
           if(idx>=0)RPG_DATA.attrDefs[idx]=rec;
           else{if(!RPG_DATA.attrDefs)RPG_DATA.attrDefs=[];RPG_DATA.attrDefs.push(rec);}
         }
         if(CHAR_VIEW)renderCharView(CHAR_VIEW);
         if(ATTR_VIEW)renderAttrView(ATTR_VIEW);
       }

       // ── RPG_REGISTRY ──
       if(topic.includes('rpg_registry')){
         // batalha_estado (jsonb — já chega como objeto)
         if(rec.batalha_estado!==undefined){
           try{
             const bd = rec.batalha_estado || {};
             if(typeof batalhaReceberEstadoRemoto==='function')batalhaReceberEstadoRemoto(bd);
           }catch(e){}
         }
         // criativos_pendentes removido — tabela criativos é a fonte de verdade
         // arena_estado — sync para quem está fora da arena
         if(rec.arena_estado!==undefined){
           try{
             const raw=rec.arena_estado;
             AR.estado=typeof raw==='object'?raw:JSON.parse(raw||'{}');
             if(!AR.estado.log)AR.estado.log=[];
             if(typeof renderMesa==='function')renderMesa();
           }catch(e){}
         }
         // config (permissões)
         if(rec.config!==undefined){
           try{
             const raw=rec.config;
             const cfg=typeof raw==='object'?raw:JSON.parse(raw||'{}');
             if(cfg.permissoes&&RPG_DATA.myRole!=='mestre'){
               RPG_DATA.myPermissoes=cfg.permissoes[RPG_DATA.userId]||{};
             }
           }catch(e){}
         }
       }

       // ── BATALHAS ──
       if(topic.includes('batalhas')){
         batalhaReceberLinhaRemota(rec);
       }

       // ── CRIATIVOS ──
       if(topic.includes('criativos')){
         criativoReceberLinhaRemota(rec);
       }

       // ── MAPAS ──
       if(topic.includes('mapas')){
         const parseMapa = (r) => ({
           id: r.id, rpg_id: r.rpg_id,
           mapa: {
             map_id: r.map_id, nome: r.nome, img_url: r.img_url||'',
             escala_val: r.escala_val??1.5, escala_unit: r.escala_unit||'m', grid: r.grid??20,
             parent_map_id: r.parent_map_id||null, tipo: r.tipo||'geral',
             zona_x: r.zona_x, zona_y: r.zona_y,
             zona_w_percent: r.zona_w_percent, zona_h_percent: r.zona_h_percent,
             largura_total: r.largura_total||null, altura_total: r.altura_total||null,
             largura_real: r.largura_real||null, altura_real: r.altura_real||null,
             representar_pct: r.representar_pct??100,
             locais: Array.isArray(r.locais)?r.locais:(typeof r.locais==='string'?JSON.parse(r.locais||'[]'):[]),
             render_data: r.render_data||null,
           }
         });
         if(ev==='DELETE'){
           const oldRec=msg.payload.old_record||{};
           const mapId=oldRec.map_id||rec.map_id;
           RPG_DATA.mapas=(RPG_DATA.mapas||[]).filter(l=>l.mapa.map_id!==mapId);
           if(MAPA_STATE.mapaAtualId===mapId){MAPA_STATE.mapaAtualId=null;}
         } else {
           const entry=parseMapa(rec);
           const idx=(RPG_DATA.mapas||[]).findIndex(l=>l.mapa.map_id===rec.map_id);
           if(idx>=0) RPG_DATA.mapas[idx]=entry;
           else {if(!RPG_DATA.mapas)RPG_DATA.mapas=[];RPG_DATA.mapas.push(entry);}
           if(MAPA_STATE.mapaAtualId===rec.map_id){renderMapaViewer();}
         }
         if(document.getElementById('mapa-lista'))renderMapasTab();
       }

     }catch(err){}
   };

   ws.onerror=()=>{};
   ws.onclose=()=>{
     const dot=document.getElementById('realtime-dot');
     if(dot){dot.style.display='none';dot.title='Desconectado';dot.classList.remove('reconectando');}
     if(!_reconectando){
       _reconectando=true;
       const banner=document.getElementById('reconexao-banner');
       if(banner)banner.classList.add('visible');
       const delay=Math.min(1000*Math.pow(2,_tentativas),30000);
       _tentativas++;
       _timerReconexao=setTimeout(()=>{if(realtimeWS===ws||realtimeWS===null){realtimeWS=null;conectar();}},delay);
     }
   };
 }

 if(_timerReconexao){clearTimeout(_timerReconexao);_timerReconexao=null;}
 conectar();
}


function fecharRealtime(){
 if(realtimeWS){try{realtimeWS.close();}catch(e){}realtimeWS=null;}
 document.getElementById('realtime-dot').style.display='none';
 if(CHAT._presenceInterval){clearInterval(CHAT._presenceInterval);CHAT._presenceInterval=null;}
 CHAT.online = []; CHAT.rpgId = null;
 chatAtualizarOnline();
}


// ── PERMISSÕES — funções auxiliares ──────────────────────────
function temPermissao(chave) {
  if (RPG_DATA?.myRole === 'mestre') return true;
  const perm = RPG_DATA?.myPermissoes || {};
  const padrao = (PERMISSOES_CONFIG?.find(p => p.key === chave)?.padrao) ?? false;
  return perm[chave] !== undefined ? perm[chave] : padrao;
}

function podeEditarPersonagem(nomePersonagem) {
  if (RPG_DATA?.myRole === 'mestre') return true;
  return RPG_DATA?.linked === nomePersonagem;
}

// Retorna o estado de batalha do ponto de vista de um jogador:
// 'livre'       → mestre, ou em batalha ativa e é o turno do personagem
// 'fora_combate'→ jogador, sem batalha ativa
// 'outro_turno' → jogador, batalha ativa mas não é o turno dele
function _estadoBatalhaJogador(nomePersonagem) {
  // ── Arena mode: usar AR.iniciativa em vez de BATALHA_ATUAL_ID ──
  if (typeof AR !== 'undefined' && AR && AR.session) {
    if (AR.myRole === 'mestre') return 'livre';
    const ini = AR.iniciativa;
    if (!ini || !ini.ativa || ini.fase !== 'combate') return 'fora_combate';
    const atual = ini.ordem && ini.ordem[ini.ordemAtual];
    if (atual && atual.nome === nomePersonagem) return 'livre';
    return 'outro_turno';
  }
  // ── Campanha normal ───────────────────────────────────────────
  if (RPG_DATA?.myRole === 'mestre') return 'livre';
  // Procura em TODAS as batalhas ativas a que inclui este personagem.
  // Isso garante que o jogador responde à sua batalha mesmo que BATALHA_ATUAL_ID
  // esteja apontando para outra batalha (ex: mestre navegou para outro mapa).
  const bs = Object.values(MAPA_STATE.batalhas).find(b =>
    b.ativa && b.participantes?.some(p => p.nome === nomePersonagem)
  );
  if (!bs) return 'fora_combate';
  if (bs.fase === 'iniciativa' || bs.fase === 'empate') return 'outro_turno';
  if (bs.fase === 'combate' && !bs.pausada) {
    const atual = bs.participantes[bs.ordemAtual];
    if (atual && atual.nome === nomePersonagem) return 'livre';
    return 'outro_turno';
  }
  return 'fora_combate';
}


// ═══════════════════════════════════════════════════════════════
// 💬 CHAT — Mensagens via Supabase Realtime Broadcast (sem tabela dedicada)
// ═══════════════════════════════════════════════════════════════

// ── Chat: persistência (localStorage + 1 linha no lore, cap 1000 chars) ──
const CHAT_TTL       = 60 * 60 * 1000; // 1 hora
const CHAT_CHAR_CAP  = 1000;            // cap de caracteres no banco
const CHAT_LORE_SEC  = 'chat_cache';

// Serializa mensagens para string compacta, cortando as mais antigas
// até caber em CHAT_CHAR_CAP caracteres
function chatSerializar(msgs) {
  const agora = Date.now();
  let recentes = msgs.filter(m => agora - (m.ts || 0) < CHAT_TTL);
  // Descarta mais antigas até caber no cap
  while (recentes.length > 0) {
    const s = JSON.stringify(recentes);
    if (s.length <= CHAT_CHAR_CAP) break;
    recentes.shift(); // remove a mais antiga
  }
  return JSON.stringify(recentes);
}

function chatSalvarLocal(rpgId, msgs) {
  try { localStorage.setItem('chat_hist_' + rpgId, chatSerializar(msgs)); } catch(e) {}
}
function chatLerLocal(rpgId) {
  try {
    const raw = localStorage.getItem('chat_hist_' + rpgId);
    if (!raw) return [];
    const agora = Date.now();
    return JSON.parse(raw).filter(m => agora - (m.ts || 0) < CHAT_TTL);
  } catch(e) { return []; }
}

// Salva no banco (debounced — máx 1 write a cada 30s)
CHAT._saveTimer   = null;
CHAT._loreId      = null; // id da linha lore já existente

function chatAgendarSalvoBanco() {
  if (CHAT._saveTimer) return; // já agendado
  CHAT._saveTimer = setTimeout(async () => {
    CHAT._saveTimer = null;
    if (!CHAT.rpgId) return;
    const conteudo = chatSerializar(CHAT.msgs);
    try {
      if (CHAT._loreId) {
        // Atualiza linha existente
        await sb(`lore?id=eq.${encodeURIComponent(CHAT._loreId)}`,
          { method: 'PATCH', body: JSON.stringify({ conteudo }) });
      } else {
        // Cria linha nova (pode já existir por race condition — ignora erro)
        const [row] = await sb('lore', {
          method: 'POST',
          headers: { 'Prefer': 'return=representation' },
          body: JSON.stringify({ rpg_id: CHAT.rpgId, secao: CHAT_LORE_SEC, titulo: '_cache', conteudo })
        });
        if (row?.id) CHAT._loreId = row.id;
      }
    } catch(e) {} // falha silenciosa — localStorage ainda tem os dados
  }, 30000); // 30 segundos
}

async function chatCarregarDoBanco(rpgId) {
  try {
    const rows = await sb(`lore?rpg_id=eq.${encodeURIComponent(rpgId)}&secao=eq.${CHAT_LORE_SEC}&limit=1`);
    if (!rows?.length) return [];
    CHAT._loreId = rows[0].id;
    const agora = Date.now();
    return JSON.parse(rows[0].conteudo || '[]').filter(m => agora - (m.ts || 0) < CHAT_TTL);
  } catch(e) { return []; }
}

async function chatIniciar(rpgId, wsRef) {
  if (!wsRef) return;
  CHAT._loreId = null;
  // 1) Carrega localStorage imediatamente (sem latência)
  const local = chatLerLocal(rpgId);
  CHAT.msgs = local; CHAT.naoLidos = 0; CHAT.rpgId = rpgId; CHAT.online = [];
  chatRenderizar();
  // 2) Em paralelo, busca do banco (pode ter msgs de outros dispositivos)
  chatCarregarDoBanco(rpgId).then(banco => {
    if (!banco.length) return;
    // Mescla: une local + banco, remove duplicatas por ts+autor+texto, ordena
    const mapa = new Map();
    [...local, ...banco].forEach(m => mapa.set(`${m.ts}_${m.autor}_${m.texto}`, m));
    const merged = [...mapa.values()].sort((a, b) => (a.ts || 0) - (b.ts || 0));
    CHAT.msgs = merged;
    chatSalvarLocal(rpgId, merged);
    chatRenderizar();
  }).catch(() => {});
  const nick = SESSION?.nickname || USER_ID || 'Jogador';
  const charVinculado = RPG_DATA?.characters?.find(c => c.nome === RPG_DATA?.linked);
  const cor = charVinculado?.custom_attrs?.cor || '#7ec8f0';
  // Join chat broadcast channel
  wsRef.send(JSON.stringify({
    topic:   `realtime:chat:${rpgId}`,
    event:   'phx_join',
    payload: { config: { broadcast: { self: true }, presence: { key: nick } } },
    ref:     'chat_join'
  }));
  // Função reutilizável para enviar presença
  const enviarPresenca = () => {
    if (wsRef.readyState !== WebSocket.OPEN) return;
    const ch = RPG_DATA?.characters?.find(c => c.nome === RPG_DATA?.linked);
    const nickAtual = ch ? ch.nome : (SESSION?.nickname || USER_ID || 'Jogador');
    const corAtual = ch?.custom_attrs?.cor || '#7ec8f0';
    wsRef.send(JSON.stringify({
      topic:   `realtime:chat:${rpgId}`,
      event:   'broadcast',
      payload: { type: 'broadcast', event: 'chat_presence', payload: { nick: nickAtual, cor: corAtual, ts: Date.now() } },
      ref:     'presence_' + Date.now()
    }));
  };
  setTimeout(enviarPresenca, 800);
  // Heartbeat a cada 20s para manter presença atualizada
  if (CHAT._presenceInterval) clearInterval(CHAT._presenceInterval);
  CHAT._presenceInterval = setInterval(() => {
    enviarPresenca();
    // Atualizar lista de online removendo inativos e atualizar badge
    const agora = Date.now();
    CHAT.online = CHAT.online.filter(u => agora - u.ts < 35000);
    chatAtualizarOnline();
    _atualizarBadgeMesa();
    // Re-renderizar vez (pode ter mudado status offline) — usa a batalha do jogador
    const bidAtivo = batalhaIdMinha ? batalhaIdMinha() : BATALHA_ATUAL_ID;
    if (bidAtivo && MAPA_STATE.batalhas[bidAtivo]?.fase === 'combate') {
      batalhaRenderOrdemStrip();
      batalhaRenderVezLabel();
    }
  }, 20000);
}

function chatEnviar() {
  const input = document.getElementById('chat-input');
  const texto = input?.value.trim();
  if (!texto) return;
  const rpgId = AR.session?.rpg_id || CURRENT_RPG?.id;
  const ws    = AR.ws || realtimeWS;
  if (!ws || ws.readyState !== WebSocket.OPEN) { mostrarToast('Chat desconectado', 'erro'); return; }
  // Usar personagem vinculado como identidade no chat
  const charVinculado = RPG_DATA?.characters?.find(c => c.nome === RPG_DATA?.linked)
    || AR.chars?.find(c => c.nome === RPG_DATA?.linked);
  const cor   = charVinculado?.custom_attrs?.cor || '#7ec8f0';
  const autor = charVinculado ? charVinculado.nome : (SESSION?.nickname || USER_ID || 'Jogador');
  ws.send(JSON.stringify({
    topic:   `realtime:chat:${rpgId}`,
    event:   'broadcast',
    payload: { type: 'broadcast', event: 'chat_msg', payload: {
      autor, cor, texto, ts: Date.now()
    }},
    ref: 'chat_msg_' + Date.now()
  }));
  // Renovar presença a cada mensagem
  ws.send(JSON.stringify({
    topic:   `realtime:chat:${rpgId}`,
    event:   'broadcast',
    payload: { type: 'broadcast', event: 'chat_presence', payload: { nick: autor, cor, ts: Date.now() } },
    ref:     'presence_' + Date.now()
  }));
  input.value = '';
  input.focus();
}

function chatReceberMensagem(pkg) {
  if (!pkg?.autor || !pkg?.texto) return;
  // Evitar duplicatas (mensagem já no histórico local)
  const jaExiste = CHAT.msgs.some(m => m.ts === pkg.ts && m.autor === pkg.autor && m.texto === pkg.texto);
  if (!jaExiste) {
    CHAT.msgs.push(pkg);
    if (CHAT.msgs.length > 200) CHAT.msgs.shift();
    // Persistir localmente e agendar salvamento no banco
    if (CHAT.rpgId) {
      chatSalvarLocal(CHAT.rpgId, CHAT.msgs);
      chatAgendarSalvoBanco();
    }
  }
  const eProprioMsg = pkg.autor === (SESSION?.nickname || USER_ID);
  const chatVis = document.getElementById('chat-container')?.classList.contains('visivel') && CHAT.aberto;
  if (!eProprioMsg && !chatVis && !jaExiste) { CHAT.naoLidos++; chatAtualizarBadge(); }
  chatRenderizar();
}

function chatRenderizar() {
  const el    = document.getElementById('chat-mensagens');
  const empty = document.getElementById('chat-empty');
  if (!el) return;
  const meuNick = SESSION?.nickname || USER_ID;
  if (!CHAT.msgs.length) { if (empty) empty.style.display = 'block'; el.innerHTML = ''; return; }
  if (empty) empty.style.display = 'none';
  el.innerHTML = CHAT.msgs.slice(-80).map(m => {
    const eP  = m.autor === meuNick;
    const hora = new Date(m.ts).toLocaleTimeString('pt-BR', { hour:'2-digit', minute:'2-digit' });
    const isSys = m.tipo === 'sistema';
    if (isSys) return `<div style="text-align:center;font-size:0.68rem;color:#3a5270;font-style:italic;padding:4px 0">${chatEscapar(m.texto)}</div>`;
    return `<div class="chat-msg${eP?' chat-msg-proprio':''}" style="max-width:85%;align-self:${eP?'flex-end':'flex-start'}">
      <div class="chat-msg-autor" style="display:flex;align-items:center;gap:5px;margin-bottom:2px">
        <span style="font-family:'Cinzel',serif;font-size:0.6rem;color:${m.cor||'#7ec8f0'}">${chatEscapar(m.autor)}</span>
        <span style="font-size:0.58rem;color:#3a5270">${hora}</span>
      </div>
      <div style="background:${eP?'rgba(79,163,209,0.1)':'rgba(255,255,255,0.04)'};border:1px solid ${eP?'rgba(79,163,209,0.2)':'rgba(255,255,255,0.06)'};border-radius:${eP?'10px 10px 2px 10px':'10px 10px 10px 2px'};padding:6px 10px;font-size:0.88rem;color:#c8d8e8;line-height:1.4;word-break:break-word">${chatEscapar(m.texto)}</div>
    </div>`;
  }).join('');
  el.scrollTop = el.scrollHeight;
  chatAtualizarOnline();
}

function chatReceberPresenca(pkg) {
  if (!pkg?.nick) return;
  // Atualizar lista de online — remover entrada antiga do mesmo nick e adicionar nova
  CHAT.online = CHAT.online.filter(u => u.nick !== pkg.nick);
  CHAT.online.push({ nick: pkg.nick, cor: pkg.cor || '#7ec8f0', ts: pkg.ts || Date.now() });
  // Limpar usuários inativos há mais de 30s
  const agora = Date.now();
  CHAT.online = CHAT.online.filter(u => agora - u.ts < 30000);
  chatAtualizarOnline();
}

function chatAtualizarOnline() {
  const el = document.getElementById('chat-online');
  if (!el) return;
  const agora = Date.now();
  const ativos = CHAT.online.filter(u => agora - u.ts < 30000);
  if (!ativos.length) { el.style.display = 'none'; return; }
  el.style.display = 'flex';
  el.innerHTML = ativos.map(u =>
    `<span title="${u.nick}" style="width:7px;height:7px;border-radius:50%;background:${u.cor};flex-shrink:0;box-shadow:0 0 4px ${u.cor}88"></span>`
  ).join('') + `<span style="font-size:0.58rem;color:#3a5270;margin-left:2px">${ativos.length} online</span>`;
}

function chatMostrar(rpgId) {
  CHAT.rpgId = rpgId;
  const btn = document.getElementById('hdr-chat-btn');
  if (btn) btn.style.display = 'inline-flex';
  const rbtn = document.getElementById('hdr-reflash-btn');
  if (rbtn) rbtn.style.display = 'inline-flex';
  // Chat começa FECHADO — usuário abre clicando no ícone
  CHAT.aberto = false; CHAT.naoLidos = 0;
  chatAtualizarBadge();
}

function chatOcultar() {
  document.getElementById('chat-container').classList.remove('visivel');
  // NÃO esconde o botão — apenas fecha o painel
  CHAT.aberto = false;
}

async function reflashDados() {
  if (!CURRENT_RPG?.id) return;
  const btn = document.getElementById('hdr-reflash-btn');
  if (btn) { btn.textContent = '⏳'; btn.style.opacity = '0.5'; btn.style.pointerEvents = 'none'; }
  try {
    RPG_DATA = await getRPGData(CURRENT_RPG.id);
    // Re-renderiza tudo sem sair da aba atual nem mostrar loading
    if (typeof renderHeader       === 'function') renderHeader();
    if (typeof renderLore         === 'function') renderLore();
    if (typeof renderCharButtons  === 'function') renderCharButtons();
    if (typeof renderAttrButtons  === 'function') renderAttrButtons();
    if (typeof renderDados        === 'function') renderDados();
    if (typeof renderConfig       === 'function') renderConfig();
    if (typeof renderMapasTab     === 'function') renderMapasTab();
    if (CHAR_VIEW) {
      if (typeof renderCharView === 'function') renderCharView(CHAR_VIEW);
      if (typeof renderAttrView === 'function') renderAttrView(CHAR_VIEW);
    }
    mostrarToast('✅ Dados atualizados!', 'sucesso');
  } catch(e) {
    mostrarToast('❌ Erro ao atualizar dados', 'erro');
  } finally {
    if (btn) { btn.textContent = '🔄'; btn.style.opacity = ''; btn.style.pointerEvents = ''; }
  }
}

function chatToggle() {
  if (CHAT.aberto) {
    chatOcultar();
  } else {
    chatAbrir();
  }
}

function chatAbrir() {
  document.getElementById('chat-container').classList.add('visivel');
  CHAT.aberto = true; CHAT.naoLidos = 0;
  chatAtualizarBadge(); chatRenderizar();
  setTimeout(() => document.getElementById('chat-input')?.focus(), 50);
}

function chatAtualizarBadge() {
  const hdrBadge = document.getElementById('chat-fab-badge');
  const n = CHAT.naoLidos;
  if (hdrBadge) {
    hdrBadge.textContent = n > 9 ? '9+' : n;
    hdrBadge.style.display = n > 0 ? 'flex' : 'none';
  }
  // Sincronizar badge da arena também
  const arBadge = document.getElementById('ar-chat-badge');
  if (arBadge) {
    arBadge.textContent = n > 9 ? '9+' : n;
    arBadge.style.display = n > 0 ? 'flex' : 'none';
  }
}

async function chatSalvarLog() {
  if (!CHAT.msgs.length) { mostrarToast('Sem mensagens para salvar', ''); return; }
  const rpgId = AR.session?.rpg_id || CURRENT_RPG?.id;
  if (!rpgId) return;
  const titulo = `chat_${Date.now()}`;
  const conteudo = JSON.stringify({ data: new Date().toLocaleDateString('pt-BR'), msgs: CHAT.msgs });
  try {
    await sb('lore', { method:'POST', body: JSON.stringify({ rpg_id: rpgId, secao:'chat_log', titulo, conteudo }) });
    mostrarToast('Log do chat salvo!', 'sucesso');
  } catch(e) { mostrarToast('Erro ao salvar log', 'erro'); }
}

function chatEscapar(texto) {
  return texto.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ═══════════════════════════════════════════════════════════════
// ⚔ SISTEMA DE COMBATE — Parser de fórmulas, rolagem, turnos, ataques e efeitos
// ═══════════════════════════════════════════════════════════════

// ── 18A: Parser de fórmula de dados ──────────────────────────
// Suporta fórmulas multi-grupo: "2d6+1d8+3", "d20", "1d6+2", etc.
// Retorna array de grupos: [{tipo:'dado',qtd,faces} | {tipo:'fixo',valor}]
function parsearFormulaDano(formula) {
  if (!formula || formula === '—') return null;
  const f = formula.toString().toLowerCase().replace(/\s/g, '');
  const grupos = [];
  // Quebra em tokens: "2d6", "+1d8", "-1", "+3", etc.
  const re = /([+-]?\d*d\d+|[+-]?\d+)/g;
  let m;
  while ((m = re.exec(f)) !== null) {
    const tok = m[1];
    const dado = tok.match(/^([+-]?\d*)d(\d+)$/);
    if (dado) {
      let qtdRaw = dado[1].replace(/^\+/, '') || '1';
      if (qtdRaw === '-') qtdRaw = '-1';
      const qtd = Math.abs(parseInt(qtdRaw) || 1);
      const faces = parseInt(dado[2]);
      if (faces > 0 && qtd > 0) grupos.push({ tipo: 'dado', qtd, faces });
    } else {
      const val = parseInt(tok);
      if (!isNaN(val) && val !== 0) grupos.push({ tipo: 'fixo', valor: val });
    }
  }
  return grupos.length ? grupos : null;
}

// Constrói string da fórmula a partir de grupos de builder
function formulaDeGrupos(grupos) {
  if (!grupos || !grupos.length) return '—';
  const agrupado = {};
  let bonus = 0;
  for (const g of grupos) {
    if (g.tipo === 'dado') {
      const k = g.faces;
      agrupado[k] = (agrupado[k] || 0) + g.qtd;
    } else {
      bonus += g.valor;
    }
  }
  const partes = Object.keys(agrupado).sort((a,b)=>b-a).map(f => `${agrupado[f]}d${f}`);
  if (bonus !== 0) partes.push(bonus > 0 ? '+'+bonus : String(bonus));
  return partes.join('+').replace(/\+\-/g, '-') || '—';
}

// Rola todos os dados dos grupos, retorna lista de {faces, valor} para animação
function rolarGrupos(grupos) {
  if (!grupos) return { total: 0, dados: [], bonus: 0 };
  const dados = [];
  let bonus = 0;
  for (const g of grupos) {
    if (g.tipo === 'dado') {
      for (let i = 0; i < g.qtd; i++) {
        dados.push({ faces: g.faces, valor: Math.floor(Math.random() * g.faces) + 1 });
      }
    } else {
      bonus += g.valor;
    }
  }
  const total = Math.max(0, dados.reduce((s, d) => s + d.valor, 0) + bonus);
  return { total, dados, bonus };
}

// Wrapper de compatibilidade — aceita fórmula como array de grupos (novo) ou objeto simples (formato antigo)
function rolarFormula(parsed) {
  if (!parsed) return { total: 0, rolls: [], formula: '?' };
  // Formato novo: array [{tipo,qtd,faces}]; formato antigo: objeto simples {tipo,qtd,faces}
  if (Array.isArray(parsed)) {
    const r = rolarGrupos(parsed);
    return { total: r.total, rolls: r.dados.map(d=>d.valor), formula: formulaDeGrupos(parsed) };
  }
  if (parsed.tipo === 'fixo') return { total: parsed.fixo, rolls: [parsed.fixo], formula: String(parsed.fixo) };
  const rolls = [];
  for (let i = 0; i < parsed.qtd; i++) rolls.push(Math.floor(Math.random() * parsed.faces) + 1);
  const total = rolls.reduce((a, b) => a + b, 0) + (parsed.bonus||0);
  return { total: Math.max(0, total), rolls, formula: `${parsed.qtd}d${parsed.faces}` };
}

// ── Calcula o bônus fixo de atributo para uma habilidade ─────
// Retorna inteiro (ceil de pct% do valor do atributo do atacante)
function calcModAtributo(habilidade, nomeAtacante, contexto) {
  const pct = habilidade.mod_atributo_pct;
  const atributo = habilidade.atributo_base;
  if (!pct || !atributo) return 0;

  const chars = contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const char = chars.find(c => c.nome === nomeAtacante);
  if (!char) return 0;

  const valor = parseFloat(
    char.custom_attrs?.atributos?.[atributo] ?? 0
  );
  return Math.ceil(valor * pct / 100);
}
let COMBATE = {
  contexto: null, atacanteNome: null, habilidadeSel: null, alvoNome: null,
  dadosRolados: null, step: 1,
  _habilidades: [], _alvos: [],
  formulaBuilder: [], rolando: false,
};
let NPC_HABILIDADES_TEMP = [];

// ── 18D: Abrir / fechar modal ────────────────────────────────
function abrirModalAtaque(atacanteNome, contexto = 'arena') {
  if (!atacanteNome) { mostrarToast('Nenhum personagem selecionado', 'erro'); return; }

  // Verificar estado de batalha para jogadores
  if (RPG_DATA?.myRole !== 'mestre') {
    const estadoAtk = _estadoBatalhaJogador(atacanteNome);
    if (estadoAtk === 'outro_turno') {
      mostrarToast('⏳ Aguarde seu turno para atacar!', 'erro');
      return;
    }
    // Guardar estado no COMBATE para uso posterior no fluxo
    COMBATE._estadoAtk = estadoAtk; // 'livre' ou 'fora_combate'
  } else {
    COMBATE._estadoAtk = 'livre';
  }

  // Cancelar qualquer trigger card/countdown pendente de ataque anterior
  _atkOcultarTrigger();

  COMBATE = {
    contexto, atacanteNome, habilidadeSel: null, alvoNome: null,
    dadosRolados: null, step: 1, _habilidades: [], _alvos: [],
    formulaBuilder: [], rolando: false, _jaAplicado: false, _pendingTrigger: false,
    _estadoAtk: COMBATE._estadoAtk || 'livre',
  };
  document.getElementById('modal-atk-atacante').textContent = atacanteNome;

  const habilidades = contexto === 'arena'
    ? atkGetHabilidadesArena(atacanteNome)
    : atkGetHabilidadesCampanha(atacanteNome);

  COMBATE._habilidades = habilidades;
  const cooldownsAtivos = contexto === 'arena' ? (AR.estado?.cooldowns || {}) : {};

  const lista = document.getElementById('atk-habilidades-lista');
  lista.innerHTML = habilidades.map((h, i) => {
    const cdRestante = cooldownsAtivos[h.id] || 0;
    const emCooldown = cdRestante > 0;
    const bloqueio   = atkVerificarBloqueioAtaque(atacanteNome, h.tipo_dano);
    const disabled   = emCooldown || !!bloqueio;
    const corBorda   = disabled ? 'rgba(60,40,20,0.6)' : 'rgba(60,30,30,0.6)';
    const corNome    = disabled ? '#6a5840' : '#e8604c';
    let badge;
    if (emCooldown) {
      badge = `<span style="font-size:0.65rem;color:#a07040;background:rgba(100,60,0,0.2);border:1px solid rgba(100,60,0,0.3);border-radius:4px;padding:1px 6px">⏳ ${cdRestante}t</span>`;
    } else if (bloqueio) {
      badge = `<span style="font-size:0.65rem;color:#c0392b;background:rgba(192,57,43,0.1);border:1px solid rgba(192,57,43,0.3);border-radius:4px;padding:1px 6px">🚫 Bloq.</span>`;
    } else if (h.formula_dano && h.formula_dano !== '—') {
      const modAttr = calcModAtributo(h, atacanteNome, contexto);
      const modLabel = modAttr !== 0 ? ` <span style="color:#7ec8f0;font-size:0.7rem">+${modAttr}(${h.atributo_base})</span>` : '';
      badge = `<span style="font-family:'Cinzel',serif;font-size:0.75rem;color:#f0cc6a;background:rgba(200,168,75,0.1);border:1px solid rgba(200,168,75,0.2);border-radius:4px;padding:1px 7px">${h.formula_dano}${modLabel}</span>`;
    } else {
      badge = `<span style="font-size:0.7rem;color:#7a6060">Montar dados</span>`;
    }
    const cdLabel     = h.cooldown_turnos > 0 ? `<span style="font-size:0.68rem;color:#7a6060"> · CD ${h.cooldown_turnos}t</span>` : '';
    const alcanceLabel= h.alcance_celulas != null ? `<span style="font-size:0.68rem;color:#7a6060"> · ⟷ ${h.alcance_celulas}c</span>` : '';
    const msgBloqueio = disabled ? (bloqueio || `Habilidade em recarga: ${cdRestante} turno(s)`) : null;
    return `<div onclick="${disabled ? `mostrarToast(${JSON.stringify(msgBloqueio)},'erro')` : `atkSelecionarHabilidade(${i})`}"
      style="padding:12px;background:rgba(20,12,12,0.8);border:1px solid ${corBorda};border-radius:8px;cursor:${disabled?'default':'pointer'};opacity:${disabled?'0.55':'1'};transition:all 0.15s"
      ${disabled ? '' : `onmouseenter="this.style.borderColor='rgba(232,80,60,0.4)'" onmouseleave="this.style.borderColor='${corBorda}'"`}>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
        <span style="font-family:'Cinzel',serif;font-size:0.85rem;color:${corNome}">${h.nome}${cdLabel}${alcanceLabel}</span>
        ${badge}
      </div>
      <div style="font-size:0.82rem;color:#9a8888;line-height:1.4">${(h.efeito||'').slice(0,100)}${(h.efeito||'').length>100?'…':''}</div>
    </div>`;
  }).join('') || '<div style="color:#7a6060;font-style:italic;padding:12px">Nenhuma habilidade disponível</div>';

  document.getElementById('atk-criativo-wrap').style.display = temPermissao('ataque_criativo') ? 'block' : 'none';
  document.getElementById('atk-criativo-desc').value = '';
  // Mostrar/ocultar aviso fora de combate
  const avisoBanner = document.getElementById('atk-aviso-fora-combate');
  if (avisoBanner) avisoBanner.style.display = (COMBATE._estadoAtk === 'fora_combate') ? 'block' : 'none';
  // Renderizar seção de pets vinculados ao atacante
  atkRenderizarSecaoPets(atacanteNome, contexto);
  atkIrParaStep(1);

  const modal = document.getElementById('modal-ataque');
  const inner = modal.querySelector('div');

  if (contexto === 'campanha') {
    const anchor = document.getElementById('atk-painel-campanha-anchor');
    // Verifica se o anchor está visível (aba do mapa ativa). Se não, usa overlay.
    const anchorVisivel = anchor && anchor.offsetParent !== null;
    if (anchorVisivel) {
      // ── Painel inline abaixo do mapa ──
      modal.style.cssText = 'display:block;position:static;background:none;z-index:auto;';
      if (inner) {
        inner.style.borderRadius = '12px';
        inner.style.marginTop = '0';
        inner.style.paddingBottom = '16px';
        inner.style.maxHeight = 'none';
      }
      if (anchor.firstChild !== modal) anchor.appendChild(modal);
      setTimeout(() => modal.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 60);
    } else {
      // ── Fallback overlay (aba do mapa não está ativa) ──
      modal.style.cssText = 'display:flex;position:fixed;inset:0;background:rgba(0,0,0,0.88);z-index:9999;align-items:flex-end;justify-content:center;';
      if (inner) {
        inner.style.borderRadius = '16px 16px 0 0';
        inner.style.marginTop = '';
        inner.style.paddingBottom = '44px';
        inner.style.maxHeight = '90vh';
      }
      document.body.appendChild(modal);
    }
  } else {
    // ── Modo arena: modal overlay como antes ──
    modal.style.cssText = 'display:flex;position:fixed;inset:0;background:rgba(0,0,0,0.88);z-index:9999;align-items:flex-end;justify-content:center;';
    if (inner) {
      inner.style.borderRadius = '16px 16px 0 0';
      inner.style.marginTop = '';
      inner.style.paddingBottom = '44px';
      inner.style.maxHeight = '90vh';
    }
    document.body.appendChild(modal);
  }
}

function fecharModalAtaque() {
  const modal = document.getElementById('modal-ataque');
  const foiCancelado = !COMBATE._jaAplicado && !COMBATE._pendingTrigger;
  modal.style.display = 'none';
  // Se estava no painel inline da campanha, devolve ao body para próximo uso
  if (modal.parentElement?.id === 'atk-painel-campanha-anchor') {
    document.body.appendChild(modal);
  }
  mapaHideRangeCircle();
  // Se há ataque pendente (dados rolados, animação não disparada ainda), mostra o trigger flutuante
  if (COMBATE._pendingTrigger) {
    COMBATE._pendingTrigger = false;
    _atkMostrarTrigger();
    return;
  }
  // Se foi cancelado sem completar o ataque, reapresenta o botão atacar via re-render da UI
  if (foiCancelado && COMBATE.contexto === 'campanha') {
    _aplicarEstadoBatalhaUI();
  }
}

// ══════════════════════════════════════════════════════════════
// ⚡ MODAL DE EFEITO CRÍTICO (mestre)
// ══════════════════════════════════════════════════════════════
let _criticoCtx = { alvos: [], ehPositivo: false, texto: '', contexto: 'campanha' };

function abrirModalCriticoMestre(alvos, ehPositivo, criticoTexto, contexto) {
  _criticoCtx = { alvos: alvos || [], ehPositivo: !!ehPositivo, texto: criticoTexto || '', contexto: contexto || 'campanha' };
  const modal = document.getElementById('modal-critico-mestre');
  if (!modal) return;

  // Preencher header
  document.getElementById('critico-modal-icone').textContent = ehPositivo ? '✨' : '⚡';
  document.getElementById('critico-modal-titulo').textContent = ehPositivo ? 'CRÍTICO POSITIVO!' : 'CRÍTICO!';
  document.getElementById('critico-modal-titulo').style.color = ehPositivo ? '#5ee09a' : '#f0cc6a';
  const sub = ehPositivo
    ? 'Habilidade de suporte atingiu potencial máximo'
    : `${alvos.join(', ')} foi(ram) atingido(s) criticamente`;
  document.getElementById('critico-modal-sub').textContent = sub;

  // Texto do efeito
  const textoEl = document.getElementById('critico-modal-efeito-texto');
  if (criticoTexto) {
    textoEl.textContent = criticoTexto;
    textoEl.style.display = 'block';
    textoEl.style.background = ehPositivo ? 'rgba(94,224,154,0.08)' : 'rgba(240,180,20,0.08)';
    textoEl.style.borderColor = ehPositivo ? 'rgba(94,224,154,0.25)' : 'rgba(240,180,20,0.25)';
    textoEl.style.color = ehPositivo ? '#9af0c0' : '#e8d090';
  } else {
    textoEl.style.display = 'none';
  }

  // Listar todos os personagens para seleção
  const chars = contexto === 'arena' ? (AR?.chars || []) : (RPG_DATA?.characters || []);
  const charsEl = document.getElementById('critico-modal-chars');
  // Por padrão, pré-selecionar os alvos do ataque
  charsEl.innerHTML = chars.map(c => {
    const selecionado = alvos.includes(c.nome);
    const isNpc = c.custom_attrs?.tipo_personagem === 'npc';
    const cor = c.custom_attrs?.cor || c.cor || '#4fa3d1';
    return `<label style="display:flex;align-items:center;gap:10px;padding:7px 10px;background:rgba(10,6,2,0.5);border:1px solid rgba(40,25,5,0.6);border-radius:7px;cursor:pointer">
      <input type="checkbox" value="${c.nome}" ${selecionado ? 'checked' : ''} style="accent-color:${ehPositivo?'#5ee09a':'#f0cc6a'};width:15px;height:15px;flex-shrink:0">
      <div style="width:10px;height:10px;border-radius:50%;background:${cor};flex-shrink:0"></div>
      <span style="font-size:0.82rem;color:#c8d8e8;flex:1">${c.nome}</span>
      ${isNpc ? `<span style="font-size:0.58rem;color:#7a92aa;background:rgba(30,20,10,0.6);border-radius:3px;padding:1px 5px">NPC</span>` : ''}
    </label>`;
  }).join('');

  // Reset tipo de efeito
  const tipoEl = document.getElementById('critico-ef-tipo');
  if (tipoEl) tipoEl.value = '';
  criticoEfTipoChange();

  modal.style.display = 'flex';
}

function fecharModalCriticoMestre() {
  const modal = document.getElementById('modal-critico-mestre');
  if (modal) modal.style.display = 'none';
}

function criticoEfTipoChange() {
  const tipo = document.getElementById('critico-ef-tipo')?.value || '';
  const campos = ['dot','hot','dano','boost','cura','livre'];
  campos.forEach(c => {
    const el = document.getElementById(`critico-ef-campos-${c}`);
    if (el) el.style.display = 'none';
  });
  const mapa = { dot: 'dot', hot: 'hot', debuff_dano: 'dano', boost: 'boost', cura_imediata: 'cura', livre: 'livre' };
  const campo = mapa[tipo];
  if (campo) {
    const el = document.getElementById(`critico-ef-campos-${campo}`);
    if (el) el.style.display = 'block';
  }
  // Turnos visível exceto para cura imediata
  const turnosEl = document.getElementById('critico-ef-turnos');
  if (turnosEl) turnosEl.closest('div')?.parentElement && (turnosEl.parentElement.parentElement.style.display = tipo === 'cura_imediata' || tipo === 'livre' || tipo === '' ? 'none' : '');
}

async function criticoMestreAplicar() {
  const { alvos, ehPositivo, texto, contexto } = _criticoCtx;
  const checks = document.querySelectorAll('#critico-modal-chars input[type=checkbox]:checked');
  const selecionados = Array.from(checks).map(c => c.value);
  if (!selecionados.length) { mostrarToast('Selecione ao menos um personagem', 'erro'); return; }

  const tipo = document.getElementById('critico-ef-tipo')?.value || '';
  const turnos = parseInt(document.getElementById('critico-ef-turnos')?.value) || 2;

  for (const nomeAlvo of selecionados) {
    if (tipo === 'dot') {
      const formula = document.getElementById('critico-ef-dot-formula')?.value.trim() || '1d6';
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico — ${texto || 'DOT'}`,
        tipo: 'debuff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        dot_formula: formula,
        dot_turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'hot') {
      const formula = document.getElementById('critico-ef-hot-formula')?.value.trim() || '1d6';
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico+ — ${texto || 'HOT'}`,
        tipo: 'buff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        hot_formula: formula,
        hot_turnos_restantes: turnos,
        hot_turnos: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'debuff_mov') {
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico — ${texto || 'Imobilizado'}`,
        tipo: 'debuff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        sem_movimento: true,
        sem_movimento_turnos: turnos,
        sem_movimento_turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'debuff_atk') {
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico — ${texto || 'Sem ataque'}`,
        tipo: 'debuff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        sem_ataque: true,
        sem_ataque_tipo: 'todos',
        sem_ataque_turnos: turnos,
        sem_ataque_turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'debuff_dano') {
      const mod = parseInt(document.getElementById('critico-ef-mod-dano')?.value) || -3;
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico — ${texto || 'Dano reduzido'}`,
        tipo: 'debuff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        mod_dano: mod < 0 ? mod : -mod,
        mod_dano_turnos: turnos,
        mod_dano_turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'boost') {
      const boost = parseInt(document.getElementById('critico-ef-boost')?.value) || 5;
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: `Crítico+ — ${texto || 'Dano aumentado'}`,
        tipo: 'buff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        boost_dano: boost,
        boost_dano_turnos: turnos,
        boost_dano_turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);

    } else if (tipo === 'cura_imediata') {
      const qtd = parseInt(document.getElementById('critico-ef-cura-qtd')?.value) || 0;
      if (qtd > 0) await atkAplicarCura(nomeAlvo, qtd, contexto);

    } else if (tipo === 'livre') {
      const nomeEf = document.getElementById('critico-ef-livre-nome')?.value.trim() || 'Efeito crítico';
      const ef = {
        id: 'crit_' + Date.now() + '_' + Math.random().toString(36).slice(2,5),
        nome: nomeEf,
        tipo: ehPositivo ? 'buff' : 'debuff',
        turno_inicio: contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
        turnos_restantes: turnos,
      };
      await atkAplicarEfeito(nomeAlvo, ef, contexto);
    }
    // Sem tipo: apenas fecha (efeito foi apenas narrativo)
  }

  if (tipo) {
    if (contexto === 'arena') {
      await arSalvarEstado();
      renderArenaPersonagens(); renderArenaEntidades(); renderArenaEfeitos();
    } else {
      renderCharView?.(selecionados[0]);
      mapaRenderStatus?.();
    }
    mostrarToast(`⚡ Efeito crítico aplicado em ${selecionados.join(', ')}!`, 'sucesso');
  }

  fecharModalCriticoMestre();
}
// ── fim modal crítico ──────────────────────────────────────────



// ── Círculo de alcance visual no mapa ────────────────────────
function mapaShowRangeCircle(atacanteNome, alcanceCelulas) {
  if (COMBATE.contexto !== 'campanha') return;
  const tokensEl = document.getElementById('mapa-tokens');
  if (!tokensEl) return;

  // Armazenar estado do círculo para atualizações em tempo real
  MAPA_STATE._rangeCircle = { atacanteNome, alcanceCelulas };

  let el = document.getElementById('atk-range-circle');
  if (!el) {
    el = document.createElement('div');
    el.id = 'atk-range-circle';
    tokensEl.appendChild(el);
  }

  const mapId = MAPA_STATE?.mapaAtualId || null;
  const char  = (RPG_DATA?.characters || []).find(c => c.nome === atacanteNome);
  const pos   = (char && mapId) ? getPosicaoNoMapa(char, mapId) : null;
  // fallback: centro do mapa se personagem não estiver posicionado
  const px = pos?.x ?? 50;
  const py = pos?.y ?? 50;

  const entry  = (RPG_DATA?.mapas || []).find(l => l.mapa.map_id === mapId);
  const gridPx = entry?.mapa?.grid || 20;
  const radiusPx = alcanceCelulas * gridPx;

  // Cor do personagem
  const ca  = char?.custom_attrs || {};
  const cor = ca.cor || char?.cor || '#7ec8f0';
  let r = 126, g = 200, b = 240;
  const hexMatch = cor.replace('#','');
  if (/^[0-9a-f]{6}$/i.test(hexMatch)) {
    r = parseInt(hexMatch.slice(0,2),16);
    g = parseInt(hexMatch.slice(2,4),16);
    b = parseInt(hexMatch.slice(4,6),16);
  }

  el.style.cssText = `
    position:absolute;
    left:${px}%;top:${py}%;
    width:${radiusPx*2}px;height:${radiusPx*2}px;
    border-radius:50%;
    pointer-events:none;
    transform:translate(-50%,-50%);
    z-index:6;
    background:rgba(${r},${g},${b},0.12);
    border:3px solid rgba(${r},${g},${b},0.8);
    box-shadow:
      0 0 0 1px rgba(${r},${g},${b},0.25),
      0 0 20px rgba(${r},${g},${b},0.35),
      inset 0 0 ${Math.max(20,Math.round(radiusPx*0.3))}px rgba(${r},${g},${b},0.12);
    display:block;
    animation:rangeCirclePulse 1.8s ease-in-out infinite alternate;
  `;
}

function mapaHideRangeCircle() {
  const el = document.getElementById('atk-range-circle');
  if (el) el.style.display = 'none';
  if (MAPA_STATE) MAPA_STATE._rangeCircle = null;
}

// ── Sistema de Pet ────────────────────────────────────────────
// Retorna habilidades do pet independente de como estão armazenadas
// (criaturas usam custom_attrs.habilidades; jogadores/NPCs usam skills)
function petGetHabilidadesPet(petNome, contexto) {
  const chars = contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const c = chars.find(x => x.nome === petNome);
  if (!c) return [];
  const ca = c.custom_attrs || {};
  // Criaturas e NPCs podem ter habilidades em custom_attrs.habilidades
  if (ca.habilidades?.length) {
    return ca.habilidades.map(h => ({ ...h, cooldown_turnos: h.cooldown_turnos || 0 }));
  }
  // Jogadores / personagens com ficha usam a tabela skills
  if (contexto === 'arena') return atkGetHabilidadesArena(petNome);
  return atkGetHabilidadesCampanha(petNome);
}

// Retorna pets vinculados ao dono que possuem habilidades
function petGetPetsDoDono(donoNome, contexto) {
  const chars = contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  return chars.filter(c => {
    const ca = c.custom_attrs || {};
    return ca.eh_pet === true && ca.pet_dono === donoNome;
  });
}

// Verifica se o dono está incapacitado (pet não pode agir)
function petDonoEstaAtivo(donoNome, contexto) {
  const chars = contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const dono = chars.find(c => c.nome === donoNome);
  if (!dono) return false;
  const hp = dono.hp_atual ?? (dono.custom_attrs?.hp_max ?? 100);
  if (hp <= 0) return false;
  // Verificar debuff sem_ataque
  const buffs = dono.buffs || [];
  const bloqueado = buffs.some(b => b.sem_ataque && (b.sem_ataque_turnos_restantes ?? 0) > 0 && (b.sem_ataque_tipo || 'todos') === 'todos');
  return !bloqueado;
}

// Renderiza seção de pets no modal de ataque (step 1)
function atkRenderizarSecaoPets(donoNome, contexto) {
  const pets = petGetPetsDoDono(donoNome, contexto);
  const el = document.getElementById('atk-pets-section');
  if (!el) return;

  if (!pets.length) { el.style.display = 'none'; return; }

  const donoAtivo = petDonoEstaAtivo(donoNome, contexto);
  const rows = pets.map(pet => {
    const habilidades = petGetHabilidadesPet(pet.nome, contexto);
    if (!habilidades.length) return '';
    const cor = pet.custom_attrs?.cor || '#7ec8f0';
    const hpAtual = pet.hp_atual ?? (pet.custom_attrs?.hp_max ?? 100);
    const hpMax = pet.custom_attrs?.hp_max ?? 100;
    const incap = hpAtual <= 0;
    return `
      <div style="margin-bottom:8px;padding:10px;background:rgba(10,18,28,0.8);border:1px solid ${cor}22;border-left:2px solid ${cor};border-radius:8px;opacity:${incap||!donoAtivo?0.45:1}">
        <div style="font-family:'Cinzel',serif;font-size:0.72rem;color:${cor};margin-bottom:6px">🐾 ${pet.nome}${incap?' <span style="color:#e74c3c;font-size:0.65rem">[INCAPACITADO]</span>':''}</div>
        ${habilidades.map((h, i) => {
          const bloqueio = atkVerificarBloqueioAtaque(pet.nome, h.tipo_dano);
          const desabilitado = incap || !donoAtivo || !!bloqueio;
          const motivo = incap ? 'Pet incapacitado' : !donoAtivo ? 'Dono incapacitado' : bloqueio;
          return `<div onclick="${desabilitado ? `mostrarToast(${JSON.stringify(motivo)},'erro')` : `atkUsarAtaquePet('${pet.nome.replace(/'/g,"\\'")}',${i})`}"
            style="padding:8px 10px;background:rgba(20,12,12,0.6);border:1px solid ${desabilitado?'rgba(60,40,20,0.4)':'rgba(126,200,240,0.2)'};border-radius:6px;cursor:${desabilitado?'default':'pointer'};margin-bottom:4px;transition:all 0.15s"
            ${desabilitado?'':` onmouseenter="this.style.borderColor='rgba(126,200,240,0.45)'" onmouseleave="this.style.borderColor='rgba(126,200,240,0.2)'"`}>
            <div style="display:flex;justify-content:space-between;align-items:center">
              <span style="font-family:'Cinzel',serif;font-size:0.8rem;color:${desabilitado?'#6a5840':'#7ec8f0'}">${h.nome}</span>
              ${h.formula_dano?`<span style="font-size:0.7rem;color:#f0cc6a">${h.formula_dano}</span>`:''}
            </div>
            ${h.efeito?`<div style="font-size:0.75rem;color:#7a8898;margin-top:2px">${h.efeito.slice(0,80)}${h.efeito.length>80?'…':''}</div>`:''}
          </div>`;
        }).join('')}
      </div>`;
  }).join('');

  if (!rows.trim()) { el.style.display = 'none'; return; }
  el.style.display = 'block';
  el.innerHTML = `
    <div style="border-top:1px solid rgba(126,200,240,0.15);margin-top:12px;padding-top:12px">
      <div style="font-family:'Cinzel',serif;font-size:0.6rem;color:rgba(126,200,240,0.5);text-transform:uppercase;margin-bottom:8px">Ataques do Pet / Montaria</div>
      ${rows}
    </div>`;
}

// Inicia ataque do pet: injeta pet como atacante e vai para seleção de alvo
function atkUsarAtaquePet(petNome, habilidadeIdx) {
  const contexto = COMBATE.contexto;
  const habilidades = petGetHabilidadesPet(petNome, contexto);
  const h = habilidades[habilidadeIdx];
  if (!h) return;

  // Guarda o dono real para logs e custos de recurso
  COMBATE._petAtacante = petNome;
  COMBATE._donoAtacante = COMBATE.atacanteNome;

  // Temporariamente troca o atacante para o pet (posição correta para cálculo de alcance)
  COMBATE.atacanteNome = petNome;
  COMBATE.habilidadeSel = h;

  atkMontarSelecaoAlvo();
  atkIrParaStep(2);
}

// Após confirmar ataque do pet, restaura o dono no atacante
const _atkConfirmarOriginal = window.atkConfirmarAtaque;
async function atkConfirmarAtaque() {
  await _atkConfirmarOriginal?.();
  // Restaurar dono após ataque do pet
  if (COMBATE._donoAtacante) {
    COMBATE.atacanteNome = COMBATE._donoAtacante;
    COMBATE._petAtacante = null;
    COMBATE._donoAtacante = null;
  }
}

function atkGetHabilidadesArena(nome) {
  const c = AR.chars.find(x => x.nome === nome);
  return (c?.custom_attrs?.habilidades || []).map(h => ({ ...h, cooldown_turnos: h.cooldown_turnos || 0 }));
}

function atkGetHabilidadesCampanha(nome) {
  const skills = (RPG_DATA?.skills || []).filter(s => s.personagem === nome).map(s => {
    let anim = s.animacao;
    if (typeof anim === 'string') { try { anim = JSON.parse(anim); } catch(e) { anim = null; } }
    if (anim && typeof anim !== 'object') anim = null;
    return {
      id: s.id,
      nome: s.habilidade,
      habilidade: s.habilidade,
      formula_dano:    s.formula_dano || null,
      efeito:          s.efeito,
      custo_rsv:       s.custo_rsv,
      cooldown_turnos: s.cooldown_turnos || 0,
      tipo_dano:       s.tipo_dano || 'fisico',
      alcance_celulas: s.alcance_celulas ?? null,
      atributo_base:   s.atributo_base || null,
      mod_atributo_pct: s.mod_atributo_pct ?? null,
      alvo_tipo:       s.alvo_tipo || 'inimigo',
      efeitos_bonus:   Array.isArray(s.efeitos_bonus) ? s.efeitos_bonus : [],
      animacao:        anim,
      critico_positivo: s.critico_positivo || null,
      critico_negativo: s.critico_negativo || null,
    };
  });

  // ── Injetar efeitos desbloqueados por equipamentos visuais ────────────────
  const c = RPG_DATA?.characters?.find(x => x.nome === nome);
  const equipVisuais = c?.custom_attrs?.aparencia?.equipamentos_visuais || [];
  const comUnlock = equipVisuais.filter(eq => eq.unlock_efeitos && Array.isArray(eq.unlock_efeitos.efeitos) && eq.unlock_efeitos.efeitos.length);
  if (!comUnlock.length) return skills;

  return skills.map(sk => {
    const extras = [];
    for (const eq of comUnlock) {
      const habs = eq.unlock_efeitos.habilidades || ['*'];
      if (habs.includes('*') || habs.includes(sk.nome) || habs.includes(sk.habilidade)) {
        extras.push(...eq.unlock_efeitos.efeitos);
      }
    }
    if (!extras.length) return sk;
    return { ...sk, efeitos_bonus: [...sk.efeitos_bonus, ...extras] };
  });
}

// ── Builder de efeitos bônus (modal de habilidade) ───────────
let SK_EFEITOS_TEMP = [];

function skToggleDotFields()   { document.getElementById('sef-dot-fields').style.display   = document.getElementById('sef-dot-on').checked   ? 'block' : 'none'; }
function skToggleHotFields()   { document.getElementById('sef-hot-fields').style.display   = document.getElementById('sef-hot-on').checked   ? 'block' : 'none'; }
function skToggleBoostFields() { document.getElementById('sef-boost-fields').style.display = document.getElementById('sef-boost-on').checked ? 'block' : 'none'; }
function skToggleRecFields()   { document.getElementById('sef-rec-fields').style.display   = document.getElementById('sef-rec-on').checked   ? 'block' : 'none'; }
function skToggleMovFields()   { document.getElementById('sef-mov-fields').style.display   = document.getElementById('sef-mov-on').checked   ? 'block' : 'none'; }
function skToggleAtkFields()   { document.getElementById('sef-atk-fields').style.display   = document.getElementById('sef-atk-on').checked   ? 'block' : 'none'; }
function skToggleDebFields()   { document.getElementById('sef-deb-fields').style.display   = document.getElementById('sef-deb-on').checked   ? 'block' : 'none'; }

function skAlvoTipoChange() {
  const v = document.getElementById('sk-alvo-tipo').value;
  const dicas = {
    inimigo:        'Ataca um inimigo — usa fórmula de dano e efeitos negativos.',
    proprio:        'Afeta apenas o próprio personagem — ideal para buffs pessoais.',
    aliado:         'Afeta um aliado dentro do alcance — usa efeitos positivos.',
    todos_aliados:  'Afeta todos os aliados dentro do alcance simultaneamente.',
    todos_inimigos: 'Ataca todos os inimigos dentro do alcance — AoE.',
  };
  document.getElementById('sk-alvo-dica').textContent = dicas[v] || '';
}

function skAbrirFormEfeito() {
  const fields = ['sef-dot-fields','sef-hot-fields','sef-boost-fields','sef-rec-fields','sef-mov-fields','sef-atk-fields','sef-deb-fields'];
  const checks = ['sef-dot-on','sef-hot-on','sef-boost-on','sef-rec-on','sef-mov-on','sef-atk-on','sef-deb-on'];
  const inputs = ['sef-nome','sef-dot-formula','sef-hot-formula','sef-rec-atributo','sef-rec-formula'];
  fields.forEach(id => { const el = document.getElementById(id); if(el) el.style.display='none'; });
  checks.forEach(id => { const el = document.getElementById(id); if(el) el.checked=false; });
  inputs.forEach(id => { const el = document.getElementById(id); if(el) el.value=''; });
  document.getElementById('sef-dot-turnos').value  = 3;
  document.getElementById('sef-hot-turnos').value  = 3;
  document.getElementById('sef-boost-mod').value   = 3;
  document.getElementById('sef-boost-turnos').value= 2;
  document.getElementById('sef-rec-modo').value    = 'imediato';
  document.getElementById('sef-rec-turnos').value  = 3;
  document.getElementById('sef-mov-turnos').value  = 1;
  document.getElementById('sef-atk-turnos').value  = 1;
  document.getElementById('sef-atk-tipo').value    = 'todos';
  document.getElementById('sef-deb-mod').value     = -3;
  document.getElementById('sef-deb-turnos').value  = 2;
  document.getElementById('sk-efeito-form').style.display = 'block';
}

function skCancelarEfeito() {
  document.getElementById('sk-efeito-form').style.display = 'none';
}

function skConfirmarEfeito() {
  const nome = document.getElementById('sef-nome').value.trim();
  if (!nome) { mostrarToast('Dê um nome ao efeito', 'erro'); return; }
  const efeito = { nome };
  // Negativos
  if (document.getElementById('sef-dot-on').checked) {
    efeito.dot_formula = document.getElementById('sef-dot-formula').value.trim() || '1d6';
    efeito.dot_turnos  = parseInt(document.getElementById('sef-dot-turnos').value) || 3;
  }
  if (document.getElementById('sef-mov-on').checked) {
    efeito.sem_movimento        = true;
    efeito.sem_movimento_turnos = parseInt(document.getElementById('sef-mov-turnos').value) || 1;
  }
  if (document.getElementById('sef-atk-on').checked) {
    efeito.sem_ataque        = true;
    efeito.sem_ataque_tipo   = document.getElementById('sef-atk-tipo').value || 'todos';
    efeito.sem_ataque_turnos = parseInt(document.getElementById('sef-atk-turnos').value) || 1;
  }
  if (document.getElementById('sef-deb-on').checked) {
    efeito.mod_dano        = parseInt(document.getElementById('sef-deb-mod').value) || -3;
    efeito.mod_dano_turnos = parseInt(document.getElementById('sef-deb-turnos').value) || 2;
  }
  // Positivos
  if (document.getElementById('sef-hot-on').checked) {
    efeito.hot_formula = document.getElementById('sef-hot-formula').value.trim() || '1d6';
    efeito.hot_turnos  = parseInt(document.getElementById('sef-hot-turnos').value) || 3;
  }
  if (document.getElementById('sef-boost-on').checked) {
    efeito.boost_dano        = parseInt(document.getElementById('sef-boost-mod').value) || 3;
    efeito.boost_dano_turnos = parseInt(document.getElementById('sef-boost-turnos').value) || 2;
  }
  if (document.getElementById('sef-rec-on').checked) {
    efeito.rec_atributo = document.getElementById('sef-rec-atributo').value.trim();
    efeito.rec_formula  = document.getElementById('sef-rec-formula').value.trim() || '10';
    efeito.rec_modo     = document.getElementById('sef-rec-modo').value;
    efeito.rec_turnos   = parseInt(document.getElementById('sef-rec-turnos').value) || 3;
  }
  SK_EFEITOS_TEMP.push(efeito);
  skRenderEfeitosLista();
  document.getElementById('sk-efeito-form').style.display = 'none';
}

function skRemoverEfeito(idx) {
  SK_EFEITOS_TEMP.splice(idx, 1);
  skRenderEfeitosLista();
}

function skRenderEfeitosLista() {
  const el = document.getElementById('sk-efeitos-lista');
  if (!el) return;
  el.innerHTML = SK_EFEITOS_TEMP.map((ef, i) => {
    const tags = [];
    // Negativos
    if (ef.dot_formula)       tags.push({ txt: `🩸 DOT ${ef.dot_formula}×${ef.dot_turnos}t`,      cor: '#e8604c' });
    if (ef.sem_movimento)     tags.push({ txt: `🚫 Mov. ${ef.sem_movimento_turnos}t`,               cor: '#e8604c' });
    if (ef.sem_ataque)        tags.push({ txt: `⚔🚫 Atk(${ef.sem_ataque_tipo}) ${ef.sem_ataque_turnos}t`, cor: '#e8604c' });
    if (ef.mod_dano != null && ef.mod_dano !== undefined && ef.mod_dano < 0)
      tags.push({ txt: `📉 Dano ${ef.mod_dano}×${ef.mod_dano_turnos}t`, cor: '#e8604c' });
    // Positivos
    if (ef.hot_formula)       tags.push({ txt: `💚 HOT ${ef.hot_formula}×${ef.hot_turnos}t`,       cor: '#5ee09a' });
    if (ef.boost_dano)        tags.push({ txt: `⚡ Dano +${ef.boost_dano}×${ef.boost_dano_turnos}t`,cor: '#f0cc6a' });
    if (ef.rec_atributo)      tags.push({ txt: `🔷 ${ef.rec_atributo} ${ef.rec_formula}${ef.rec_modo==='turno'?'×'+ef.rec_turnos+'t':' (imediato)'}`, cor: '#b07ef0' });
    const ehBuff = !!(ef.hot_formula || ef.boost_dano || ef.rec_atributo);
    const corBorda = ehBuff ? 'rgba(94,224,154,0.25)' : 'rgba(232,96,76,0.2)';
    return `<div style="display:flex;justify-content:space-between;align-items:flex-start;background:rgba(10,15,25,0.5);border:1px solid ${corBorda};border-radius:6px;padding:7px 10px">
      <div>
        <span style="font-family:var(--fonte-d);font-size:0.78rem;color:${ehBuff?'#5ee09a':'#e87060'}">${ef.nome}</span>
        <div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px">
          ${tags.map(t=>`<span style="font-size:0.64rem;background:${t.cor}18;border:1px solid ${t.cor}33;border-radius:4px;padding:1px 5px;color:${t.cor}">${t.txt}</span>`).join('')}
        </div>
      </div>
      <button onclick="skRemoverEfeito(${i})" style="background:none;border:none;color:#e74c3c66;cursor:pointer;font-size:0.9rem;padding:0 0 0 8px;flex-shrink:0">✕</button>
    </div>`;
  }).join('') || '<div style="font-size:0.78rem;color:var(--suave);font-style:italic">Nenhum efeito bônus</div>';
}

// ── Distância entre personagens no mapa atual ─────────────────
function atkDistanciaCelulas(nomeA, nomeB) {
  const mapId = MAPA_STATE?.mapaAtualId || null;
  if (!mapId) return null; // sem mapa ativo → sem restrição
  const chars  = COMBATE.contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const charA  = chars.find(c => c.nome === nomeA);
  const charB  = chars.find(c => c.nome === nomeB);
  if (!charA || !charB) return null;

  // Posições como % (0-100)
  let posA, posB;
  if (COMBATE.contexto === 'arena') {
    posA = (charA.custom_attrs?.pos) || null;
    posB = (charB.custom_attrs?.pos) || null;
  } else {
    posA = getPosicaoNoMapa(charA, mapId);
    posB = getPosicaoNoMapa(charB, mapId);
  }
  if (!posA || !posB) return null;

  // Converte % → pixels usando o elemento do mapa
  const imgEl = document.getElementById('mapa-img');
  if (!imgEl) return null;
  const W = imgEl.offsetWidth || 1;
  const H = imgEl.offsetHeight || 1;
  const dx = (posB.x - posA.x) / 100 * W;
  const dy = (posB.y - posA.y) / 100 * H;
  const distPx = Math.sqrt(dx*dx + dy*dy);

  // Mapa atual
  const entry = (RPG_DATA?.mapas || []).find(l => l.mapa.map_id === mapId);
  const gridPx = entry?.mapa?.grid || 20;
  return distPx / gridPx; // distância em células
}

// ── Verifica se atacante está bloqueado de atacar ─────────────
function atkVerificarBloqueioAtaque(nomeAtacante, tipoDanoHabilidade) {
  const chars = COMBATE.contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const c = chars.find(x => x.nome === nomeAtacante);
  if (!c) return null;
  const buffs = c.buffs || [];
  for (const b of buffs) {
    if (!b.sem_ataque || (b.sem_ataque_turnos_restantes ?? 0) <= 0) continue;
    const tipo = b.sem_ataque_tipo || 'todos';
    if (tipo === 'todos') return `${nomeAtacante} está impedido de atacar (${b.nome})`;
    // Classifica a habilidade: físico ou mágico
    const ehFisico = ['fisico','outro'].includes(tipoDanoHabilidade);
    const ehMagico = ['magico','fogo','gelo','veneno','psiquico','cura'].includes(tipoDanoHabilidade);
    if (tipo === 'fisico' && ehFisico) return `${nomeAtacante} está impedido de ataques físicos (${b.nome})`;
    if (tipo === 'magico' && ehMagico) return `${nomeAtacante} está impedido de ataques mágicos (${b.nome})`;
  }
  return null;
}

// ── 18E: Fluxo de combate ────────────────────────────────────
function atkIrParaStep(n) {
  COMBATE.step = n;
  ['atk-step-1','atk-step-2','atk-step-3','atk-step-pendente'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
  const stepId = n === 'pendente' ? 'atk-step-pendente' : `atk-step-${n}`;
  const el = document.getElementById(stepId);
  if (el) el.style.display = 'block';
}

function atkVoltarStep(n) { if (n === 1) mapaHideRangeCircle(); atkIrParaStep(n); }

// Jogador clica "Ir para o mapa" após rolar com animação pendente
function atkIrParaMapa() {
  fecharModalAtaque(); // fecharModalAtaque detecta _pendingTrigger e mostra o card flutuante
}

function atkSelecionarHabilidade(idx) {
  const h = COMBATE._habilidades[idx];
  COMBATE.habilidadeSel = h;
  const alvoTipo = h.alvo_tipo || 'inimigo';

  // Mostrar círculo de alcance no mapa (campanha)
  if (h.alcance_celulas != null && COMBATE.contexto === 'campanha') {
    mapaShowRangeCircle(COMBATE.atacanteNome, h.alcance_celulas);
  } else {
    mapaHideRangeCircle();
  }

  // Skill que afeta apenas o próprio: aplica imediatamente
  if (alvoTipo === 'proprio') {
    COMBATE.alvoNome = COMBATE.atacanteNome;
    atkMontarSelecaoAlvo(); // preenche resumo
    atkAplicarSkillSuporte([COMBATE.atacanteNome]);
    return;
  }
  // Skill AoE aliados: aplica a todos sem perguntar
  if (alvoTipo === 'todos_aliados') {
    atkMontarSelecaoAlvo();
    const aliados = atkListarAlvos().filter(a => !a.foraAlcance).map(a => a.nome);
    aliados.push(COMBATE.atacanteNome); // inclui o próprio
    atkAplicarSkillSuporte(aliados);
    return;
  }
  // Skill AoE inimigos: vai para step 2 (lista tudo, aplica a todos)
  if (alvoTipo === 'todos_inimigos') {
    atkMontarSelecaoAlvo();
    atkIrParaStep(2);
    return;
  }
  // aliado ou inimigo: vai para step 2 de seleção normal
  atkMontarSelecaoAlvo();
  atkIrParaStep(2);
}

// Aplica buff/suporte imediatamente a uma lista de alvos (sem dano)
async function atkAplicarSkillSuporte(alvos) {
  const h = COMBATE.habilidadeSel;
  const { atacanteNome, contexto } = COMBATE;

  // ── Habilidade de cura COM fórmula → passa pelo trigger card (permite crítico) ─
  if (h.formula_dano && h.tipo_dano === 'cura') {
    COMBATE.alvoNome  = alvos[0];
    COMBATE._alvosAoE = alvos.length > 1 ? alvos : null;
    atkPrepararStep3();
    atkIrParaStep(3);
    return;
  }

  const efeitos = Array.isArray(h.efeitos_bonus) ? h.efeitos_bonus : [];

  // Descontar custo de recurso
  if (h.custo_rsv) await descontarCustoSkill(atacanteNome, h.custo_rsv, contexto);

  for (const nomeAlvo of alvos) {
    // Efeitos bônus (buffs positivos)
    for (const ef of efeitos) await atkAplicarEfeito(nomeAlvo, ef, contexto);
  }

  // Cooldown
  if (contexto === 'arena' && h.id && (h.cooldown_turnos || 0) > 0) {
    if (!AR.estado.cooldowns) AR.estado.cooldowns = {};
    AR.estado.cooldowns[h.id] = h.cooldown_turnos;
  }

  const logMsg = `✨ ${atacanteNome} usou "${h.nome}" em ${alvos.join(', ')}`;
  if (contexto === 'arena') {
    arAddLog(logMsg); await arSalvarEstado();
    renderArenaPersonagens(); renderArenaEntidades(); renderArenaEfeitos();
  } else {
    mostrarToast(logMsg, '');
  }
  fecharModalAtaque();
  mostrarToast(`"${h.nome}" aplicado em ${alvos.join(', ')}!`, 'sucesso');
  if (contexto === 'campanha' && BATALHA_ATUAL_ID) await batalhaPassarVez();

  // ── Efeito crítico para buff sem fórmula (baseado em critico_positivo) ─
  const ehMestre = (contexto === 'arena' ? AR?.myRole : RPG_DATA?.myRole) === 'mestre';
  if (ehMestre && h.critico_positivo) {
    setTimeout(() => abrirModalCriticoMestre(alvos, true, h.critico_positivo, contexto), 300);
  }
}

async function atkAplicarCura(nomeAlvo, cura, contexto) {
  if (!cura) return;
  if (contexto === 'arena') {
    const c = AR.chars.find(x => x.nome === nomeAlvo);
    if (!c) return;
    const hpMax = c.custom_attrs?.hp_max ?? 100;
    c.hp_atual = Math.min(hpMax, (c.hp_atual ?? hpMax) + cura);
    await arSb(`characters?rpg_id=eq.${encodeURIComponent(AR.session.rpg_id)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ hp_atual: c.hp_atual }) });
  } else {
    const c = RPG_DATA?.characters.find(x => x.nome === nomeAlvo);
    if (!c) return;
    const hpMax = c.custom_attrs?.hp_max ?? 100;
    c.hp_atual = Math.min(hpMax, (c.hp_atual ?? hpMax) + cura);
    await saveCharacterStats(RPG_DATA.rpgId, nomeAlvo, { hp_atual: c.hp_atual });
  }
}

async function atkAplicarRecuperacaoAtributo(nomeAlvo, atributo, quantidade, contexto) {
  if (!atributo || !quantidade) return;
  const chars = contexto === 'arena' ? AR.chars : (RPG_DATA?.characters || []);
  const c = chars.find(x => x.nome === nomeAlvo);
  if (!c || !c.custom_attrs) return;
  if (!c.custom_attrs.atributos) c.custom_attrs.atributos = {};
  const atual = parseFloat(c.custom_attrs.atributos[atributo]) || 0;
  c.custom_attrs.atributos[atributo] = atual + quantidade;
  if (contexto === 'arena') {
    await arSb(`characters?rpg_id=eq.${encodeURIComponent(AR.session.rpg_id)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ custom_attrs: c.custom_attrs }) });
  } else {
    await sb(`characters?rpg_id=eq.${encodeURIComponent(RPG_DATA.rpgId)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ custom_attrs: c.custom_attrs }) });
  }
}

// ── SISTEMA DE CUSTO DE RECURSO (Mana, Stamina, Ki, etc.) ────
function parsearCustoRSV(custo_rsv) {
  if (!custo_rsv) return null;
  const s = custo_rsv.trim();
  if (!s || /^passiv/i.test(s)) return null;
  const match = s.match(/^(\d+(?:\.\d+)?)\s+(.+)$/);
  if (!match) return null;
  return { quantidade: parseFloat(match[1]), atributo: match[2].trim() };
}

function verificarCustoSkill(atacanteNome, custo_rsv, contexto) {
  const parsed = parsearCustoRSV(custo_rsv);
  if (!parsed) return { ok: true };
  const chars = contexto === 'arena' ? (AR?.chars || []) : (RPG_DATA?.characters || []);
  const c = chars.find(x => x.nome === atacanteNome);
  const atual = parseFloat(c?.custom_attrs?.atributos?.[parsed.atributo]) || 0;
  if (atual < parsed.quantidade) {
    return { ok: false, atributo: parsed.atributo, custo: parsed.quantidade, atual };
  }
  return { ok: true, atributo: parsed.atributo, quantidade: parsed.quantidade };
}

async function descontarCustoSkill(atacanteNome, custo_rsv, contexto) {
  const parsed = parsearCustoRSV(custo_rsv);
  if (!parsed) return;
  await atkAplicarRecuperacaoAtributo(atacanteNome, parsed.atributo, -parsed.quantidade, contexto);
  mostrarToast(`−${parsed.quantidade} ${parsed.atributo}`, '');
}

function atkSelecionarCriativo() {
  const desc = document.getElementById('atk-criativo-desc').value.trim();
  if (!desc) { mostrarToast('Descreva a ação criativa', 'erro'); return; }
  COMBATE.habilidadeSel = { criativo: true, descricao: desc, nome: 'Ação Criativa', formula_dano: null, cooldown_turnos: 0 };
  atkMontarSelecaoAlvo();
  atkIrParaStep(2);
}

function atkMontarSelecaoAlvo() {
  const h = COMBATE.habilidadeSel;
  const alvoTipo = h.alvo_tipo || 'inimigo';
  const ehBuff = alvoTipo === 'aliado' || alvoTipo === 'proprio' || alvoTipo === 'todos_aliados';
  const corAcao = ehBuff ? '#5ee09a' : '#e8604c';
  const labelAcao = ehBuff ? '✨ Suporte / Buff' : '⚔ Ataque';
  document.getElementById('atk-habilidade-resumo').innerHTML = `
    <strong style="color:${corAcao}">${h.nome}</strong>
    <span style="font-size:0.7rem;color:${corAcao};margin-left:6px;background:${corAcao}15;border:1px solid ${corAcao}33;border-radius:4px;padding:1px 6px">${labelAcao}</span><br>
    ${h.formula_dano ? `<span style="color:#f0cc6a">🎲 ${h.formula_dano}</span> · ` : ''}
    ${h.alcance_celulas != null ? `<span style="color:#7ec8f0">⟷ ${h.alcance_celulas} células</span> · ` : ''}
    <span style="color:#9a8888">${h.efeito || h.descricao || ''}</span>
  `;

  // Título do step 2
  const tituloEl = document.getElementById('atk-step2-titulo');
  if (tituloEl) tituloEl.textContent = ehBuff ? 'Selecionar Aliado' : 'Selecionar Alvo';

  const alvos = atkListarAlvos();
  COMBATE._alvos = alvos;
  document.getElementById('atk-alvos-lista').innerHTML = alvos.map((a, i) => {
    const cor = a.cor || (ehBuff ? '#5ee09a' : '#7ec8f0');
    const foraAlcance = a.foraAlcance;
    const distLabel = a.distCelulas != null ? ` · ${a.distCelulas.toFixed(1)}c` : '';
    return `<div onclick="${foraAlcance
      ? `mostrarToast('Alvo fora do alcance (${a.distCelulas?.toFixed(1)} de ${h.alcance_celulas} células)','erro')`
      : `atkSelecionarAlvo(${i})`}"
      style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:rgba(20,12,12,0.8);border:1px solid ${cor}22;border-left:2px solid ${foraAlcance?'#444':cor};border-radius:8px;cursor:${foraAlcance?'default':'pointer'};opacity:${foraAlcance?'0.4':'1'};transition:all 0.15s"
      ${foraAlcance ? '' : `onmouseenter="this.style.borderColor='${cor}55'" onmouseleave="this.style.borderColor='${cor}22'"`}>
      <div style="flex:1">
        <div style="font-family:'Cinzel',serif;font-size:0.85rem;color:${foraAlcance?'#556':cor}">${a.nome}</div>
        <div style="font-size:0.72rem;color:#7a6060">${a.tipo||'personagem'} · HP: ${a.hp}/${a.hpMax||a.hp}${distLabel}${foraAlcance ? ' · 🚫 fora do alcance' : ''}</div>
      </div>
      <span style="color:${foraAlcance?'#444':cor};font-size:0.8rem">›</span>
    </div>`;
  }).join('') || '<div style="color:#7a6060;font-style:italic;padding:10px">Sem alvos disponíveis</div>';
}

function atkListarAlvos() {
  const meuNome  = COMBATE.atacanteNome;
  const h        = COMBATE.habilidadeSel;
  const alvoTipo = h?.alvo_tipo || 'inimigo';
  const ehBuff   = alvoTipo === 'aliado' || alvoTipo === 'todos_aliados';
  const pvpAtivo = COMBATE.contexto === 'arena' || (CURRENT_RPG?.theme?.pvp_ativo === true);
  let lista = [];

  if (COMBATE.contexto === 'arena') {
    const meuChar = AR.chars.find(c => c.nome === meuNome);
    const meuTipo = meuChar?.custom_attrs?.tipo || 'jogador';
    lista = (AR.chars || [])
      .filter(c => {
        if (c.nome === meuNome) return ehBuff; // próprio: inclui se buff
        const tipo = c.custom_attrs?.tipo || 'jogador';
        const ehNpc = tipo !== 'jogador';
        const meuTimeNpc = meuTipo !== 'jogador';
        if (ehBuff) {
          // Aliados: mesmo time
          return ehNpc === meuTimeNpc;
        } else {
          // Inimigos: time oposto
          if (ehNpc === meuTimeNpc && !pvpAtivo) return false;
          return (c.hp_atual ?? 100) > 0;
        }
      })
      .map(c => ({ nome: c.nome, cor: c.custom_attrs?.cor || '#e8604c', tipo: c.custom_attrs?.tipo || 'jogador', hp: c.hp_atual ?? (c.custom_attrs?.hp_max??100), hpMax: c.custom_attrs?.hp_max??100 }));
  } else {
    const atacanteChar = (RPG_DATA?.characters||[]).find(x => x.nome === meuNome);
    const atacanteMapId = atacanteChar?.active_map_id || null;
    // Restringir alvos aos participantes da batalha em andamento (se houver)
    const _bidAtk = batalhaIdMinha() || BATALHA_ATUAL_ID;
    const _bsAtk  = _bidAtk ? MAPA_STATE?.batalhas?.[_bidAtk] : null;
    const _partBatalha = _bsAtk?.participantes?.map(p => p.nome) || null;
    lista = (RPG_DATA?.characters || [])
      .filter(c => {
        // Só elegíveis que estão na mesma batalha
        if (_partBatalha && !_partBatalha.includes(c.nome)) return false;
        const tipo = c.custom_attrs?.tipo_personagem || c.custom_attrs?.tipo || 'jogador';
        const ehNpc = tipo === 'npc' || tipo === 'criatura' || tipo === 'objeto';
        const atacanteTipo = atacanteChar?.custom_attrs?.tipo_personagem || atacanteChar?.custom_attrs?.tipo || 'jogador';
        const atacanteEhNpc = atacanteTipo === 'npc' || atacanteTipo === 'criatura';
        const mestreAtacando = RPG_DATA?.myRole === 'mestre';
        if (c.nome === meuNome) return ehBuff; // próprio: inclui se buff
        // Filtrar pelo mesmo local (active_map_id) quando o atacante está em um mapa
        if (atacanteMapId && c.active_map_id && c.active_map_id !== atacanteMapId) return false;
        if (ehBuff) {
          // Aliados: mesmo time
          return ehNpc === atacanteEhNpc || mestreAtacando;
        } else {
          // PvP: bloquear ataque a jogadores E suas criaturas/montarias vinculadas quando PvP desativado
          const vinculadoAJogador = !ehNpc && !pvpAtivo ? false : (() => {
            if (ehNpc && c.custom_attrs?.vinculado_a) {
              const dono = (RPG_DATA?.characters||[]).find(x => x.nome === c.custom_attrs.vinculado_a);
              const donoTipo = dono?.custom_attrs?.tipo_personagem || dono?.custom_attrs?.tipo || 'jogador';
              return donoTipo === 'jogador'; // criatura vinculada a um jogador
            }
            return false;
          })();
          if (!ehNpc && !pvpAtivo && !atacanteEhNpc) return false;
          if (vinculadoAJogador && !pvpAtivo && !atacanteEhNpc) return false;
          return (c.hp_atual ?? 0) > 0; // só alvos com HP > 0 são atacáveis
        }
      })
      .map(c => ({
        nome: c.nome,
        cor:  c.custom_attrs?.cor || (ehBuff ? '#5ee09a' : '#7ec8f0'),
        tipo: c.custom_attrs?.tipo_personagem || c.custom_attrs?.tipo || 'jogador',
        hp:   c.hp_atual ?? (c.custom_attrs?.hp_max??100),
        hpMax: c.custom_attrs?.hp_max??100,
      }));
  }

  // Calcular distância e flag de alcance
  const alcance = h?.alcance_celulas ?? null;
  const mapaId  = MAPA_STATE?.mapaAtualId || null;
  return lista
    .map(a => {
      const dist = atkDistanciaCelulas(meuNome, a.nome);
      // Sem posição no mapa atual + alcance definido → não aplicar restrição de alcance
      if (alcance != null && mapaId && COMBATE.contexto !== 'arena') {
        const charA = (RPG_DATA?.characters||[]).find(x => x.nome === meuNome);
        const charB = (RPG_DATA?.characters||[]).find(x => x.nome === a.nome);
        const semPosA = !getPosicaoNoMapa(charA, mapaId);
        const semPosB = !getPosicaoNoMapa(charB, mapaId);
        // Só bloqueia por alcance se AMBOS estiverem posicionados no mapa
        if (semPosA || semPosB) return { ...a, distCelulas: null, foraAlcance: false };
      }
      const foraAlcance = alcance != null && dist != null && dist > alcance;
      return { ...a, distCelulas: dist, foraAlcance };
    })
    .sort((a, b) => (a.foraAlcance ? 1 : 0) - (b.foraAlcance ? 1 : 0));
}

// ── Seleção de alvo → prepara step 3 ────────────────────────
function atkSelecionarAlvo(idx) {
  const a = COMBATE._alvos[idx];
  COMBATE.alvoNome = a.nome;
  const h = COMBATE.habilidadeSel;
  document.getElementById('atk-alvo-resumo').textContent = `Alvo: ${a.nome}`;
  // ── Verificar custo de recurso ────────────────────────────
  if (!h.criativo && h.custo_rsv) {
    const check = verificarCustoSkill(COMBATE.atacanteNome, h.custo_rsv, COMBATE.contexto);
    if (!check.ok) {
      mostrarToast(`❌ Sem ${check.atributo} suficiente! (precisa ${check.custo}, tem ${check.atual})`, 'erro');
      return;
    }
  }

  if (h.criativo) { atkEnviarAtaqueCriativo(); return; }
  const alvoTipo = h.alvo_tipo || 'inimigo';
  const ehBuff = alvoTipo === 'aliado' || alvoTipo === 'proprio';
  // Skill ofensiva fora de combate → solicitar aprovação do mestre
  if (!ehBuff && COMBATE._estadoAtk === 'fora_combate' && RPG_DATA?.myRole !== 'mestre') {
    atkEnviarSolicitacaoSkill(); return;
  }
  if (ehBuff) {
    atkAplicarSkillSuporte([a.nome]);
    return;
  }
  if (alvoTipo === 'todos_inimigos') {
    const todos = COMBATE._alvos.filter(x => !x.foraAlcance).map(x => x.nome);
    // Fora de combate: ainda enviar para aprovação (AoE)
    if (COMBATE._estadoAtk === 'fora_combate' && RPG_DATA?.myRole !== 'mestre') {
      atkEnviarSolicitacaoSkill(); return;
    }
    atkAplicarAoEInimigos(todos);
    return;
  }
  atkPrepararStep3();
  atkIrParaStep(3);
}

async function atkAplicarAoEInimigos(alvos) {
  const { atacanteNome, habilidadeSel: h, contexto } = COMBATE;
  // Aguarda o jogador rolar os dados (abre step 3 com multi-alvo pendente)
  COMBATE._alvosAoE = alvos;
  atkPrepararStep3();
  atkIrParaStep(3);
}

function atkPrepararStep3() {
  const h = COMBATE.habilidadeSel;
  const { atacanteNome, contexto } = COMBATE;
  COMBATE.formulaBuilder = [];
  COMBATE.dadosRolados   = null;
  COMBATE.rolando        = false;

  const grupos = parsearFormulaDano(h.formula_dano);

  // Calcular bônus de atributo e injetar como grupo fixo
  const modAttr = calcModAtributo(h, atacanteNome, contexto);
  if (modAttr !== 0 && grupos) {
    grupos.push({ tipo: 'fixo', valor: modAttr });
  }

  const temFormula = grupos && grupos.length > 0;

  const secFormula   = document.getElementById('atk-sec-formula');
  const secBuilder   = document.getElementById('atk-sec-builder');
  const formulaEl    = document.getElementById('atk-formula-exibida');
  const dadosEl      = document.getElementById('atk-dados-individuais');
  const totalEl      = document.getElementById('atk-total-dano');
  const btnRolar     = document.getElementById('atk-btn-rolar');
  const btnConfirmar = document.getElementById('atk-btn-confirmar');
  const btnDelegar   = document.getElementById('atk-btn-delegar');

  dadosEl.innerHTML = '';
  totalEl.textContent = '—';
  btnConfirmar.style.display = 'none';
  // Resetar botão rolar e esconder botão ir-para-mapa
  btnRolar.disabled = false;
  btnRolar.textContent = '🎲 Rolar Dados';
  btnRolar.style.cssText = 'width:100%;padding:12px;background:linear-gradient(135deg,#9b2020,#c0392b);border:none;border-radius:8px;color:#fff;font-family:\'Cinzel\',serif;font-size:0.78rem;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:10px';
  const _btnMapa = document.getElementById('atk-btn-ir-mapa');
  if (_btnMapa) _btnMapa.style.display = 'none';

  if (temFormula) {
    secFormula.style.display = 'block';
    secBuilder.style.display = 'none';
    // Mostrar fórmula base + modificador de atributo se houver
    let formulaLabel = h.formula_dano || '';
    if (modAttr !== 0 && h.atributo_base && h.mod_atributo_pct) {
      const sinal = modAttr >= 0 ? '+' : '';
      formulaLabel += ` ${sinal}${modAttr} (${h.mod_atributo_pct}% ${h.atributo_base})`;
    }
    formulaEl.textContent    = formulaLabel;
    document.getElementById('atk-formula-db-label').textContent = formulaLabel;
    btnRolar.style.display   = 'block';
    btnRolar.textContent     = '🎲 Rolar Dados';
    btnRolar.disabled        = false;
    btnRolar.onclick         = atkRolarDados;
    btnDelegar.style.display = 'none';
    COMBATE._gruposFormula   = grupos;
  } else {
    secFormula.style.display = 'none';
    secBuilder.style.display = 'block';
    formulaEl.textContent    = '—';
    btnRolar.style.display   = 'none';
    btnRolar.onclick         = atkRolarDados;
    btnDelegar.style.display = 'block';
    COMBATE._gruposFormula   = null;
    atkAtualizarBuilder();
  }
}

// ── Builder de dados (sem fórmula no DB) ────────────────────
function atkAdicionarDado(faces) {
  const existente = COMBATE.formulaBuilder.find(g => g.tipo === 'dado' && g.faces === faces);
  if (existente) existente.qtd++;
  else COMBATE.formulaBuilder.push({ tipo: 'dado', qtd: 1, faces });
  atkAtualizarBuilder();
}

function atkRemoverDado(faces) {
  const idx = COMBATE.formulaBuilder.findIndex(g => g.tipo === 'dado' && g.faces === faces);
  if (idx < 0) return;
  COMBATE.formulaBuilder[idx].qtd--;
  if (COMBATE.formulaBuilder[idx].qtd <= 0) COMBATE.formulaBuilder.splice(idx, 1);
  atkAtualizarBuilder();
}

function atkLimparBuilder() {
  COMBATE.formulaBuilder = [];
  atkAtualizarBuilder();
}

function atkAtualizarBuilder() {
  const formula = formulaDeGrupos(COMBATE.formulaBuilder);
  document.getElementById('atk-formula-exibida').textContent = formula;
  const btnRolar = document.getElementById('atk-btn-rolar');
  const temDados = COMBATE.formulaBuilder.length > 0;
  btnRolar.style.display = temDados ? 'block' : 'none';
  btnRolar.textContent   = '🎲 Rolar Dados';
  // Chips dos dados selecionados
  const chipsEl = document.getElementById('atk-builder-chips');
  if (chipsEl) {
    chipsEl.innerHTML = COMBATE.formulaBuilder.map(g => {
      if (g.tipo !== 'dado') return '';
      return `<div style="display:flex;align-items:center;gap:4px;background:rgba(232,80,60,0.12);border:1px solid rgba(232,80,60,0.3);border-radius:20px;padding:3px 10px 3px 6px">
        <span style="font-family:'Cinzel',serif;font-size:0.85rem;color:#e8604c">${g.qtd}d${g.faces}</span>
        <button onclick="atkRemoverDado(${g.faces})" style="background:none;border:none;color:#e8604c88;cursor:pointer;font-size:1rem;padding:0 0 0 3px;line-height:1">−</button>
      </div>`;
    }).join('');
  }
}

// ── Animação de rolar dados (sequencial) ────────────────────
async function atkRolarDados() {
  if (COMBATE.rolando) return;
  const grupos = COMBATE._gruposFormula || COMBATE.formulaBuilder;
  if (!grupos || !grupos.length) return;

  // Capturar valores ANTES dos awaits — evita race condition se COMBATE for resetado
  // durante a animação dos dados (ex: evento realtime ou nova chamada de abrirModalAtaque)
  const _habilidadeCapturada = COMBATE.habilidadeSel;
  const _contextoCapturado   = COMBATE.contexto;
  const _roleAtivoCapturado  = _contextoCapturado === 'arena' ? (AR?.myRole) : RPG_DATA?.myRole;

  COMBATE.rolando = true;
  const btnRolar     = document.getElementById('atk-btn-rolar');
  const dadosEl      = document.getElementById('atk-dados-individuais');
  const totalEl      = document.getElementById('atk-total-dano');
  const btnConfirmar = document.getElementById('atk-btn-confirmar');

  btnRolar.disabled = true;
  btnConfirmar.style.display = 'none';
  dadosEl.innerHTML = '';
  totalEl.textContent = '—';

  const resultado = rolarGrupos(grupos);
  COMBATE.dadosRolados = resultado;
  let totalAcumulado = 0;

  for (const dado of resultado.dados) {
    const chip = document.createElement('div');
    chip.style.cssText = `width:44px;height:44px;border-radius:8px;background:rgba(232,80,60,0.1);border:2px solid rgba(232,80,60,0.5);display:flex;align-items:center;justify-content:center;font-family:'Cinzel',serif;font-size:1rem;color:#f0cc6a;flex-shrink:0`;
    chip.title = `d${dado.faces}`;
    dadosEl.appendChild(chip);

    // Animação de embaralhamento ~320ms
    await new Promise(resolve => {
      let elapsed = 0;
      const iv = setInterval(() => {
        chip.textContent = Math.floor(Math.random() * dado.faces) + 1;
        elapsed += 60;
        if (elapsed >= 320) {
          clearInterval(iv);
          chip.textContent    = dado.valor;
          const isCrit        = dado.valor === dado.faces;
          chip.style.borderColor = isCrit ? '#f0cc6a' : 'rgba(232,80,60,0.4)';
          chip.style.background  = isCrit ? 'rgba(240,204,106,0.15)' : 'rgba(232,80,60,0.08)';
          chip.style.color       = isCrit ? '#f0cc6a' : '#e8604c';
          resolve();
        }
      }, 60);
    });

    totalAcumulado += dado.valor;
    totalEl.textContent = totalAcumulado;
    await new Promise(r => setTimeout(r, 100));
  }

  if (resultado.bonus !== 0) {
    totalAcumulado += resultado.bonus;
    totalEl.textContent = totalAcumulado;
  }

  // Sincronizar resultado de volta para COMBATE (pode ter sido resetado, mas preservamos o resultado desta rolagem)
  COMBATE.dadosRolados = resultado;
  // Restaurar habilidadeSel se foi zerado durante os awaits (race condition)
  if (!COMBATE.habilidadeSel && _habilidadeCapturada) {
    COMBATE.habilidadeSel = _habilidadeCapturada;
    COMBATE.contexto = _contextoCapturado;
  }

  // Broadcast: notificar todos que alguém rolou dados
  const _hNome = (COMBATE.habilidadeSel || _habilidadeCapturada)?.nome || 'Ataque';
  const _criticoLabel = resultado.dados?.some(d => d.face === 20 && d.valor === 20) ? '🎯 Crítico Perfeito!' :
                        resultado.dados?.some(d => d.face === 20 && d.valor === 1) ? '💀 Falha Crítica' : null;
  combateBroadcast('dados_rolados', {
    atacante: COMBATE.atacanteNome || _contextoCapturado,
    habilidade: _hNome,
    total: resultado.total,
    critico: _criticoLabel,
  });

  // Sempre redireciona ao mapa — o card flutuante é quem dispara animação + dano
  // (vale para mestre, jogador, com ou sem animação, habilidade catalogada ou criativa)
  COMBATE._pendingTrigger = true;
  COMBATE.rolando = false;
  btnRolar.disabled = true;
  const btnMapa = document.getElementById('atk-btn-ir-mapa');
  if (btnMapa) btnMapa.style.display = 'block';
}

// ── Delegar ao mestre ────────────────────────────────────────
async function atkDelegarAoMestre() {
  const { atacanteNome, alvoNome, habilidadeSel: h, contexto } = COMBATE;
  const formulaStr = formulaDeGrupos(COMBATE.formulaBuilder) || '(sem fórmula)';
  const pendente = {
    id: 'ap_' + Date.now(),
    atacante: atacanteNome,
    alvo:     alvoNome,
    descricao: `[Delegado] ${h.nome} — fórmula sugerida: ${formulaStr}`,
    turno:  contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
    status: 'pendente',
  };
  if (contexto === 'arena') {
    CRIATIVOS_CAMP.push(pendente);
    CRIATIVO_ID_ATUAL = pendente.id;
    try {
      await arSb('criativos', {method:'POST', body:JSON.stringify({
        rpg_id:   AR.session.rpg_id,
        id:       pendente.id,
        atacante: pendente.atacante,
        alvo:     pendente.alvo,
        descricao:pendente.descricao,
        turno:    pendente.turno || 0,
        status:   'pendente',
      })});
    } catch(e) {}
    if (AR.myRole === 'mestre') {
      fecharModalAtaque();
      abrirModalCriativoMestre(pendente.id);
      return;
    }
    criativoIniciarPolling(pendente.id);
  }
  atkIrParaStep('pendente');
  mostrarToast('Dano delegado ao Mestre', '');
  combateBroadcast('aguardando_aprovacao', {
    atacante: atacanteNome,
    alvo:     alvoNome,
    habilidade: h.nome || 'Ação Criativa',
  });
}

// ── Helper: aplica dano e efeitos sem fechar o modal ────────
async function _atkAplicarDanoFinal() {
  if (COMBATE._jaAplicado) return;
  COMBATE._jaAplicado = true;

  const { atacanteNome, habilidadeSel: h, dadosRolados, contexto } = COMBATE;
  const dano = dadosRolados?.total ?? 0;
  const alvosAtaque = COMBATE._alvosAoE?.length ? COMBATE._alvosAoE : [COMBATE.alvoNome];
  COMBATE._alvosAoE = null;

  if (h.custo_rsv) await descontarCustoSkill(atacanteNome, h.custo_rsv, contexto);

  // ── Aplicar dano ou cura dependendo do tipo ──────────────────
  const ehCura = h.tipo_dano === 'cura';
  if (ehCura) {
    for (const nomeAlvo of alvosAtaque) await atkAplicarCura(nomeAlvo, dano, contexto);
  } else {
    for (const nomeAlvo of alvosAtaque) await atkAplicarDano(nomeAlvo, dano, contexto, h.tipo_dano);
  }

  const efeitos = Array.isArray(h.efeitos_bonus) ? h.efeitos_bonus : (h.efeito_auto ? [h.efeito_auto] : []);
  for (const ef of efeitos) {
    const ehPositivo = !!(ef.hot_formula || ef.boost_dano || ef.rec_atributo);
    const alvoEf = ehPositivo ? atacanteNome : alvosAtaque[0];
    await atkAplicarEfeitoComRecuperacao(alvoEf, ef, contexto);
  }

  if (contexto === 'arena' && h.id && (h.cooldown_turnos || 0) > 0) {
    if (!AR.estado.cooldowns) AR.estado.cooldowns = {};
    AR.estado.cooldowns[h.id] = h.cooldown_turnos;
  }
  const formulaUsada = h.formula_dano || formulaDeGrupos(COMBATE.formulaBuilder) || '';
  const efeitosStr = efeitos.map(e => e.nome).join(', ');
  const logVerbo = ehCura ? 'curou' : 'causou';
  const logMsg = `${ehCura?'✨':'⚔'} ${atacanteNome} usou "${h.nome}" em ${alvosAtaque.join(', ')} — ${dano} de ${ehCura?'cura':'dano'}${formulaUsada ? ` (${formulaUsada})` : ''}${efeitosStr ? ` · Efeitos: ${efeitosStr}` : ''}`;
  if (contexto === 'arena') {
    arAddLog(logMsg); await arSalvarEstado();
    renderArenaPersonagens(); renderArenaEntidades(); renderMesa(); renderArenaEfeitos();
  } else {
    mostrarToast(logMsg, '');
  }
  mostrarToast(`${dano} de ${ehCura?'cura':'dano'} em ${alvosAtaque.join(', ')}!${efeitosStr ? ` +${efeitosStr}` : ''}`, 'sucesso');
  // Broadcast: todos veem o resultado do ataque em tempo real
  combateBroadcast('ataque_executado', {
    atacante: atacanteNome,
    alvo: alvosAtaque.join(', '),
    dano,
    habilidade: h.nome || '',
    efeitos: efeitosStr || null,
  });

  // ── Modal de efeito crítico (apenas mestre) ──────────────────
  const ehCritico = COMBATE._ehCritico;
  const criticoTexto = COMBATE._criticoTexto;
  const criticoEhPositivo = COMBATE._criticoEhPositivo;
  COMBATE._ehCritico = false;
  COMBATE._criticoTexto = null;
  COMBATE._criticoEhPositivo = false;

  if (contexto === 'campanha' && BATALHA_ATUAL_ID) await batalhaPassarVez();

  if (CRIATIVO_ID_ATUAL) {
    const idCriativo = CRIATIVO_ID_ATUAL;
    const c = CRIATIVOS_CAMP.find(x => x.id === idCriativo);
    if (c) {
      // Remover localmente imediatamente
      const idx = CRIATIVOS_CAMP.indexOf(c);
      if (idx >= 0) CRIATIVOS_CAMP.splice(idx, 1);
      if (typeof criativoRenderMestre === 'function') criativoRenderMestre();
      // Deletar do banco (nao fazer PATCH - evita voltar no reload)
      try {
        const rpgId = AR.session?.rpg_id || RPG_DATA?.rpgId;
        if (rpgId) {
          const sbFn = AR.session ? arSb : sb;
          await sbFn(`criativos?rpg_id=eq.${encodeURIComponent(rpgId)}&id=eq.${encodeURIComponent(idCriativo)}`, { method: 'DELETE' });
        }
      } catch(e) { console.warn('Erro ao deletar criativo concluido:', e); }
    }
    criativoStopPolling();
    CRIATIVO_ID_ATUAL = null;
  }

  // Avancar turno automaticamente na arena apos o dano ser aplicado
  if (contexto === 'arena' && typeof AR !== 'undefined' && AR.iniciativa && AR.iniciativa.fase === 'combate') {
    if (AR.myRole === 'mestre') {
      await arProximoTurnoIniciativa();
    } else {
      // Jogador avanca o proprio turno (mesmo mecanismo do arAcaoPassar)
      const ini = AR.iniciativa;
      const meuChar = arMeuChar();
      const atual = ini.ordem[ini.ordemAtual];
      if (atual && atual.nome === meuChar) {
        let prox = (ini.ordemAtual + 1);
        while (prox < ini.ordem.length && ini.ordem[prox]?.vinculado_a) prox++;
        if (prox >= ini.ordem.length) {
          ini.round = (ini.round||1) + 1;
          prox = 0;
          if (typeof avancarTurno === 'function') await avancarTurno();
          arAddLog(`🔄 Round ${ini.round} iniciado`);
        }
        ini.ordemAtual = prox;
        const proximo = ini.ordem[prox];
        arAddLog(`🎯 Vez de: ${proximo?.nome}`);
        await arSalvarEstado();
        if (typeof renderArenaIniciativaUI === 'function') renderArenaIniciativaUI();
        if (typeof renderArenaCenario === 'function') renderArenaCenario();
        arToast(`Vez de ${proximo?.nome || '?'}!`, 'sucesso');
      }
    }
  }

  // ── Abrir modal de efeito crítico para o mestre ──────────────
  const ehMestre = (contexto === 'arena' ? AR?.myRole : RPG_DATA?.myRole) === 'mestre';
  if (ehCritico && ehMestre) {
    setTimeout(() => abrirModalCriticoMestre(alvosAtaque, criticoEhPositivo, criticoTexto, contexto), 400);
  }
}

// ── Confirmar ataque (builder manual / AoE) ──────────────────
// ═══════════════════════════════════════════════════════════════════════════
// ██  BROADCAST DE COMBATE — eventos em tempo real para todos
// ═══════════════════════════════════════════════════════════════════════════

function combateBroadcast(tipo, dados) {
  try {
    const rpgId = AR.session?.rpg_id || RPG_DATA?.rpgId;
    const ws = AR.ws || realtimeWS;
    if (!rpgId || !ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({
      topic:   `realtime:chat:${rpgId}`,
      event:   'broadcast',
      payload: { type: 'broadcast', event: 'combate_evento', payload: { tipo, ...dados, _sid: _ANIM_SID } },
      ref:     'cbt_' + Date.now()
    }));
  } catch(e) {}
}

function combateReceberBroadcast(payload) {
  if (!payload || payload._sid === _ANIM_SID) return; // ignorar eco do próprio emissor

  const { tipo } = payload;

  if (tipo === 'dados_rolados') {
    const criticoStr = payload.critico ? ` — ${payload.critico}` : '';
    mostrarToast(`🎲 ${payload.atacante} rolou ${payload.total} com "${payload.habilidade}"${criticoStr}`, '');
  }

  if (tipo === 'vez_passou') {
    // Atualização imediata de turno antes do DB propagar
    const bid = payload.batalhaId;
    if (bid && MAPA_STATE.batalhas[bid]) {
      const bs = MAPA_STATE.batalhas[bid];
      const anteriorIdx = bs.ordemAtual;
      bs.ordemAtual = payload.ordemAtual;
      if (payload.turnoRound) bs.turnoRound = payload.turnoRound;
      _aplicarEstadoBatalhaUI();
      if (bs.ordemAtual !== anteriorIdx) _notificarVez(bs, bid);
      _atualizarBadgeMesa();
    }
  }

  if (tipo === 'ataque_executado') {
    const efStr = payload.efeitos ? ` + ${payload.efeitos}` : '';
    mostrarToast(`⚔ ${payload.atacante} → ${payload.alvo}: ${payload.dano} de dano${efStr}`, 'sucesso');
  }

  if (tipo === 'aguardando_aprovacao') {
    if (RPG_DATA?.myRole === 'mestre' || AR?.myRole === 'mestre') {
      mostrarToast(`📩 Ação criativa de ${payload.atacante}: "${payload.habilidade}" — aguarda aprovação`, '');
    }
  }

  // ── BATALHA CRIADA ────────────────────────────────────────────────────────
  if (tipo === 'batalha_criada') {
    const { batalhaId, estado } = payload;
    if (!MAPA_STATE.batalhas[batalhaId] && estado) {
      MAPA_STATE.batalhas[batalhaId] = estado;
      _aplicarEstadoBatalhaUI();
      _atualizarBadgeMesa();
      if (typeof _atualizarSeletorBatalhas === 'function') _atualizarSeletorBatalhas();
      mostrarToast(`⚔ Batalha iniciada! Role sua iniciativa.`, '');
    }
  }

  // ── INICIATIVA ROLADA POR UM JOGADOR ──────────────────────────────────────
  if (tipo === 'iniciativa_rolada') {
    const { batalhaId, nome, valor } = payload;
    const bs = MAPA_STATE.batalhas[batalhaId];
    if (bs) {
      bs.iniciativasRoladas[nome] = valor;
      const p = bs.participantes.find(x => x.nome === nome);
      if (p) p.iniciativa = valor;
      bs.empatados = (bs.empatados || []).filter(n => n !== nome);
      if (BATALHA_ATUAL_ID === batalhaId) batalhaRenderFaseIniciativa();
      // Mestre verifica se todos já rolaram para iniciar o combate
      if (RPG_DATA?.myRole === 'mestre') batalhaVerificarIniciativasCompletas(batalhaId);
      _atualizarBadgeMesa();
      mostrarToast(`🎲 ${nome} rolou iniciativa: ${valor}`, '');
    }
  }

  // ── ESTADO GERAL DA BATALHA (fase, empate, combate) ───────────────────────
  if (tipo === 'batalha_estado') {
    const { batalhaId } = payload;
    const bs = MAPA_STATE.batalhas[batalhaId];
    if (bs) {
      if (payload.fase) bs.fase = payload.fase;
      if (payload.participantes) bs.participantes = payload.participantes;
      if (payload.iniciativasRoladas) bs.iniciativasRoladas = payload.iniciativasRoladas;
      if (payload.empatados != null) bs.empatados = payload.empatados;
      if (payload.ordemAtual != null) bs.ordemAtual = payload.ordemAtual;
      if (payload.turnoRound != null) bs.turnoRound = payload.turnoRound;
      _aplicarEstadoBatalhaUI();
      _atualizarBadgeMesa();
      if (payload.fase === 'combate') mostrarToast('⚔ Combate iniciado! Confira a ordem de turnos.', 'sucesso');
      if (payload.fase === 'empate') mostrarToast('⚠ Empate na iniciativa! Re-role seu dado.', '');
    }
  }

  // ── BATALHA PAUSADA / RETOMADA ────────────────────────────────────────────
  if (tipo === 'batalha_pausada') {
    const { batalhaId, pausada } = payload;
    const bs = MAPA_STATE.batalhas[batalhaId];
    if (bs) {
      bs.pausada = pausada;
      if (BATALHA_ATUAL_ID === batalhaId) batalhaRenderVezLabel();
      _atualizarBadgeMesa();
      mostrarToast(pausada ? '⏸ Batalha pausada pelo mestre' : '▶ Batalha retomada pelo mestre', '');
    }
  }

  // ── BATALHA ENCERRADA ─────────────────────────────────────────────────────
  if (tipo === 'batalha_encerrada') {
    const { batalhaId } = payload;
    if (MAPA_STATE.batalhas[batalhaId]) {
      delete MAPA_STATE.batalhas[batalhaId];
      if (BATALHA_ATUAL_ID === batalhaId) BATALHA_ATUAL_ID = null;
      _aplicarEstadoBatalhaUI();
      _atualizarBadgeMesa();
      if (typeof _atualizarSeletorBatalhas === 'function') _atualizarSeletorBatalhas();
      mostrarToast('⚔ Batalha encerrada pelo mestre', '');
    }
  }

  // ── CARD DE TRIGGER (visível para todos) ──────────────────────────────────
  if (tipo === 'trigger_mostrar') {
    _atkMostrarTriggerRemoto(payload);
  }
  if (tipo === 'trigger_ocultar') {
    const el = document.getElementById('atk-anim-trigger');
    if (el) el.style.display = 'none';
    const box = document.getElementById('atk-anim-trigger-box');
    if (box) box.style.pointerEvents = ''; // restaurar clicabilidade para próximo uso
  }

  // ── PERSONAGEM MORTO (marcador X no mapa) ────────────────────────────────
  if (tipo === 'personagem_morto') {
    const { nome } = payload;
    const c = (RPG_DATA?.characters || []).find(x => x.nome === nome);
    if (c) {
      if (!c.custom_attrs) c.custom_attrs = {};
      c.custom_attrs.morto = true;
    }
    const entry = (RPG_DATA?.mapas||[]).find(l => l.mapa.map_id === MAPA_STATE?.mapaAtualId);
    if (entry) mapaRenderTokens(entry.mapa);
    mostrarToast(`💀 ${nome} foi derrotado!`, 'erro');
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ██  MOTOR DE ANIMAÇÃO DE ATAQUE  (Canvas 2D, zero dependências externas)
// ═══════════════════════════════════════════════════════════════════════════

// ── ID de sessão por aba — evita dupla execução no emissor ─────────────────
const _ANIM_SID = Math.random().toString(36).slice(2);

// ── Emite evento de animação para todos via canal de chat ─────────────
function animBroadcast(payload) {
  try {
    const rpgId = AR.session?.rpg_id || RPG_DATA?.rpgId;
    const ws    = AR.ws || realtimeWS;
    if (!rpgId || !ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({
      topic:   `realtime:chat:${rpgId}`,
      event:   'broadcast',
      payload: { type: 'broadcast', event: 'anim_ataque', payload },
      ref:     'anim_' + Date.now()
    }));
  } catch(e) { console.warn('[ANIM] Broadcast falhou:', e); }
}

// ── Recebe e executa animação vinda de outro cliente ───────────────
async function animReceberBroadcast(payload) {
  if (!payload?.animacao?.tipo || payload.animacao.tipo === 'nenhuma') return;
  if (payload.sid === _ANIM_SID) return; // ignorar eco do proprio emissor
  try {
    const ctx = payload.contexto;
    const atacEl = resolverTokenEl(payload.atacanteNome, ctx);
    const alvoEl = resolverTokenEl(payload.alvoNome,     ctx);
    if (atacEl && alvoEl) {
      const repeticoes = Math.max(1, parseInt(payload.animacao.repeticao) || 1);
      for (let i = 0; i < repeticoes; i++) {
        await animarAtaque({ atacEl, alvoEl, animacao: payload.animacao, dano: payload.dano });
        if (i < repeticoes - 1) await new Promise(r => setTimeout(r, 120));
      }
    }
  } catch(e) { console.warn('[ANIM] Erro ao receber animacao remota:', e); }
}

// ── Helper compartilhado: roda animacao localmente E emite para os outros ─
async function _atkRodarAnimacao() {
  const h = COMBATE.habilidadeSel;
  if (!h?.animacao?.tipo || h.animacao.tipo === 'nenhuma') return;

  const payload = {
    sid:           _ANIM_SID,
    atacanteNome:  COMBATE.atacanteNome,
    alvoNome:      COMBATE.alvoNome,
    contexto:      COMBATE.contexto,
    animacao:      h.animacao,
    dano:          COMBATE.dadosRolados?.total ?? null,
  };

  // Emite para os outros ANTES de rodar localmente (nao bloqueia)
  animBroadcast(payload);

  // Roda localmente (com repetições)
  try {
    const atacEl = resolverTokenEl(COMBATE.atacanteNome, COMBATE.contexto);
    const alvoEl = resolverTokenEl(COMBATE.alvoNome,    COMBATE.contexto);
    if (atacEl && alvoEl) {
      const repeticoes = Math.max(1, parseInt(h.animacao.repeticao) || 1);
      for (let i = 0; i < repeticoes; i++) {
        await animarAtaque({ atacEl, alvoEl, animacao: h.animacao, dano: payload.dano });
        if (i < repeticoes - 1) await new Promise(r => setTimeout(r, 120)); // pausa breve entre ciclos
      }
    }
  } catch(e) { console.warn('[ANIM] Erro na animacao local:', e); }
}

// ── Resolve elemento DOM do token pelo nome + contexto ─────────────────────
function resolverTokenEl(nome, contexto) {
  if (!nome) return null;
  const esc = CSS.escape(nome);
  if (contexto === 'arena') {
    return document.querySelector(`.ar-mesa-token[data-nome="${esc}"]`);
  } else {
    return document.querySelector(`.mapa-token[data-nome="${esc}"]`);
  }
}

function _animCriarCanvas() {
  const c = document.createElement('canvas');
  c.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:10100';
  c.width  = window.innerWidth;
  c.height = window.innerHeight;
  document.body.appendChild(c);
  return c;
}

function _animCentro(el) {
  const r = el.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
}

function _animHexToRgb(hex) {
  hex = hex.replace('#','');
  if (hex.length === 3) hex = hex.split('').map(c=>c+c).join('');
  const r = parseInt(hex.slice(0,2),16);
  const g = parseInt(hex.slice(2,4),16);
  const b = parseInt(hex.slice(4,6),16);
  return `${r},${g},${b}`;
}

function animarAtaque({ atacEl, alvoEl, animacao, dano }) {
  return new Promise(resolve => {
    const origem = _animCentro(atacEl);
    const alvo   = _animCentro(alvoEl);
    const cor    = animacao.cor   || '#e74c3c';
    const icone  = animacao.icone || '';
    const trilha = !!animacao.trilha;
    const rgb    = _animHexToRgb(cor);
    const canvas = _animCriarCanvas();
    const ctx    = canvas.getContext('2d');
    function destruir() { canvas.remove(); resolve(); }

    const tipos = {
      projetil: () => _animProjetil(ctx, canvas, origem, alvo, cor, rgb, icone, trilha, destruir),
      onda:     () => _animOnda    (ctx, canvas, origem, alvo, cor, rgb, icone, destruir),
      explosao: () => _animExplosao(ctx, canvas, origem, alvo, cor, rgb, icone, destruir),
      raio:     () => _animRaio    (ctx, canvas, origem, alvo, cor, rgb, icone, destruir),
      aura:     () => _animAura    (ctx, canvas, origem, alvo, cor, rgb, icone, destruir),
      gif:      () => { canvas.remove(); _animMedia(animacao, origem, alvo, resolve); },
      imagem:   () => { canvas.remove(); _animMedia(animacao, origem, alvo, resolve); },
      svg:      () => { canvas.remove(); _animMedia(animacao, origem, alvo, resolve); },
      iframe:   () => { canvas.remove(); _animMedia(animacao, origem, alvo, resolve); },
    };
    const fn = tipos[animacao.tipo];
    if (fn) fn(); else destruir();
  });
}

function _animProjetil(ctx, canvas, origem, alvo, cor, rgb, icone, trilha, done) {
  const dur = 500, start = performance.now();
  const cx = (origem.x + alvo.x) / 2;
  const cy = Math.min(origem.y, alvo.y) - 80;
  const trail = [];
  function bezier(t) {
    return {
      x: (1-t)*(1-t)*origem.x + 2*(1-t)*t*cx + t*t*alvo.x,
      y: (1-t)*(1-t)*origem.y + 2*(1-t)*t*cy + t*t*alvo.y
    };
  }
  function frame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const pos = bezier(t);
    if (trilha) {
      trail.push({ ...pos, t });
      for (let i = trail.length - 1; i >= 0; i--) {
        const p = trail[i], age = t - p.t;
        if (age > 0.35) { trail.splice(0, i + 1); break; }
        const a = (1 - age / 0.35) * 0.6;
        const s = Math.max(2, 10 * (1 - age / 0.35));
        ctx.beginPath(); ctx.arc(p.x, p.y, s, 0, Math.PI*2);
        ctx.fillStyle = `rgba(${rgb},${a})`; ctx.fill();
      }
    }
    const grad = ctx.createRadialGradient(pos.x, pos.y, 0, pos.x, pos.y, 18);
    grad.addColorStop(0, `rgba(${rgb},0.9)`);
    grad.addColorStop(1, `rgba(${rgb},0)`);
    ctx.beginPath(); ctx.arc(pos.x, pos.y, 18, 0, Math.PI*2);
    ctx.fillStyle = grad; ctx.fill();
    if (icone) {
      ctx.font='22px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(icone, pos.x, pos.y);
    } else {
      ctx.beginPath(); ctx.arc(pos.x, pos.y, 7, 0, Math.PI*2);
      ctx.fillStyle = cor; ctx.fill();
    }
    if (t >= 1) { _animImpacto(ctx, alvo, rgb, cor, icone); setTimeout(done, 300); return; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

function _animOnda(ctx, canvas, origem, alvo, cor, rgb, icone, done) {
  const dur = 700, start = performance.now();
  const ondas = [0, 0.2, 0.4];
  function frame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (const off of ondas) {
      const lt = Math.min(Math.max((t - off) / (1 - off), 0), 1);
      if (lt <= 0) continue;
      const raio = lt * 120, alpha = (1 - lt) * 0.7;
      ctx.beginPath(); ctx.arc(origem.x, origem.y, raio, 0, Math.PI*2);
      ctx.strokeStyle = `rgba(${rgb},${alpha})`; ctx.lineWidth = 3*(1-lt)+1; ctx.stroke();
    }
    if (icone) {
      ctx.font = `${20+t*10}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.globalAlpha = 1-t*0.5; ctx.fillText(icone, origem.x, origem.y); ctx.globalAlpha=1;
    }
    if (t >= 1) { done(); return; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

function _animExplosao(ctx, canvas, origem, alvo, cor, rgb, icone, done) {
  const dur = 600, start = performance.now();
  const N = 28;
  const ps = Array.from({length:N},(_,i)=>{
    const ang=(Math.PI*2*i/N)+(Math.random()-0.5)*0.4, spd=60+Math.random()*80;
    return {vx:Math.cos(ang)*spd, vy:Math.sin(ang)*spd, size:3+Math.random()*5};
  });
  function frame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (t < 0.15) {
      const r=t/0.15*40;
      const g=ctx.createRadialGradient(alvo.x,alvo.y,0,alvo.x,alvo.y,r);
      g.addColorStop(0,`rgba(255,255,255,${0.9*(1-t/0.15)})`);
      g.addColorStop(0.5,`rgba(${rgb},0.8)`); g.addColorStop(1,`rgba(${rgb},0)`);
      ctx.beginPath(); ctx.arc(alvo.x,alvo.y,r,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
    }
    for (const p of ps) {
      const px=alvo.x+p.vx*t, py=alvo.y+p.vy*t, alpha=Math.max(0,1-t*1.4);
      ctx.beginPath(); ctx.arc(px,py,p.size*(1-t*0.6),0,Math.PI*2);
      ctx.fillStyle=`rgba(${rgb},${alpha})`; ctx.fill();
    }
    if (icone && t>0.05 && t<0.7) {
      ctx.font=`${28+t*14}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.globalAlpha=Math.max(0,1-t*2); ctx.fillText(icone,alvo.x,alvo.y); ctx.globalAlpha=1;
    }
    if (t >= 1) { done(); return; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

function _animRaio(ctx, canvas, origem, alvo, cor, rgb, icone, done) {
  const dur = 400, start = performance.now();
  let segs = _animGerarZigzag(origem, alvo, 8), lastRegen = 0;
  function frame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (now - lastRegen > 60) { segs = _animGerarZigzag(origem, alvo, 8); lastRegen = now; }
    const alpha = t < 0.7 ? 1 : (1-t)/0.3;
    ctx.save();
    ctx.shadowColor=cor; ctx.shadowBlur=16;
    ctx.strokeStyle=`rgba(${rgb},${alpha*0.4})`; ctx.lineWidth=8;
    ctx.beginPath(); segs.forEach((s,i)=>i===0?ctx.moveTo(s.x,s.y):ctx.lineTo(s.x,s.y)); ctx.stroke();
    ctx.strokeStyle=`rgba(255,255,255,${alpha*0.85})`; ctx.lineWidth=2; ctx.shadowBlur=0;
    ctx.beginPath(); segs.forEach((s,i)=>i===0?ctx.moveTo(s.x,s.y):ctx.lineTo(s.x,s.y)); ctx.stroke();
    ctx.restore();
    if (icone && t > 0.6) {
      ctx.font='28px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.globalAlpha=(t-0.6)/0.4; ctx.fillText(icone,alvo.x,alvo.y); ctx.globalAlpha=1;
    }
    if (t >= 1) { done(); return; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

function _animGerarZigzag(a, b, n) {
  const pts = [a];
  for (let i = 1; i < n; i++) {
    const tt = i/n;
    const bx = a.x+(b.x-a.x)*tt, by = a.y+(b.y-a.y)*tt;
    const px = -(b.y-a.y), py = b.x-a.x;
    const len = Math.sqrt(px*px+py*py)||1;
    const off = (Math.random()-0.5)*40;
    pts.push({x:bx+px/len*off, y:by+py/len*off});
  }
  pts.push(b); return pts;
}

function _animAura(ctx, canvas, origem, alvo, cor, rgb, icone, done) {
  const dur = 800, start = performance.now();
  function frame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const pulse = Math.sin(t*Math.PI*4)*0.5+0.5;
    const raio  = 28+pulse*16;
    const alpha = (t<0.8?1:(1-t)/0.2)*(0.4+pulse*0.4);
    const g = ctx.createRadialGradient(alvo.x,alvo.y,0,alvo.x,alvo.y,raio);
    g.addColorStop(0,`rgba(${rgb},${alpha})`);
    g.addColorStop(0.6,`rgba(${rgb},${alpha*0.5})`);
    g.addColorStop(1,`rgba(${rgb},0)`);
    ctx.beginPath(); ctx.arc(alvo.x,alvo.y,raio,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
    ctx.beginPath(); ctx.arc(alvo.x,alvo.y,raio*1.1,0,Math.PI*2);
    ctx.strokeStyle=`rgba(${rgb},${alpha*0.6})`; ctx.lineWidth=2; ctx.stroke();
    if (icone) {
      ctx.font=`${18+pulse*6}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.globalAlpha=Math.min(1,alpha*2); ctx.fillText(icone,alvo.x,alvo.y); ctx.globalAlpha=1;
    }
    if (t >= 1) { done(); return; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

// ── TIPO: Mídia (gif, imagem, svg, iframe) ─────────────────────────────────
function _animMedia(animacao, origem, alvo, resolve) {
  const { tipo, url, svg, tamanho = 120, duracao = 1500, posicao = 'alvo' } = animacao;

  // Calcular posição do elemento
  let cx, cy;
  if (posicao === 'atacante') {
    cx = origem.x; cy = origem.y;
  } else if (posicao === 'meio') {
    cx = (origem.x + alvo.x) / 2; cy = (origem.y + alvo.y) / 2;
  } else {
    cx = alvo.x; cy = alvo.y;
  }

  // Container overlay
  const wrap = document.createElement('div');
  wrap.style.cssText = `position:fixed;inset:0;pointer-events:none;z-index:10100;overflow:hidden`;

  // Elemento de mídia
  let el;
  const sz = tamanho + 'px';

  if (tipo === 'gif' || tipo === 'imagem') {
    el = document.createElement('img');
    el.src = url;
    el.style.cssText = `width:${sz};height:${sz};object-fit:contain;border-radius:8px;position:absolute`;
  } else if (tipo === 'svg') {
    el = document.createElement('div');
    el.innerHTML = svg;
    el.style.cssText = `width:${sz};height:${sz};display:flex;align-items:center;justify-content:center;position:absolute`;
    const svgEl = el.querySelector('svg');
    if (svgEl) { svgEl.style.width = '100%'; svgEl.style.height = '100%'; }
  } else if (tipo === 'iframe') {
    el = document.createElement('iframe');
    el.src = url;
    el.style.cssText = `width:${sz};height:${sz};border:none;border-radius:8px;position:absolute;background:transparent`;
    el.setAttribute('allowtransparency', 'true');
    el.setAttribute('sandbox', 'allow-scripts allow-same-origin');
  }

  if (!el) { resolve(); return; }

  // Se posição = trajetória: animar ao longo da trajetória
  const isTrajetoria = posicao === 'trajetoria';
  const halfSz = tamanho / 2;

  if (isTrajetoria) {
    el.style.left = (origem.x - halfSz) + 'px';
    el.style.top  = (origem.y - halfSz) + 'px';
  } else {
    el.style.left = (cx - halfSz) + 'px';
    el.style.top  = (cy - halfSz) + 'px';
  }

  // Transições CSS: fade in → hold → fade out
  el.style.opacity = '0';
  el.style.transition = `opacity 0.2s ease`;
  el.style.transform = 'scale(0.85)';

  wrap.appendChild(el);
  document.body.appendChild(wrap);

  // Fade in
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      el.style.opacity = '1';
      el.style.transform = 'scale(1)';
      el.style.transition = 'opacity 0.2s ease, transform 0.2s ease';
    });
  });

  // Trajetória: mover com RAF
  if (isTrajetoria) {
    const startTs = performance.now();
    const cx2 = (origem.x + alvo.x) / 2;
    const cy2 = Math.min(origem.y, alvo.y) - 60;
    function moveFrame(now) {
      const t = Math.min((now - startTs) / duracao, 1);
      const bx = (1-t)*(1-t)*origem.x + 2*(1-t)*t*cx2 + t*t*alvo.x;
      const by = (1-t)*(1-t)*origem.y + 2*(1-t)*t*cy2 + t*t*alvo.y;
      el.style.left = (bx - halfSz) + 'px';
      el.style.top  = (by - halfSz) + 'px';
      if (t < 1) requestAnimationFrame(moveFrame);
    }
    requestAnimationFrame(moveFrame);
  }

  // Fade out e remover
  setTimeout(() => {
    el.style.opacity = '0';
    el.style.transform = 'scale(1.1)';
    el.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
    setTimeout(() => { wrap.remove(); resolve(); }, 320);
  }, duracao - 320);
}

function _animImpacto(ctx, pos, rgb, cor, icone) {
  let f = 0;
  function frame() {
    f++; const alpha=Math.max(0,1-f/10), raio=10+f*4;
    ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);
    const g=ctx.createRadialGradient(pos.x,pos.y,0,pos.x,pos.y,raio);
    g.addColorStop(0,`rgba(255,255,255,${alpha})`);
    g.addColorStop(0.4,`rgba(${rgb},${alpha})`);
    g.addColorStop(1,`rgba(${rgb},0)`);
    ctx.beginPath(); ctx.arc(pos.x,pos.y,raio,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
    if (icone) {
      ctx.font=`${14+f*2}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.globalAlpha=alpha; ctx.fillText(icone,pos.x,pos.y); ctx.globalAlpha=1;
    }
    if (f < 10) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

// ── Validação de duração total da animação ──────────────────────────────────
function skAnimValidarDuracao() {
  const _isMestre = RPG_DATA?.myRole === 'mestre';
  const maxTotal  = _isMestre ? 10000 : 3000;
  const limLabel  = _isMestre ? '10s' : '3s';

  // Mídia
  const durM   = parseInt(document.getElementById('sk-anim-duracao')?.value) || 0;
  const repM   = parseInt(document.getElementById('sk-anim-repeticao')?.value) || 1;
  const totalM = durM * repM;
  const avisoM = document.getElementById('sk-anim-dur-aviso');
  if (avisoM) {
    const over = totalM > maxTotal;
    avisoM.style.display = totalM > 0 ? 'block' : 'none';
    avisoM.style.color   = over ? '#e8604c' : totalM > maxTotal * 0.85 ? '#f39c12' : 'rgba(255,255,255,0.35)';
    avisoM.textContent   = over ? `⚠ Total: ${totalM}ms — limite: ${maxTotal}ms (${limLabel})` : `Total: ${totalM}ms de ${maxTotal}ms`;
  }

  // Canvas
  const durC   = parseInt(document.getElementById('sk-anim-duracao-canvas')?.value) || 0;
  const repC   = parseInt(document.getElementById('sk-anim-repeticao-canvas')?.value) || 1;
  const totalC = durC * repC;
  const avisoC = document.getElementById('sk-anim-dur-aviso-canvas');
  if (avisoC) {
    const over = totalC > maxTotal;
    avisoC.style.display = totalC > 0 ? 'block' : 'none';
    avisoC.style.color   = over ? '#e8604c' : totalC > maxTotal * 0.85 ? '#f39c12' : 'rgba(255,255,255,0.35)';
    avisoC.textContent   = over ? `⚠ Total: ${totalC}ms — limite: ${maxTotal}ms (${limLabel})` : `Total: ${totalC}ms de ${maxTotal}ms`;
  }
}

// ── Preview no modal de skill ──────────────────────────────────────────────
let _skAnimPreviewRaf = null;

// ── UI: mudar campos ao selecionar tipo de animação ──────────────────────
function skAnimTipoChange() {
  const tipo = document.getElementById('sk-anim-tipo').value;
  const camposCanvas = document.getElementById('sk-anim-campos-canvas');
  const camposMidia  = document.getElementById('sk-anim-campos-midia');
  const isMidia  = ['gif','imagem','svg','iframe'].includes(tipo);
  const isCanvas = ['projetil','onda','explosao','raio','aura'].includes(tipo);

  if (camposCanvas) camposCanvas.style.display = isCanvas ? '' : 'none';
  if (camposMidia)  camposMidia.style.display  = isMidia  ? '' : 'none';

  if (isMidia) {
    // Ajustar label e mostrar campo correto
    const urlLabel  = document.getElementById('sk-anim-url-label');
    const urlInput  = document.getElementById('sk-anim-url');
    const svgInput  = document.getElementById('sk-anim-svg-code');
    const labels = { gif:'URL do GIF', imagem:'URL da Imagem', iframe:'URL do iFrame' };
    if (urlLabel) urlLabel.textContent = labels[tipo] || 'URL';
    if (urlInput)  urlInput.style.display  = tipo !== 'svg' ? '' : 'none';
    if (svgInput)  svgInput.style.display  = tipo === 'svg' ? '' : 'none';
    skAnimMidiaPreview();
  } else if (isCanvas) {
    skAnimPreview();
  } else {
    // nenhuma — esconder preview
    const pw = document.getElementById('sk-anim-preview-wrap');
    const mw = document.getElementById('sk-anim-midia-preview-wrap');
    if (pw) pw.style.display = 'none';
    if (mw) mw.style.display = 'none';
  }
}

function skAnimMidiaPreview() {
  const tipo   = document.getElementById('sk-anim-tipo').value;
  const url    = document.getElementById('sk-anim-url')?.value.trim();
  const svg    = document.getElementById('sk-anim-svg-code')?.value.trim();
  const tam    = parseInt(document.getElementById('sk-anim-tamanho')?.value) || 120;
  const wrap   = document.getElementById('sk-anim-midia-preview-wrap');
  const inner  = document.getElementById('sk-anim-midia-preview-inner');
  if (!wrap || !inner) return;

  const conteudo = tipo === 'svg' ? svg : url;
  if (!conteudo) { wrap.style.display = 'none'; return; }
  wrap.style.display = '';

  const sz = Math.min(tam, 150);
  if (tipo === 'svg') {
    inner.innerHTML = `<div style="width:${sz}px;height:${sz}px;display:flex;align-items:center;justify-content:center">${svg}</div>`;
  } else if (tipo === 'gif' || tipo === 'imagem') {
    inner.innerHTML = `<img src="${url}" style="max-width:${sz}px;max-height:${sz}px;border-radius:6px;object-fit:contain" onerror="this.parentElement.innerHTML='<span style=color:#e74c3c;font-size:0.75rem>Erro ao carregar imagem</span>'">`;
  } else if (tipo === 'iframe') {
    inner.innerHTML = `<div style="font-size:0.72rem;color:var(--suave);font-style:italic">iFrame não pré-visualizável — será exibido durante o ataque</div>`;
  }
}


// ── Criativo mestre: troca campos ao mudar tipo ───────────────────────────
function criativoAnimTipoChange() {
  const tipo = document.getElementById('criativo-anim-tipo')?.value || 'nenhuma';
  const isMidia  = ['gif','imagem','svg','iframe'].includes(tipo);
  const isCanvas = ['projetil','onda','explosao','raio','aura'].includes(tipo);
  const cc = document.getElementById('criativo-anim-campos-canvas');
  const cm = document.getElementById('criativo-anim-campos-midia');
  if (cc) cc.style.display = isCanvas ? '' : 'none';
  if (cm) cm.style.display = isMidia  ? '' : 'none';
  if (isMidia) {
    const labels = { gif:'URL do GIF', imagem:'URL da Imagem', iframe:'URL do iFrame' };
    const lbl = document.getElementById('criativo-anim-url-label');
    const url = document.getElementById('criativo-anim-url');
    const svg = document.getElementById('criativo-anim-svg-code');
    if (lbl) lbl.textContent = labels[tipo] || 'URL';
    if (url) url.style.display = tipo !== 'svg' ? '' : 'none';
    if (svg) svg.style.display = tipo === 'svg' ? '' : 'none';
  }
}

// ── Arena mestre-dano: troca campos ao mudar tipo ─────────────────────────
function arAnimDnTipoChange() {
  const tipo = document.getElementById('ar-atk-dn-anim-tipo')?.value || 'nenhuma';
  const isMidia  = ['gif','imagem','svg','iframe'].includes(tipo);
  const isCanvas = ['projetil','onda','explosao','raio','aura'].includes(tipo);
  const cc = document.getElementById('ar-atk-dn-anim-canvas');
  const cm = document.getElementById('ar-atk-dn-anim-midia');
  if (cc) cc.style.display = isCanvas ? '' : 'none';
  if (cm) cm.style.display = isMidia  ? '' : 'none';
  if (isMidia) {
    const labels = { gif:'URL do GIF', imagem:'URL da Imagem', iframe:'URL do iFrame' };
    const lbl = document.getElementById('ar-atk-dn-anim-url-label');
    const url = document.getElementById('ar-atk-dn-anim-url');
    const svg = document.getElementById('ar-atk-dn-anim-svg');
    if (lbl) lbl.textContent = labels[tipo] || 'URL';
    if (url) url.style.display = tipo !== 'svg' ? '' : 'none';
    if (svg) svg.style.display = tipo === 'svg' ? '' : 'none';
  }
}

function skAnimPreview() {
  const tipo = document.getElementById('sk-anim-tipo').value;
  const wrap = document.getElementById('sk-anim-preview-wrap');
  if (wrap) wrap.style.display = (tipo === 'nenhuma' || !['projetil','onda','explosao','raio','aura'].includes(tipo)) ? 'none' : 'block';
  if (!['projetil','onda','explosao','raio','aura'].includes(tipo)) return;
  skAnimPreviewPlay();
}

function skAnimPreviewPlay() {
  if (_skAnimPreviewRaf) cancelAnimationFrame(_skAnimPreviewRaf);
  const tipo   = document.getElementById('sk-anim-tipo').value;
  const cor    = document.getElementById('sk-anim-cor').value   || '#e74c3c';
  const icone  = document.getElementById('sk-anim-icone').value.trim();
  const trilha = document.getElementById('sk-anim-trilha').checked;
  const canvas = document.getElementById('sk-anim-preview-canvas');
  if (!canvas) return;
  const ctx    = canvas.getContext('2d');
  const rgb    = _animHexToRgb(cor);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const origem = { x: 20, y: 30 }, alvo = { x: 240, y: 30 };
  const dur = tipo==='aura'?800:tipo==='raio'?400:500;
  const start = performance.now();
  let lastRegen = 0, prevSegs = _animGerarZigzag(origem, alvo, 5);

  function drawFrame(now) {
    const t = Math.min((now - start) / dur, 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // tokens
    ctx.beginPath(); ctx.arc(origem.x,origem.y,10,0,Math.PI*2);
    ctx.fillStyle='rgba(79,163,209,0.5)'; ctx.fill();
    ctx.beginPath(); ctx.arc(alvo.x,alvo.y,10,0,Math.PI*2);
    ctx.fillStyle='rgba(232,80,60,0.5)'; ctx.fill();

    if (tipo==='projetil') {
      const cx2=(origem.x+alvo.x)/2, cy2=Math.min(origem.y,alvo.y)-20;
      const bx=(1-t)*(1-t)*origem.x+2*(1-t)*t*cx2+t*t*alvo.x;
      const by=(1-t)*(1-t)*origem.y+2*(1-t)*t*cy2+t*t*alvo.y;
      if (trilha) {
        for (let i=1;i<=6;i++) {
          const tt=Math.max(0,t-i*0.06);
          const tx=(1-tt)*(1-tt)*origem.x+2*(1-tt)*tt*cx2+tt*tt*alvo.x;
          const ty=(1-tt)*(1-tt)*origem.y+2*(1-tt)*tt*cy2+tt*tt*alvo.y;
          ctx.beginPath(); ctx.arc(tx,ty,3*(1-i/6),0,Math.PI*2);
          ctx.fillStyle=`rgba(${rgb},${(1-i/6)*0.35})`; ctx.fill();
        }
      }
      ctx.beginPath(); ctx.arc(bx,by,6,0,Math.PI*2); ctx.fillStyle=cor; ctx.fill();
      if (icone) { ctx.font='14px serif'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(icone,bx,by); }

    } else if (tipo==='onda') {
      for (const off of [0,0.2,0.4]) {
        const lt=Math.max(0,Math.min((t-off)/(1-off),1));
        if(lt<=0) continue;
        ctx.beginPath(); ctx.arc(origem.x,origem.y,lt*45,0,Math.PI*2);
        ctx.strokeStyle=`rgba(${rgb},${(1-lt)*0.7})`; ctx.lineWidth=2; ctx.stroke();
      }

    } else if (tipo==='explosao') {
      const N=14;
      for(let i=0;i<N;i++){
        const ang=Math.PI*2*i/N;
        ctx.beginPath(); ctx.arc(alvo.x+Math.cos(ang)*t*30,alvo.y+Math.sin(ang)*t*30,3*(1-t),0,Math.PI*2);
        ctx.fillStyle=`rgba(${rgb},${1-t})`; ctx.fill();
      }
      if(t<0.3){ctx.beginPath();ctx.arc(alvo.x,alvo.y,t/0.3*18,0,Math.PI*2);ctx.fillStyle=`rgba(${rgb},${1-t/0.3*0.8})`;ctx.fill();}

    } else if (tipo==='raio') {
      if (now - lastRegen > 80) { prevSegs=_animGerarZigzag(origem,alvo,5); lastRegen=now; }
      const a=t<0.7?1:(1-t)/0.3;
      ctx.beginPath(); prevSegs.forEach((s,i)=>i===0?ctx.moveTo(s.x,s.y):ctx.lineTo(s.x,s.y));
      ctx.strokeStyle=`rgba(${rgb},${a*0.7})`; ctx.lineWidth=4; ctx.stroke();
      ctx.beginPath(); prevSegs.forEach((s,i)=>i===0?ctx.moveTo(s.x,s.y):ctx.lineTo(s.x,s.y));
      ctx.strokeStyle=`rgba(255,255,255,${a*0.8})`; ctx.lineWidth=1.5; ctx.stroke();

    } else if (tipo==='aura') {
      const pulse=Math.sin(t*Math.PI*4)*0.5+0.5;
      const r2=14+pulse*8, a=(t<0.8?1:(1-t)/0.2)*(0.4+pulse*0.4);
      const g2=ctx.createRadialGradient(alvo.x,alvo.y,0,alvo.x,alvo.y,r2);
      g2.addColorStop(0,`rgba(${rgb},${a})`); g2.addColorStop(1,`rgba(${rgb},0)`);
      ctx.beginPath(); ctx.arc(alvo.x,alvo.y,r2,0,Math.PI*2); ctx.fillStyle=g2; ctx.fill();
      if (icone) {
        ctx.font=`${12+pulse*4}px serif`; ctx.textAlign='center'; ctx.textBaseline='middle';
        ctx.globalAlpha=Math.min(1,a*2); ctx.fillText(icone,alvo.x,alvo.y); ctx.globalAlpha=1;
      }
    }

    if (t < 1) {
      _skAnimPreviewRaf = requestAnimationFrame(drawFrame);
    } else {
      setTimeout(skAnimPreviewPlay, 500);
    }
  }
  _skAnimPreviewRaf = requestAnimationFrame(drawFrame);
}

// ── Confirmar ataque (builder manual / AoE) ──────────────────
function atkConfirmarAtaque() {
  // Sempre via card do mapa — animação e dano só aplicados ao clicar no card
  // (mestre, jogador, com ou sem animação, catalogada ou criativa)
  COMBATE._pendingTrigger = true;
  fecharModalAtaque();
}

// Wrapper que aplica efeito + recuperação imediata de atributo
async function atkAplicarEfeitoComRecuperacao(nomeAlvo, ef, contexto) {
  // Cura imediata via HOT com 0 turnos ou heal direto
  if (ef.heal_formula) {
    const grupos = parsearFormulaDano(ef.heal_formula);
    const r = grupos ? rolarGrupos(grupos) : { total: parseInt(ef.heal_formula)||0 };
    await atkAplicarCura(nomeAlvo, r.total, contexto);
  }
  // Recuperação imediata de atributo
  if (ef.rec_atributo && ef.rec_modo === 'imediato') {
    const grupos = parsearFormulaDano(ef.rec_formula || '0');
    const r = grupos ? rolarGrupos(grupos) : { total: parseInt(ef.rec_formula)||0 };
    await atkAplicarRecuperacaoAtributo(nomeAlvo, ef.rec_atributo, r.total, contexto);
  }
  // Aplica o buff (HOT, boost, etc.) como buff recorrente
  await atkAplicarEfeito(nomeAlvo, ef, contexto);
}

// ── Aplicar efeito bônus ao alvo ─────────────────────────────
async function atkAplicarEfeito(nomeAlvo, efeitoConfig, contexto) {
  if (!efeitoConfig) return;
  const turnoAtual = contexto === 'arena' ? (AR.estado?.turno || 0) : 0;
  // Determinar se é buff ou debuff
  const ehPositivo = !!(efeitoConfig.hot_formula || efeitoConfig.boost_dano || efeitoConfig.rec_atributo);
  const buff = {
    id:           'ef_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
    nome:         efeitoConfig.nome || 'Efeito',
    tipo:         ehPositivo ? 'buff' : 'debuff',
    turno_inicio: turnoAtual,
    // ── Negativos ──────────────────────────────────────────
    dot_formula:              efeitoConfig.dot_formula || null,
    dot_turnos_restantes:     efeitoConfig.dot_turnos  || 0,
    sem_movimento:            !!efeitoConfig.sem_movimento,
    sem_movimento_turnos_restantes: efeitoConfig.sem_movimento_turnos || 0,
    sem_ataque:               !!efeitoConfig.sem_ataque,
    sem_ataque_tipo:          efeitoConfig.sem_ataque_tipo || 'todos',
    sem_ataque_turnos_restantes: efeitoConfig.sem_ataque_turnos || 0,
    mod_dano:                 efeitoConfig.mod_dano ?? 0,
    mod_dano_turnos_restantes: efeitoConfig.mod_dano_turnos || 0,
    // ── Positivos ──────────────────────────────────────────
    hot_formula:              efeitoConfig.hot_formula || null,
    hot_turnos_restantes:     efeitoConfig.hot_turnos  || 0,
    boost_dano:               efeitoConfig.boost_dano || 0,
    boost_dano_turnos_restantes: efeitoConfig.boost_dano_turnos || 0,
    rec_atributo:             efeitoConfig.rec_atributo || null,
    rec_formula:              efeitoConfig.rec_formula || null,
    rec_modo:                 efeitoConfig.rec_modo || 'imediato',
    rec_turnos_restantes:     efeitoConfig.rec_modo === 'turno' ? (efeitoConfig.rec_turnos || 0) : 0,
    // ── Campo de compatibilidade: maior duração entre todos os efeitos ativos ──
    turnos_restantes: Math.max(
      efeitoConfig.dot_turnos || 0,
      efeitoConfig.sem_movimento_turnos || 0,
      efeitoConfig.sem_ataque_turnos || 0,
      efeitoConfig.mod_dano_turnos || 0,
      efeitoConfig.hot_turnos || 0,
      efeitoConfig.boost_dano_turnos || 0,
      (efeitoConfig.rec_modo === 'turno' ? efeitoConfig.rec_turnos : 0) || 0,
      efeitoConfig.turnos || 0,
    ) || 3,
    auto_aplicado: true,
  };

  if (contexto === 'arena') {
    const c = AR.chars.find(x => x.nome === nomeAlvo);
    if (!c) return;
    if (!Array.isArray(c.buffs)) c.buffs = [];
    c.buffs.push(buff);
    await arSb(`characters?rpg_id=eq.${encodeURIComponent(AR.session.rpg_id)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ buffs: c.buffs, custom_attrs: c.custom_attrs }) });
  } else {
    const c = RPG_DATA?.characters.find(x => x.nome === nomeAlvo);
    if (!c) return;
    if (!Array.isArray(c.buffs)) c.buffs = [];
    c.buffs.push(buff);
    await sb(`characters?rpg_id=eq.${encodeURIComponent(RPG_DATA.rpgId)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ buffs: c.buffs }) });
  }
}

// ── Calcula dano final após armadura e resistências ────────────
// Retorna o dano já reduzido (ceil em cada etapa)
function calcularDanoFinal(danoBruto, tipoDano, char, attrDefs) {
  if (!danoBruto || danoBruto <= 0) return 0;
  const atribs = char?.custom_attrs?.atributos || {};
  const resistDefs = (attrDefs || []).filter(a => a.categoria === 'resistencia');
  
  let danoAtual = danoBruto;

  // 1. Processar armaduras (reduzem todo dano + bônus para físico)
  for (const def of resistDefs) {
    let cfg = {};
    try { cfg = JSON.parse(def.opcoes || '{}'); } catch(e) { continue; }
    if (cfg.tipo !== 'armadura') continue;
    const valorArmadura = parseFloat(atribs[def.nome]) || 0;
    if (!valorArmadura) continue;

    // Redução geral (% do valor da armadura aplicada a todo dano)
    if (cfg.pct_geral) {
      const reducaoGeral = Math.ceil(valorArmadura * cfg.pct_geral / 100);
      danoAtual = Math.max(0, danoAtual - reducaoGeral);
    }
    // Redução adicional para dano físico
    if (cfg.pct_fisico && tipoDano === 'fisico') {
      const reducaoFisica = Math.ceil(valorArmadura * cfg.pct_fisico / 100);
      danoAtual = Math.max(0, danoAtual - reducaoFisica);
    }
    // Redução adicional para dano mágico
    if (cfg.pct_magico && tipoDano === 'magico') {
      const reducaoMagica = Math.ceil(valorArmadura * cfg.pct_magico / 100);
      danoAtual = Math.max(0, danoAtual - reducaoMagica);
    }
  }

  // 2. Processar resistências elementais/por tipo
  for (const def of resistDefs) {
    let cfg = {};
    try { cfg = JSON.parse(def.opcoes || '{}'); } catch(e) { continue; }
    if (cfg.tipo !== 'resistencia') continue;
    // Verificar se este tipo de resistência se aplica ao dano
    const dmgTypes = Array.isArray(cfg.damage_type) ? cfg.damage_type : [cfg.damage_type];
    if (!dmgTypes.includes(tipoDano)) continue;
    const valorRes = parseFloat(atribs[def.nome]) || 0;
    if (!valorRes) continue;

    if (cfg.modo === 'absoluto') {
      // Redução flat
      danoAtual = Math.max(0, danoAtual - valorRes);
    } else {
      // Percentual (default): valor do atributo usado diretamente como %
      const reducao = Math.ceil(danoAtual * valorRes / 100);
      danoAtual = Math.max(0, danoAtual - reducao);
    }
  }

  return Math.ceil(danoAtual);
}

// ── Obtém attrDefs do contexto correto ──────────────────────────
function getAttrDefsParaDano(contexto) {
  if (contexto === 'arena') return AR.attrDefs || RPG_DATA?.attrDefs || [];
  return RPG_DATA?.attrDefs || [];
}

async function atkAplicarDano(nomeAlvo, dano, contexto, tipoDano) {
  const attrDefs = getAttrDefsParaDano(contexto);
  if (contexto === 'arena') {
    const c = AR.chars.find(x => x.nome === nomeAlvo);
    if (!c) return;
    const danoFinal = calcularDanoFinal(dano, tipoDano || 'fisico', c, attrDefs);
    const hpMax = c.custom_attrs?.hp_max ?? 100;
    const novoHp = Math.max(0, (c.hp_atual ?? hpMax) - danoFinal);
    if (danoFinal !== dano) arLog(`🛡 ${nomeAlvo} — ${dano} de dano bruto → ${danoFinal} após resistências`);
    c.hp_atual = novoHp;
    await arSb(`characters?rpg_id=eq.${encodeURIComponent(AR.session.rpg_id)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
      { method: 'PATCH', body: JSON.stringify({ hp_atual: novoHp }) });
  } else {
    const c = RPG_DATA?.characters.find(x => x.nome === nomeAlvo);
    if (!c) return;
    const danoFinal = calcularDanoFinal(dano, tipoDano || 'fisico', c, attrDefs);
    if (danoFinal !== dano) mostrarToast(`🛡 ${nomeAlvo}: ${dano} → ${danoFinal} (resistências)`, '');
    const hpAtualReal = c.hp_atual ?? (c.custom_attrs?.hp_max ?? 100);
    const novoHp = Math.max(0, hpAtualReal - danoFinal);
    c.hp_atual = novoHp;
    await saveCharacterStats(RPG_DATA.rpgId, nomeAlvo, { hp_atual: novoHp });
    renderCharView(nomeAlvo); renderAttrView(nomeAlvo); mapaRenderStatus();
    if (novoHp <= 0) {
      // Marcar como morto e re-renderizar tokens (broadcast via DB realttime)
      c.custom_attrs = c.custom_attrs || {};
      c.custom_attrs.morto = true;
      try {
        await sb(`characters?rpg_id=eq.${encodeURIComponent(RPG_DATA.rpgId)}&nome=eq.${encodeURIComponent(nomeAlvo)}`,
          { method:'PATCH', body: JSON.stringify({ custom_attrs: c.custom_attrs }) });
      } catch(e) {}
      // Broadcast morte para todos os clientes
      combateBroadcast('personagem_morto', { nome: nomeAlvo });
      // I9: verificar drop automático se for NPC com tier
      const cMorto = RPG_DATA.characters.find(x=>x.nome===nomeAlvo);
      if(cMorto&&(cMorto.custom_attrs?.tipo==='inimigo'||cMorto.custom_attrs?.tipo==='npc')&&cMorto.custom_attrs?.tier){
        _executarDropNPC(RPG_DATA.rpgId, nomeAlvo, cMorto).catch(()=>{});
      }
      const entry = (RPG_DATA.mapas||[]).find(l => l.mapa.map_id === MAPA_STATE.mapaAtualId);
      if (entry) mapaRenderTokens(entry.mapa);
      mostrarToast(`💀 ${nomeAlvo} foi derrotado!`, 'erro');
    }
  }
}

// ── 18F: Ataques criativos ───────────────────────────────────
async function atkEnviarAtaqueCriativo() {
  const { atacanteNome, alvoNome, habilidadeSel: h, contexto } = COMBATE;
  const id = 'ap_' + Date.now();
  const pendente = {
    id,
    atacante:  atacanteNome,
    alvo:      alvoNome,
    descricao: h.descricao,
    turno:     contexto === 'arena' ? (AR.estado?.turno || 0) : 0,
    status:    'pendente',
  };

  if (contexto === 'arena') {
    // Arena também usa a tabela criativos (mesma que campanha) para realtime funcionar
    CRIATIVOS_CAMP.push(pendente);
    CRIATIVO_ID_ATUAL = id;
    // Inserir usando arSb para garantir o rpg_id correto da arena
    try {
      await arSb('criativos', {method:'POST', body:JSON.stringify({
        rpg_id:   AR.session.rpg_id,
        id:       pendente.id,
        atacante: pendente.atacante,
        alvo:     pendente.alvo,
        descricao:pendente.descricao,
        turno:    pendente.turno || 0,
        status:   'pendente',
      })});
    } catch(e) {}
    // Se o mestre está jogando como personagem, abre aprovação direto
    if (AR.myRole === 'mestre') {
      fecharModalAtaque();
      mostrarToast('Defina a fórmula da ação criativa', '');
      abrirModalCriativoMestre(id);
      return;
    }
    const divAguardando = document.getElementById('atk-pendente-aguardando');
    const divAprovado   = document.getElementById('atk-pendente-aprovado');
    const divRejeitado  = document.getElementById('atk-pendente-rejeitado');
    if (divAguardando) divAguardando.style.display = '';
    if (divAprovado)   divAprovado.style.display   = 'none';
    if (divRejeitado)  divRejeitado.style.display  = 'none';
    criativoIniciarPolling(id);
  } else {
    // Campanha: salvar na tabela criativos
    CRIATIVOS_CAMP.push(pendente);
    CRIATIVO_ID_ATUAL = id;
    await criativoInserir(pendente);

    // Mestre controlando o personagem: abrir modal de aprovação diretamente
    if (RPG_DATA?.myRole === 'mestre') {
      fecharModalAtaque();
      mostrarToast('Defina a fórmula da ação criativa', '');
      abrirModalCriativoMestre(id);
      return;
    }

    // Resetar sub-estados do step-pendente
    const divAguardando = document.getElementById('atk-pendente-aguardando');
    const divAprovado   = document.getElementById('atk-pendente-aprovado');
    const divRejeitado  = document.getElementById('atk-pendente-rejeitado');
    if (divAguardando) divAguardando.style.display = '';
    if (divAprovado)   divAprovado.style.display   = 'none';
    if (divRejeitado)  divRejeitado.style.display  = 'none';
    criativoIniciarPolling(id); // fallback: polling caso o realtime nao chegue
  }

  atkIrParaStep('pendente');
  mostrarToast('Ação criativa enviada ao Mestre', '');
}

// ── Solicitar aprovação do mestre para skill ofensiva fora de combate ─
async function atkEnviarSolicitacaoSkill() {
  const { atacanteNome, alvoNome, habilidadeSel: h, contexto } = COMBATE;
  const id = 'sk_' + Date.now();
  // Codificar info da skill no campo descricao com marcador especial
  const skillJson = JSON.stringify({
    nome: h.nome,
    formula: h.formula_dano || null,
    atributo: h.atributo_base || null,
    mod_pct: h.mod_atributo_pct || null,
  });
  const descricao = `[SKILL:${skillJson}] ${h.efeito || h.nome}`;
  const pendente = {
    id,
    tipo: 'skill_request',
    skill_nome: h.nome,
    skill_formula: h.formula_dano || null,
    skill_atributo: h.atributo_base || null,
    skill_mod_pct: h.mod_atributo_pct || null,
    atacante: atacanteNome,
    alvo: alvoNome,
    descricao,
    turno: 0,
    status: 'pendente',
  };

  CRIATIVOS_CAMP.push(pendente);
  CRIATIVO_ID_ATUAL = id;
  await criativoInserir(pendente);

  // Mestre controlando o personagem: abrir modal de aprovação diretamente
  if (RPG_DATA?.myRole === 'mestre') {
    fecharModalAtaque();
    mostrarToast(`Defina a fórmula para "${h.nome}"`, '');
    abrirModalCriativoMestre(id);
    return;
  }

  const divAguardando = document.getElementById('atk-pendente-aguardando');
  const divAprovado   = document.getElementById('atk-pendente-aprovado');
  const divRejeitado  = document.getElementById('atk-pendente-rejeitado');
  if (divAguardando) {
    divAguardando.style.display = '';
    divAguardando.querySelector
      && (divAguardando.querySelector('div:nth-child(2)') || divAguardando.lastElementChild || {}).textContent
      && (divAguardando.lastElementChild.textContent = `Mestre irá revisar o uso de "${h.nome}" em ${alvoNome}.`);
  }
  if (divAprovado)   divAprovado.style.display   = 'none';
  if (divRejeitado)  divRejeitado.style.display  = 'none';

  criativoIniciarPolling(id); // fallback: polling caso o realtime nao chegue
  atkIrParaStep('pendente');
  mostrarToast(`"${h.nome}" enviada ao Mestre para aprovação`, '');
}

function renderAtaquesPendentes() {
  const pendentes = (AR.estado.ataques_pendentes || []).filter(a => a.status === 'pendente');
  const el = document.getElementById('ar-ataques-pendentes');
  if (!el) return;
  el.style.display = pendentes.length && RPG_DATA?.myRole === 'mestre' ? 'block' : 'none';
  if (!pendentes.length) { el.innerHTML = ''; return; }
  el.innerHTML = `
    <div style="font-family:'Cinzel',serif;font-size:0.65rem;color:rgba(200,168,75,0.7);text-transform:uppercase;margin-bottom:8px">⚔ Ações Criativas Pendentes</div>
    ${pendentes.map(a => `
      <div style="background:rgba(200,168,75,0.05);border:1px solid rgba(200,168,75,0.2);border-radius:8px;padding:12px;margin-bottom:8px">
        <div style="font-family:'Cinzel',serif;font-size:0.8rem;color:var(--destaque);margin-bottom:4px">${a.atacante} → ${a.alvo}</div>
        <div style="font-size:0.85rem;color:#b8a8a8;margin-bottom:10px;line-height:1.5">${a.descricao}</div>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <div style="display:flex;align-items:center;gap:6px;flex:1">
            <input type="number" id="dano-ap-${a.id}" value="1" min="1"
              style="width:52px;padding:5px;background:rgba(8,4,4,0.9);border:1px solid rgba(60,30,30,0.6);border-radius:4px;color:#c8d8e8;font-family:'Cinzel',serif;font-size:0.75rem;text-align:center">
            <select id="dado-ap-${a.id}" style="padding:5px;background:rgba(8,4,4,0.9);border:1px solid rgba(60,30,30,0.6);border-radius:4px;color:#c8d8e8;font-family:'Cinzel',serif;font-size:0.75rem">
              ${[4,6,8,10,12,20].map(d=>`<option value="${d}">d${d}</option>`).join('')}
            </select>
            <button onclick="atkRolarParaPendente('${a.id}')"
              style="padding:5px 10px;background:rgba(232,80,60,0.1);border:1px solid rgba(232,80,60,0.3);border-radius:4px;color:#e8604c;font-family:'Cinzel',serif;font-size:0.7rem;cursor:pointer">🎲</button>
            <span id="resultado-ap-${a.id}" style="font-family:'Cinzel',serif;font-size:1.1rem;color:#f0cc6a;min-width:24px;text-align:center">—</span>
          </div>
          <div style="display:flex;gap:6px">
            <button onclick="atkMestreAprovar('${a.id}')"
              style="padding:5px 10px;background:rgba(39,174,96,0.1);border:1px solid rgba(39,174,96,0.3);border-radius:4px;color:#5ee09a;font-family:'Cinzel',serif;font-size:0.7rem;cursor:pointer">✓ Aprovar</button>
            <button onclick="atkMestreRejeitar('${a.id}')"
              style="padding:5px 10px;background:rgba(192,57,43,0.1);border:1px solid rgba(192,57,43,0.3);border-radius:4px;color:#e74c3c;font-family:'Cinzel',serif;font-size:0.7rem;cursor:pointer">✕ Rejeitar</button>
          </div>
        </div>
      </div>
    `).join('')}
  `;
}

function atkRolarParaPendente(apId) {
  const qtd   = parseInt(document.getElementById('dano-ap-'  + apId)?.value  || '1');
  const faces = parseInt(document.getElementById('dado-ap-'  + apId)?.value  || '6');
  const result = rolarFormula({ qtd, faces, bonus: 0, tipo: 'dado' });
  const el = document.getElementById('resultado-ap-' + apId);
  if (el) {
    el.textContent = result.total;
    el.dataset.total = result.total;
    el.title = `Dados: [${result.rolls.join(', ')}]`;
  }
}

async function atkMestreAprovar(apId) {
  const pendente = AR.estado.ataques_pendentes?.find(a => a.id === apId);
  if (!pendente) return;
  const resultEl = document.getElementById('resultado-ap-' + apId);
  const dano = parseInt(resultEl?.dataset.total || '0');
  pendente.status = 'aprovado'; pendente.dano_aplicado = dano;
  await atkAplicarDano(pendente.alvo, dano, 'arena', pendente.tipo_dano || 'fisico');
  arAddLog(`⚔ [Criativo] ${pendente.atacante} → ${pendente.alvo} — ${dano} de dano (aprovado pelo Mestre)`);
  await arSalvarEstado();
  renderArenaPersonagens(); renderArenaEntidades(); renderMesa();
  renderAtaquesPendentes();
  mostrarToast(`Ataque criativo de ${pendente.atacante} aprovado!`, 'sucesso');
}

async function atkMestreRejeitar(apId) {
  const pendente = AR.estado.ataques_pendentes?.find(a => a.id === apId);
  if (!pendente) return;
  pendente.status = 'rejeitado';
  arAddLog(`✕ Ação criativa de ${pendente.atacante} rejeitada pelo Mestre`);
  await arSalvarEstado();
  renderAtaquesPendentes();
  mostrarToast('Ação rejeitada', '');
}

// ══════════════════════════════════════════════════════════════
// ⚔ SISTEMA DE ATAQUES CRIATIVOS — CAMPANHA
// Fluxo: Jogador envia → Mestre preenche fórmula → Jogador rola → Dano aplicado
// Estado sincronizado via tabela criativos (realtime)
// ══════════════════════════════════════════════════════════════

// ── Helper: parsear dados de DC guardados em formula_aprovada ──────────────
function _parseDCData(formulaAprovada) {
  if (!formulaAprovada || !String(formulaAprovada).startsWith('__DC__')) return null;
  try { return JSON.parse(String(formulaAprovada).slice(6)); } catch(e) { return null; }
}

async function criativoSalvar(apenasId) {
  const rpgId = AR.session?.rpg_id || RPG_DATA?.rpgId;
  if (!rpgId) return;
  const sbFn = AR.session ? arSb : sb;
  const lista = apenasId
    ? CRIATIVOS_CAMP.filter(c => c.id === apenasId)
    : CRIATIVOS_CAMP;
  try {
    await Promise.all(lista.map(c =>
      sbFn(`criativos?rpg_id=eq.${encodeURIComponent(rpgId)}&id=eq.${encodeURIComponent(c.id)}`, {
        method:'PATCH',
        body:JSON.stringify({
          status:           c.status,
          formula_aprovada: c.formula_aprovada||null,
          mod_atributo:     c.mod_atributo||null,
          mod_atributo_pct: c.mod_atributo_pct||null,
          custo_cobrado:    c.custo_cobrado||null,
          animacao:         c.animacao||null,
        })
      })
    ));
  } catch(e) {}
}

async function criativoInserir(pendente) {
  if (!RPG_DATA?.rpgId) return;
  try {
    await sb('criativos', {
      method:'POST',
      body:JSON.stringify({
        rpg_id:   RPG_DATA.rpgId,
        id:       pendente.id,
        atacante: pendente.atacante,
        alvo:     pendente.alvo,
        descricao:pendente.descricao,
        turno:    pendente.turno||0,
        status:   pendente.status||'pendente',
      })
    });
  } catch(e) {}
}

function criativoReceberLinhaRemota(rec) {
  if (!rec || !rec.id) return;
  const c = {
    id:rec.id, atacante:rec.atacante, alvo:rec.alvo, descricao:rec.descricao,
    turno:rec.turno, status:rec.status,
    formula_aprovada:rec.formula_aprovada||null,
    mod_atributo:rec.mod_atributo||null,
    mod_atributo_pct:rec.mod_atributo_pct||null,
    custo_cobrado:rec.custo_cobrado||null,
    animacao:rec.animacao||null,
  };
  // Normalizar animacao (pode vir como string JSON do banco)
  if (typeof c.animacao === 'string') { try { c.animacao = JSON.parse(c.animacao); } catch(e) { c.animacao = null; } }
  if (c.animacao && typeof c.animacao !== 'object') c.animacao = null;
  // Extrair dados de DC se formula_aprovada tiver prefixo __DC__
  const dcData = _parseDCData(c.formula_aprovada);
  if (dcData) {
    c._dc = dcData;  // {dado, dc, eh_ataque, mensagem_fase1, resultado, critico, natural_max, mensagem_fase2}
  } else {
    c._dc = null;
  }
  // Detectar combate_pedido a partir do prefixo [COMBATE_PEDIDO]
  const combateMatch = (rec.descricao || '').match(/^\[COMBATE_PEDIDO\]/);
  if (combateMatch) {
    c.tipo = 'combate_pedido';
    const mapaMatch = (rec.descricao || '').match(/mapa:([^\s|]+)/);
    c.mapa_id_pedido = mapaMatch ? mapaMatch[1] : null;
  }
  // Detectar skill request a partir do prefixo [SKILL:{...}]
  const skillMatch = (rec.descricao || '').match(/^\[SKILL:(\{.*?\})\]/);
  if (skillMatch) {
    try {
      const sk = JSON.parse(skillMatch[1]);
      c.tipo = 'skill_request';
      c.skill_nome    = sk.nome    || null;
      c.skill_formula = sk.formula || null;
      c.skill_atributo= sk.atributo|| null;
      c.skill_mod_pct = sk.mod_pct || null;
    } catch(e) {}
  }
  const idx = CRIATIVOS_CAMP.findIndex(x => x.id === c.id);
  if (idx >= 0) CRIATIVOS_CAMP[idx] = c;
  else CRIATIVOS_CAMP.push(c);
  criativoRenderMestre();
  if (CRIATIVO_ID_ATUAL === c.id) criativoAtualizarStepJogador(c);
  // Toast para mestre quando recebe pedido de combate
  if (c.tipo === 'combate_pedido' && (RPG_DATA?.myRole === 'mestre' || AR?.myRole === 'mestre')) {
    mostrarToast(`⚔ ${c.atacante} solicita entrada em combate!`, '');
  }
  // Toast para mestre quando jogador rolou o DC e aguarda definição de dano
  if (c.status === 'dc_rolado_sucesso' && (RPG_DATA?.myRole === 'mestre' || AR?.myRole === 'mestre')) {
    const dc = c._dc;
    const resultLabel = dc ? `${dc.resultado}/${dc.dc}` : '';
    mostrarToast(`⚔ ${c.atacante} superou o desafio (${resultLabel})! Monte o dano.`, 'sucesso');
    // Auto-abrir modal de definir dano se não estiver aberto
    const overlayAberto = document.getElementById('modal-criativo-mestre-overlay')?.style.display !== 'none';
    if (!overlayAberto) abrirModalCriativoMestre(c.id);
  }
  if (c.status === 'dc_rolado_falha' && (RPG_DATA?.myRole === 'mestre' || AR?.myRole === 'mestre')) {
    const dc = c._dc;
    mostrarToast(`✗ ${c.atacante} falhou no desafio (${dc?.resultado||'?'}/${dc?.dc||'?'})`, '');
  }

  // Detectar se estamos em arena ou campanha
  const emArena = !!AR.session;
  const roleAtivo = emArena ? AR.myRole : RPG_DATA?.myRole;

  // Notificar mestre instantaneamente quando chega nova solicitação
  if (roleAtivo === 'mestre' && c.status === 'pendente') {
    // Em arena: aba Mesa; em campanha: aba Mapas
    const abaAtiva = emArena
      ? document.getElementById('ar-tab-mesa')?.classList.contains('ativo')
      : document.getElementById('tab-mapas')?.classList.contains('active');
    const isSkill = c.tipo === 'skill_request';
    const descCurta = isSkill
      ? (c.skill_nome || 'Skill')
      : (c.descricao||'').replace(/^\[SKILL:\{.*?\}\]\s*/,'').substring(0,60);
    _criativoNotifId = c.id;
    if (!abaAtiva) {
      criativoNotifMostrar(
        'nova-solicitacao',
        '🎲 Nova Solicitação de Ação',
        `${c.atacante} → ${c.alvo || '?'}: ${descCurta}`,
        '📋 Abrir e Aprovar'
      );
    } else {
      mostrarToast(`Nova ação de ${c.atacante} aguardando aprovação`, '');
    }
  }
}

function criativoRenderMestre() {
  // Suporte a campanha e arena
  const emArena = !!AR.session;
  const roleAtivo = emArena ? AR.myRole : RPG_DATA?.myRole;
  const wrap = document.getElementById(emArena ? 'ar-criativos-mestre-wrap' : 'criativos-mestre-wrap');
  if (!wrap) return;
  if (roleAtivo !== 'mestre') { wrap.style.display = 'none'; return; }
  const pendentes = CRIATIVOS_CAMP.filter(c => c.status === 'pendente' || c.status === 'dc_rolado_sucesso');
  if (!pendentes.length) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  const corAccent = emArena ? 'rgba(232,80,60,0.7)' : 'rgba(200,168,75,0.7)';
  const corBtn = emArena ? 'rgba(232,80,60,0.2)' : 'rgba(200,168,75,0.2)';
  const corBtnBorder = emArena ? 'rgba(232,80,60,0.35)' : 'rgba(200,168,75,0.35)';
  const corBtnText = emArena ? '#e8604c' : 'var(--destaque)';
  wrap.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
      <div style="font-family:'Cinzel',serif;font-size:0.6rem;color:${corAccent};text-transform:uppercase;letter-spacing:0.08em">✦ Ações Aguardando Aprovação</div>
      <button onclick="criativoMestreLimparTodas()" style="background:none;border:1px solid rgba(192,57,43,0.2);border-radius:4px;color:#e74c3c66;font-family:'Cinzel',serif;font-size:0.55rem;padding:2px 7px;cursor:pointer;text-transform:uppercase" title="Rejeitar todas as solicitações pendentes">✕ Limpar todas</button>
    </div>
    ${pendentes.map(c => {
      const isSkill    = c.tipo === 'skill_request';
      const isCombate  = c.tipo === 'combate_pedido';
      const isDanoReq  = c.status === 'dc_rolado_sucesso';
      const badge = isCombate
        ? `<span style="font-size:0.55rem;background:rgba(192,57,43,0.15);border:1px solid rgba(192,57,43,0.35);border-radius:3px;padding:1px 5px;color:#e74c3c;margin-left:4px">⚔ Combate</span>`
        : isDanoReq
          ? `<span style="font-size:0.55rem;background:rgba(192,57,43,0.15);border:1px solid rgba(192,57,43,0.35);border-radius:3px;padding:1px 5px;color:#e74c3c;margin-left:4px">⚔ Montar Dano</span>`
          : isSkill
            ? `<span style="font-size:0.55rem;background:rgba(79,163,209,0.12);border:1px solid rgba(79,163,209,0.3);border-radius:3px;padding:1px 5px;color:#7ec8f0;margin-left:4px">Skill</span>`
            : `<span style="font-size:0.55rem;background:${corBtn};border:1px solid ${corBtnBorder};border-radius:3px;padding:1px 5px;color:${corBtnText};margin-left:4px">Criativo</span>`;
      const dc = c._dc;
      const descExibida = isCombate
        ? `⚔ Solicita entrada em combate — ${(c.descricao||'').replace(/^\[COMBATE_PEDIDO\]\s*mapa:[^\s|]+\s*\|?\s*/,'').trim() || 'sem descrição adicional'}`
        : isDanoReq
          ? `✅ Tirou <strong style="color:#f0cc6a">${dc?.resultado||'?'}</strong> / DC ${dc?.dc||'?'}${dc?.critico?' 🌟 Crítico!':''} — Monte os dados de dano`
          : isSkill
            ? `🗡 ${c.skill_nome || '?'} em <strong style="color:#e8604c">${c.alvo}</strong>`
            : (c.descricao || '').replace(/^\[SKILL:\{.*?\}\]\s*/,'').replace(/^\[USO DE ITEM\]\s*/,'🎒 ').replace(/^\[COMBATE_PEDIDO\]\s*/,'');
      return `
      <div style="background:${emArena?'rgba(232,80,60,0.05)':'rgba(200,168,75,0.05)'};border:1px solid ${emArena?'rgba(232,80,60,0.2)':'rgba(200,168,75,0.2)'};border-radius:8px;padding:10px;margin-bottom:6px">
        <div style="font-family:'Cinzel',serif;font-size:0.75rem;color:${corBtnText};margin-bottom:3px">${c.atacante}${badge}</div>
        <div style="font-size:0.8rem;color:#b8a8a8;margin-bottom:8px;line-height:1.4">${descExibida}</div>
        <div style="display:flex;gap:6px">
          <button onclick="${c.tipo === 'combate_pedido' ? `mestreAbrirModalCombatePedido('${c.id}')` : `abrirModalCriativoMestre('${c.id}')`}"
            style="flex:1;padding:8px;background:linear-gradient(135deg,${c.tipo === 'combate_pedido' || isDanoReq ? 'rgba(192,57,43,0.2),rgba(192,57,43,0.08)' : `${corBtn},${corBtn.replace('0.2','0.08')}`});border:1px solid ${c.tipo === 'combate_pedido' || isDanoReq ? 'rgba(192,57,43,0.4)' : corBtnBorder};border-radius:6px;color:${c.tipo === 'combate_pedido' || isDanoReq ? '#e74c3c' : corBtnText};font-family:'Cinzel',serif;font-size:0.65rem;cursor:pointer;text-transform:uppercase;letter-spacing:0.06em">
            ${c.tipo === 'combate_pedido' ? '⚔ Gerenciar Combate' : isDanoReq ? '🎲 Montar Dano' : isSkill ? '🎲 Revisar Skill' : '🎲 Definir Desafio'}
          </button>
          <button onclick="criativoMestreRejeitarDireto('${c.id}')"
            style="padding:8px 10px;background:rgba(192,57,43,0.08);border:1px solid rgba(192,57,43,0.25);border-radius:6px;color:#e74c3c88;font-family:'Cinzel',serif;font-size:0.72rem;cursor:pointer" title="Rejeitar">✕</button>
        </div>
      </div>
    `}).join('')}
  `;
}

function abrirModalCriativoMestre(id) {
  const c = CRIATIVOS_CAMP.find(x => x.id === id);
  if (!c) return;
  document.getElementById('criativo-mestre-id').value = id;

  const isSkill    = c.tipo === 'skill_request';
  const isFase2    = c.status === 'dc_rolado_sucesso';

  // --- Info header ---
  let descDisplay;
  if (isFase2 && c._dc) {
    const dc = c._dc;
    const criticoStr = dc.critico ? ` 🌟 <span style="color:#f0cc6a">CRÍTICO!</span>` : '';
    descDisplay = `<strong style="color:var(--destaque)">${c.atacante}</strong> rolou um <strong style="color:#f0cc6a;font-size:1.1em">${dc.resultado}</strong> (d${dc.dado}) contra DC ${dc.dc}${criticoStr}<br>
      <span style="font-size:0.8rem;color:#7a6060">Sucesso! Monte os dados de dano para o ataque.</span>`;
  } else if (isSkill) {
    descDisplay = `<strong style="color:var(--destaque)">${c.atacante}</strong> → <strong style="color:#e8604c">${c.alvo}</strong><br>
      <span style="font-family:'Cinzel',serif;font-size:0.82rem;color:#7ec8f0">🗡 ${c.skill_nome}</span>
      ${c.skill_formula ? `<span style="color:#f0cc6a;margin-left:6px">· ${c.skill_formula}</span>` : ''}
      <br><span style="font-size:0.8rem;color:#7a6060;margin-top:2px;display:block">Defina dado e DC para esta skill fora de combate</span>`;
  } else {
    const descLimpa = (c.descricao||'').replace(/^\[SKILL:\{.*?\}\]\s*/,'').replace(/^\[USO DE ITEM\]\s*/,'').replace(/^\[COMBATE_PEDIDO\]\s*/,'');
    descDisplay = `<strong style="color:var(--destaque)">${c.atacante}</strong><br><span style="color:#b8a8a8">${descLimpa}</span>`;
  }
  document.getElementById('criativo-mestre-info').innerHTML = descDisplay;

  // Título
  const tituloEl = document.getElementById('criativo-mestre-titulo');
  if (tituloEl) tituloEl.textContent = isFase2 ? '⚔ Montar Dados de Dano' : '🎲 Definir Desafio';

  // Mostrar fase correta
  document.getElementById('criativo-fase1').style.display = isFase2 ? 'none' : '';
  document.getElementById('criativo-fase2').style.display = isFase2 ? '' : 'none';

  if (isFase2) {
    // --- FASE 2: Builder de dano ---
    CRIATIVO_MESTRE_BUILDER = [];
    if (isSkill && c.skill_formula) {
      const grupos = parsearFormulaDano(c.skill_formula);
      if (grupos) grupos.forEach(g => {
        if (g.tipo === 'dado') {
          const ex = CRIATIVO_MESTRE_BUILDER.find(x => x.tipo === 'dado' && x.faces === g.faces);
          if (ex) ex.qtd += (g.qtd||1); else CRIATIVO_MESTRE_BUILDER.push({tipo:'dado',qtd:g.qtd||1,faces:g.faces});
        }
      });
    }
    criativoMestreBuilderAtualizar();
    // Preencher atributos
    const selAttr = document.getElementById('criativo-mestre-atributo');
    if (selAttr) {
      const attrDefsSource = RPG_DATA?.attrDefs || AR?.estado?.attrDefs || [];
      selAttr.innerHTML = '<option value="">— Nenhum —</option>' +
        attrDefsSource.filter(a => a.tipo==='number'||!a.tipo||a.tipo==='text').map(a=>`<option value="${a.nome}">${a.nome}</option>`).join('');
      selAttr.value = (isSkill && c.skill_atributo) ? c.skill_atributo : '';
    }
    const modPctEl = document.getElementById('criativo-mestre-mod-pct');
    if (modPctEl) modPctEl.value = (isSkill && c.skill_mod_pct) ? c.skill_mod_pct : '';
    document.getElementById('criativo-mestre-attr-preview').textContent = '';
    criativoMestreAtributoMudou();
    // Mostrar resultado
    const resultEl = document.getElementById('criativo-fase2-resultado');
    if (resultEl && c._dc) {
      const dc = c._dc;
      const criticoStr = dc.critico ? ` — 🌟 Crítico!` : '';
      const corResult = dc.critico ? '#f0cc6a' : '#5ee09a';
      resultEl.style.cssText = `padding:12px;border-radius:8px;margin-bottom:14px;text-align:center;background:rgba(39,174,96,0.06);border:1px solid rgba(39,174,96,0.2)`;
      resultEl.innerHTML = `<div style="font-size:0.65rem;color:var(--suave);font-family:'Cinzel',serif;text-transform:uppercase;margin-bottom:4px">Resultado do Desafio</div>
        <div style="font-family:'Cinzel',serif;font-size:1.8rem;color:${corResult};line-height:1">${dc.resultado}</div>
        <div style="font-size:0.75rem;color:var(--suave);margin-top:2px">d${dc.dado} • DC ${dc.dc}${criticoStr}</div>`;
    }
    // Reset animação
    const animTipoEl = document.getElementById('criativo-anim-tipo');
    if (animTipoEl) { animTipoEl.value = 'nenhuma'; criativoAnimTipoChange(); }
    const _rId = (eid) => document.getElementById(eid);
    if (_rId('criativo-anim-cor'))      _rId('criativo-anim-cor').value    = '#e74c3c';
    if (_rId('criativo-anim-icone'))    _rId('criativo-anim-icone').value  = '';
    if (_rId('criativo-anim-trilha'))   _rId('criativo-anim-trilha').checked = false;
    if (_rId('criativo-anim-url'))      _rId('criativo-anim-url').value    = '';
    if (_rId('criativo-anim-svg-code')) _rId('criativo-anim-svg-code').value = '';
    if (_rId('criativo-anim-tamanho'))  _rId('criativo-anim-tamanho').value = 120;
    if (_rId('criativo-anim-duracao'))  _rId('criativo-anim-duracao').value = 1500;
    if (_rId('criativo-anim-posicao'))  _rId('criativo-anim-posicao').value = 'alvo';
    if (_rId('criativo-msg-fase2'))     _rId('criativo-msg-fase2').value   = '';
  } else {
    // --- FASE 1: DC declaration ---
    // Reset dado selecionado (default d20)
    document.querySelectorAll('.dc-dado-btn').forEach(b => b.classList.remove('dc-dado-sel'));
    const d20Btn = document.querySelector('.dc-dado-btn[data-faces="20"]');
    if (d20Btn) d20Btn.classList.add('dc-dado-sel');
    // Reset DC
    const dcEl = document.getElementById('criativo-dc-valor');
    if (dcEl) dcEl.value = '';
    const dcPrev = document.getElementById('criativo-dc-preview');
    if (dcPrev) dcPrev.textContent = '';
    // Reset ataque toggle
    const atqCheck = document.getElementById('criativo-eh-ataque');
    if (atqCheck) { atqCheck.checked = false; criativoEhAtaqueChange(); }
    // Reset mensagem
    const msgEl = document.getElementById('criativo-msg-fase1');
    if (msgEl) msgEl.value = '';
    // Reset custo
    const cobrarCheck = document.getElementById('criativo-cobrar-custo');
    const custoFields = document.getElementById('criativo-custo-fields');
    const custoPrev   = document.getElementById('criativo-custo-preview');
    if (cobrarCheck) cobrarCheck.checked = false;
    if (custoFields) custoFields.style.display = 'none';
    if (custoPrev)   custoPrev.textContent = '';
    const custoSel = document.getElementById('criativo-custo-atributo');
    if (custoSel) {
      const especiais = (RPG_DATA?.attrDefs || []).filter(a => a.categoria==='status' && a.tipo==='number');
      custoSel.innerHTML = '<option value="">— Selecionar —</option>' +
        especiais.map(a=>`<option value="${a.nome}">${a.nome}</option>`).join('');
    }
    const custoQtd = document.getElementById('criativo-custo-qtd');
    if (custoQtd) custoQtd.value = '';
    // Reset skill
    const cadastrarCheck = document.getElementById('criativo-cadastrar-skill');
    const cadastrarFields = document.getElementById('criativo-cadastrar-skill-fields');
    if (cadastrarCheck) cadastrarCheck.checked = false;
    if (cadastrarFields) cadastrarFields.style.display = 'none';
    const skNomeEl = document.getElementById('criativo-skill-nome');
    const skEfeitoEl = document.getElementById('criativo-skill-efeito');
    if (skNomeEl) skNomeEl.value = c.skill_nome || '';
    if (skEfeitoEl) skEfeitoEl.value = (c.descricao||'').replace(/^\[SKILL:\{.*?\}\]\s*/,'').replace(/^\[COMBATE_PEDIDO\]\s*/,'').replace(/^\[USO DE ITEM\]\s*/,'') || '';
    // Pré-preencher DC para skill_request
    if (isSkill && c.skill_formula) {
      // Sugerir d20 como dado padrão para skills
    }
  }

  document.getElementById('modal-criativo-mestre-overlay').style.display = 'flex';
}

