function lerCSV(tipo,input){const f=input.files[0];if(!f)return;const st=document.getElementById('status-'+tipo),rd=new FileReader();rd.onload=e=>{try{const p=parseCSV(e.target.result);p.forEach(r=>Object.keys(r).forEach(k=>{if(typeof r[k]==='string')r[k]=r[k].replace(/\\n/g,'\n');}));IMPORT_CSVS[tipo]=p;st.textContent=`✓ ${p.length} linha(s)`;st.className='import-status ok';st.style.display='block';}catch(err){st.textContent=`✗ ${err.message}`;st.className='import-status err';st.style.display='block';}};rd.readAsText(f,'UTF-8');}

// Lê CSV colado como texto
function lerCSVPaste(tipo, texto) {
  const st = document.getElementById('status-' + tipo);
  if (!texto || !texto.trim()) { IMPORT_CSVS[tipo] = null; if(st){st.style.display='none';} return; }
  try {
    const p = parseCSV(texto);
    p.forEach(r => Object.keys(r).forEach(k => { if(typeof r[k]==='string') r[k]=r[k].replace(/\\n/g,'\n'); }));
    IMPORT_CSVS[tipo] = p;
    if (st) { st.textContent = `✓ ${p.length} linha(s) (texto colado)`; st.className='import-status ok'; st.style.display='block'; }
  } catch(err) {
    if (st) { st.textContent = `✗ ${err.message}`; st.className='import-status err'; st.style.display='block'; }
    IMPORT_CSVS[tipo] = null;
  }
}

function lerAllInOne(input){const f=input.files[0];if(!f)return;const st=document.getElementById('status-allinone'),rd=new FileReader();rd.onload=e=>{try{const secs=parseMultiSection(e.target.result);const ns=Object.keys(secs);if(!ns.length)throw new Error('Nenhuma seção encontrada.');ns.forEach(s=>IMPORT_CSVS[s]=secs[s]);st.textContent=`✓ ${ns.length} seção(ões): ${ns.join(', ')}`;st.className='import-status ok';st.style.display='block';}catch(err){st.textContent=`✗ ${err.message}`;st.className='import-status err';st.style.display='block';}};rd.readAsText(f,'UTF-8');}

// Lê CSV all-in-one colado como texto
function lerAllInOnePaste(texto) {
  const st = document.getElementById('status-allinone');
  if (!texto || !texto.trim()) { if(st) st.style.display='none'; return; }
  try {
    const secs = parseMultiSection(texto);
    const ns = Object.keys(secs);
    if (!ns.length) throw new Error('Nenhuma seção encontrada. Use #SECTION:config, #SECTION:characters…');
    ns.forEach(s => IMPORT_CSVS[s] = secs[s]);
    if (st) { st.textContent = `✓ ${ns.length} seção(ões): ${ns.join(', ')} (texto colado)`; st.className='import-status ok'; st.style.display='block'; }
  } catch(err) {
    if (st) { st.textContent = `✗ ${err.message}`; st.className='import-status err'; st.style.display='block'; }
  }
}

// Lê JSON de mapas via input de arquivo
function lerMapasJSONFile(input) {
  const file = input.files[0];
  if (!file) return;
  const st = document.getElementById('status-mapas');
  const reader = new FileReader();
  reader.onload = e => {
    _processarMapasJSONTexto(e.target.result, st);
  };
  reader.readAsText(file);
}

// Lê JSON de mapas via texto colado
function lerMapasJSONPaste(texto) {
  const st = document.getElementById('status-mapas');
  if (!texto || !texto.trim()) { _mapasImportJSON = null; if(st) st.style.display='none'; return; }
  _processarMapasJSONTexto(texto, st);
}

function _processarMapasJSONTexto(texto, st) {
  try {
    const raw = texto.replace(/^```[a-z]*\n?/,'').replace(/```$/,'').trim();
    const data = JSON.parse(raw);
    const arr = Array.isArray(data) ? data : (data.mapas ? data.mapas : [data]);
    if (!arr.length || !arr[0].map_id) throw new Error('JSON inválido: cada mapa precisa de map_id');
    // Aceita formato SVG+JSON (campo svg) e formato anterior (render_data/img_url)
    const comSvg = arr.filter(m => m.svg && m.svg.includes('<svg')).length;
    _mapasImportJSON = arr;
    const labels = arr.map(m => {
      const visaoIcon = m.visao === 'iso' ? '🔷' : '⬛';
      return `${visaoIcon} ${m.nome||m.map_id}`;
    }).join(', ');
    const svgInfo = comSvg > 0 ? ` · ${comSvg} com SVG` : '';
    if (st) { st.innerHTML = `<span style="color:var(--sucesso)">✓ ${arr.length} mapa(s)${svgInfo}: ${labels}</span>`; st.style.display='block'; }
  } catch(err) {
    if (st) { st.innerHTML = `<span style="color:var(--perigo)">✗ JSON inválido: ${err.message}</span>`; st.style.display='block'; }
    _mapasImportJSON = null;
  }
}

// Importa APENAS os mapas num RPG já existente (sem precisar de CSV)
async function importarSoMapas() {
  const rpgId = document.getElementById('mapas-rpg-select').value;
  const st = document.getElementById('status-mapas');
  const mostrarSt = (msg, tipo) => {
    if (st) { st.innerHTML = `<span style="color:var(--${tipo==='ok'?'sucesso':'perigo'})">${msg}</span>`; st.style.display='block'; }
  };
  if (!rpgId) { mostrarSt('✗ Selecione um RPG antes de importar', 'err'); return; }
  if (!_mapasImportJSON || !_mapasImportJSON.length) { mostrarSt('✗ Nenhum JSON de mapas carregado. Use o arquivo ou cole o texto acima.', 'err'); return; }
  mostrarSt('⏳ Importando mapas…', 'ok');
  try {
    await importarMapasJSON(rpgId, _mapasImportJSON);
    mostrarSt(`✓ ${_mapasImportJSON.length} mapa(s) importado(s) com sucesso!`, 'ok');
    _mapasImportJSON = null;
    document.getElementById('paste-mapas').value = '';
    document.getElementById('file-mapas').value = '';
  } catch(e) {
    mostrarSt(`✗ Erro: ${e.message}`, 'err');
  }
}

function parseMultiSection(text){const res={},lines=text.split(/\r?\n/);let cur=null,buf=[];const flush=()=>{if(cur&&buf.length>1){const p=parseCSV(buf.join('\n'));p.forEach(r=>Object.keys(r).forEach(k=>{if(typeof r[k]==='string')r[k]=r[k].replace(/\\n/g,'\n');}));res[cur]=p;}};lines.forEach(l=>{const m=l.match(/^#SECTION:(\w+)/i);if(m){flush();cur=m[1];buf=[];}else if(!l.startsWith('#')&&l.trim())buf.push(l);});flush();return res;}
function parseCSV(text){const ls=text.trim().split(/\r?\n/);if(!ls.length)return[];const h=parseCSVLine(ls[0]);return ls.slice(1).filter(l=>l.trim()).map(l=>{const v=parseCSVLine(l);const o={};h.forEach((k,i)=>o[k.trim()]=(v[i]||'').trim());return o;});}
function parseCSVLine(line){const r=[];let cur='',inQ=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(inQ&&line[i+1]==='"'){cur+='"';i++;}else inQ=!inQ;}else if(ch===','&&!inQ){r.push(cur);cur='';}else cur+=ch;}r.push(cur);return r;}


async function enviarImport(){
 const btn=document.getElementById('btn-import-submit');
 if(IMPORT_MODE==='atualizar'){
   const rpgId=document.getElementById('rpg-update-select').value;
   if(!rpgId){showSt('status-import','Selecione qual RPG atualizar','err');return;}
   const secs=Object.keys(IMPORT_CSVS).filter(k=>IMPORT_CSVS[k]&&IMPORT_CSVS[k].length);
   if(!secs.length){showSt('status-import','Nenhum arquivo carregado','err');return;}
   btn.disabled=true;btn.textContent='Atualizando...';
   try{const upd=await updateRPG(rpgId,IMPORT_CSVS);showSt('status-import',`✓ Atualizado: ${upd.join(', ')}`,'ok');HUB_DATA.rpgs=await getAllRPGs()||[];setTimeout(fecharImport,2000);}
   catch(e){showSt('status-import',`✗ ${e.message}`,'err');}
   finally{btn.disabled=false;btn.textContent='Atualizar RPG';}
   return;
 }
 if(!IMPORT_CSVS.config||!IMPORT_CSVS.config.length){showSt('status-import','#SECTION:config é obrigatório','err');return;}
 btn.disabled=true;btn.textContent='Importando...';
 try{const rpgId=await importRPG(IMPORT_CSVS, _mapasImportJSON);showSt('status-import',`✓ "${IMPORT_CSVS.config[0].name}" importado!`,'ok');HUB_DATA.rpgs=await getAllRPGs()||[];renderRPGList(HUB_DATA.rpgs);setTimeout(fecharImport,2000);}
 catch(e){showSt('status-import',`✗ ${e.message}`,'err');}
 finally{btn.disabled=false;btn.textContent='Importar RPG';}
}


function showSt(id,msg,tipo){const el=document.getElementById(id);el.textContent=msg;el.className='import-status '+tipo;el.style.display='block';}



